// The portable board file format (.swhiteboard.json) — snapshot, strict validation, and rebuild.
//
// A file is plain JSON:
//   {
//     "format": "swhiteboard",          // magic
//     "schemaVersion": 1,               // bumped on any breaking change; readers reject versions they don't know
//     "app": "S Whiteboard",
//     "exportedAt": "2026-11-24T12:00:00.000Z",
//     "meta": { "title": "...", "bg": "grid", ... },        // board meta (no identity, no secrets)
//     "objectCount": 3,                                      // integrity check
//     "objects": [ { "id", "tool", "color", "width", "points", "text", "dir", "fill", "pr", "t",
//                    ...any layer / transform fields present } ],
//     "roots": { "layers": { "kind": "map", "data": {...} } } // optional, allow-listed extra Y roots
//   }
//
// Privacy: every key that names a device, user, author or secret (author, deviceId, token, session…)
// is stripped on export AND on import, at every depth. The board code (the room's access key) is never
// written. Validation is strict and all-or-nothing: a bad file never touches any board.
import * as Y from 'yjs'

export const FORMAT = 'swhiteboard'
export const SCHEMA_VERSION = 1
export const SUPPORTED_VERSIONS = [1]
export const MAX_BYTES = 20 * 1024 * 1024
export const MAX_OBJECTS = 50000
export const FILE_EXT = '.swhiteboard.json'
const MAX_DEPTH = 8
const MAX_STR = 8 * 1024 * 1024 // a single string (e.g. an embedded image data URL)
const MAX_TITLE = 200

// ---- object types. Other capabilities (images, links, frames…) register theirs so files round-trip.
const BASE_TYPES = ['pen', 'highlighter', 'eraser', 'line', 'arrow', 'rect', 'ellipse', 'text']
const types = new Set(BASE_TYPES)
export function registerObjectType (t) {
  if (typeof t === 'string' && /^[a-z][a-z0-9_-]{0,31}$/i.test(t)) types.add(t)
}
export const knownTypes = () => [...types]
const FREE = new Set(['pen', 'highlighter', 'eraser'])

// ---- extra Y roots that may be carried (layers / scenes). Anything else is never exported.
const ROOT_ALLOW = new Set(['layers', 'scenes'])
export function registerRoot (name) {
  if (typeof name === 'string' && /^[a-z][a-z0-9_-]{0,31}$/i.test(name) && !PRIVATE_KEY_RE.test(name)) ROOT_ALLOW.add(name)
}

// Keys that identify a device/person or carry a secret. Stripped everywhere, never exported.
const PRIVATE_KEY_RE = /^(author|authorid|authorname|device|deviceid|devicekind|deviceinfo|install|installid|installation|clientid|owner|ownerid|user|userid|uid|peer|peerid|me|members|friends|presence|awareness|by)$|token|secret|passw|bearer|session|recovery|credential|apikey|api_key|privatekey|private_key|signature/i
const BAD_KEYS = new Set(['__proto__', 'constructor', 'prototype'])

// ------------------------------------------------------------------ errors
export class BoardFileError extends Error {
  constructor (code, he, detail = '') {
    super(`${code}${detail ? ': ' + detail : ''}`)
    this.name = 'BoardFileError'
    this.code = code
    this.he = he
  }
}
const fail = (code, he, detail) => { throw new BoardFileError(code, he, detail) }
const clip = (s, n = 32) => { s = String(s); return s.length > n ? s.slice(0, n) + '…' : s }

// ------------------------------------------------------------------ sanitize (export side)
function cleanJSON (v, depth = 0) {
  if (v === null) return null
  const t = typeof v
  if (t === 'number') return Number.isFinite(v) ? v : null
  if (t === 'string' || t === 'boolean') return v
  if (t !== 'object' || depth > MAX_DEPTH) return undefined
  if (Array.isArray(v)) return v.map(x => { const c = cleanJSON(x, depth + 1); return c === undefined ? null : c })
  if (ArrayBuffer.isView(v)) return undefined
  const out = {}
  for (const k of Object.keys(v)) {
    if (BAD_KEYS.has(k) || PRIVATE_KEY_RE.test(k)) continue
    const c = cleanJSON(v[k], depth + 1)
    if (c !== undefined) out[k] = c
  }
  return out
}

const toPlain = x => (x instanceof Y.AbstractType ? x.toJSON() : x)

// Snapshot a live Y.Doc into the file object. Never reads awareness/presence (that's where devices live).
export function snapshotDoc (doc) {
  const objects = doc.getArray('strokes').toArray().map(m => cleanJSON(toPlain(m))).filter(o => o && typeof o === 'object' && !Array.isArray(o))
  const meta = cleanJSON(doc.getMap('meta').toJSON()) || {}
  const roots = {}
  for (const name of ROOT_ALLOW) {
    const t = doc.share.get(name)
    if (t instanceof Y.Map) roots[name] = { kind: 'map', data: cleanJSON(t.toJSON()) }
    else if (t instanceof Y.Array) roots[name] = { kind: 'array', data: cleanJSON(t.toJSON()) }
  }
  const file = {
    format: FORMAT,
    schemaVersion: SCHEMA_VERSION,
    app: 'S Whiteboard',
    exportedAt: new Date().toISOString(),
    meta,
    objectCount: objects.length,
    objects
  }
  if (Object.keys(roots).length) file.roots = roots
  return file
}

// ------------------------------------------------------------------ validate (import side)
function checkValue (v, depth, where) {
  if (v === null) return null
  switch (typeof v) {
    case 'number':
      if (!Number.isFinite(v)) fail('non-finite', `הקובץ מכיל מספר לא תקין (${where})`, where)
      return v
    case 'string':
      if (v.length > MAX_STR) fail('string-too-long', `הקובץ מכיל טקסט ארוך מדי (${where})`, where)
      return v
    case 'boolean':
      return v
    case 'object': {
      if (depth > MAX_DEPTH) fail('too-deep', `מבנה הקובץ עמוק מדי (${where})`, where)
      if (Array.isArray(v)) {
        const out = new Array(v.length)
        for (let i = 0; i < v.length; i++) out[i] = checkValue(v[i], depth + 1, where)
        return out
      }
      const proto = Object.getPrototypeOf(v)
      if (proto !== Object.prototype && proto !== null) fail('bad-value', `ערך לא תקין בקובץ (${where})`, where)
      const out = {}
      for (const k of Object.keys(v)) {
        if (BAD_KEYS.has(k)) fail('bad-key', `שם שדה אסור בקובץ: "${clip(k)}" (${where})`, where)
        if (PRIVATE_KEY_RE.test(k)) continue // identity / secret: dropped, never imported
        out[k] = checkValue(v[k], depth + 1, where)
      }
      return out
    }
    default:
      fail('bad-value', `ערך לא תקין בקובץ (${where})`, where)
  }
}

const isPlainObj = v => !!v && typeof v === 'object' && !Array.isArray(v)

function checkObject (raw, i) {
  const where = `אובייקט #${i + 1}`
  if (!isPlainObj(raw)) fail('bad-object', `${where} אינו אובייקט תקין`, where)
  const o = checkValue(raw, 1, where)
  if (typeof o.tool !== 'string' || !o.tool) fail('no-type', `ל${where} אין סוג (tool)`, where)
  if (!types.has(o.tool)) fail('unknown-type', `סוג אובייקט לא מוכר: "${clip(o.tool)}" (${where})`, o.tool)
  if ('points' in o) {
    if (!Array.isArray(o.points) || o.points.some(n => typeof n !== 'number')) fail('bad-points', `נקודות לא תקינות ב${where}`, where)
  }
  if ('width' in o && (typeof o.width !== 'number' || o.width <= 0 || o.width > 100000)) fail('bad-width', `עובי לא תקין ב${where}`, where)
  if ('color' in o && (typeof o.color !== 'string' || o.color.length > 64)) fail('bad-color', `צבע לא תקין ב${where}`, where)
  if ('text' in o && typeof o.text !== 'string') fail('bad-text', `טקסט לא תקין ב${where}`, where)
  if (o.id != null && (typeof o.id !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(o.id))) delete o.id // re-minted on import
  return o
}

// Validate a parsed file object. Returns a clean, normalized copy (identity keys stripped) or throws BoardFileError.
export function validateBoard (obj) {
  if (!isPlainObj(obj)) fail('not-board', 'זה לא קובץ לוח של S Whiteboard')
  if (obj.format !== FORMAT) fail('not-board', 'זה לא קובץ לוח של S Whiteboard (חסר הסימון "swhiteboard")')
  const v = obj.schemaVersion
  if (typeof v !== 'number' || !Number.isInteger(v) || v < 1) fail('bad-version', 'גרסת הקובץ חסרה או לא תקינה')
  if (v > Math.max(...SUPPORTED_VERSIONS)) fail('newer-version', `הקובץ נשמר בגרסה חדשה יותר (גרסה ${v}) — עדכנו את האפליקציה ונסו שוב`, String(v))
  if (!SUPPORTED_VERSIONS.includes(v)) fail('unsupported-version', `גרסת הקובץ (${v}) אינה נתמכת`, String(v))
  if (!Array.isArray(obj.objects)) fail('no-objects', 'בקובץ חסרה רשימת האובייקטים')
  if (obj.objects.length > MAX_OBJECTS) fail('too-many', `יותר מדי אובייקטים בקובץ (${obj.objects.length.toLocaleString('he-IL')}; המקסימום ${MAX_OBJECTS.toLocaleString('he-IL')})`)
  if (obj.objectCount != null && obj.objectCount !== obj.objects.length) fail('count-mismatch', 'הקובץ פגום — מספר האובייקטים לא תואם')
  const objects = obj.objects.map(checkObject)

  const meta = {}
  if (obj.meta != null) {
    if (!isPlainObj(obj.meta)) fail('bad-meta', 'פרטי הלוח (meta) בקובץ לא תקינים')
    const m = checkValue(obj.meta, 1, 'meta')
    for (const [k, val] of Object.entries(m)) {
      if (val === null || ['string', 'number', 'boolean'].includes(typeof val)) meta[k] = val
    }
    if ('title' in meta) meta.title = typeof meta.title === 'string' ? meta.title.slice(0, MAX_TITLE) : ''
    if ('bg' in meta && typeof meta.bg !== 'string') delete meta.bg
  }

  let roots = null
  if (obj.roots != null) {
    if (!isPlainObj(obj.roots)) fail('bad-roots', 'שכבות/סצנות בקובץ לא תקינות')
    roots = {}
    for (const name of Object.keys(obj.roots)) {
      if (BAD_KEYS.has(name) || !ROOT_ALLOW.has(name)) fail('unknown-root', `סוג נתונים לא מוכר בקובץ: "${clip(name)}"`, name)
      const r = obj.roots[name]
      if (!isPlainObj(r) || (r.kind !== 'map' && r.kind !== 'array')) fail('bad-roots', `נתוני "${clip(name)}" בקובץ לא תקינים`, name)
      const data = checkValue(r.data, 1, name)
      if (r.kind === 'map' ? !isPlainObj(data) : !Array.isArray(data)) fail('bad-roots', `נתוני "${clip(name)}" בקובץ לא תקינים`, name)
      roots[name] = { kind: r.kind, data }
    }
  }
  return { format: FORMAT, schemaVersion: SCHEMA_VERSION, meta, objects, roots }
}

// Parse + validate raw text (the whole file). Throws BoardFileError with a Hebrew `.he` message.
export function parseBoardText (text) {
  if (typeof text !== 'string') fail('empty', 'הקובץ ריק')
  if (text.length > MAX_BYTES || (text.length > MAX_BYTES / 4 && new TextEncoder().encode(text).length > MAX_BYTES)) {
    fail('too-big', 'הקובץ גדול מדי (מעל 20MB)')
  }
  if (!text.trim()) fail('empty', 'הקובץ ריק')
  let obj
  try { obj = JSON.parse(text) } catch { fail('not-json', 'הקובץ אינו JSON תקין — ייתכן שהוא פגום או שאינו קובץ לוח') }
  return validateBoard(obj)
}

// Serialize to the file text (after self-validation, so we never write a file we would refuse to read).
export function serializeBoard (file) {
  validateBoard(file)
  const text = JSON.stringify(file)
  if (text.length > MAX_BYTES) fail('too-big', 'הלוח גדול מדי לקובץ (מעל 20MB)')
  return text
}

// ------------------------------------------------------------------ rebuild into a (fresh) Y.Doc
const toY = v => {
  // nested plain objects become Y.Maps (how live roots like layers are shaped); arrays stay JSON
  if (isPlainObj(v)) { const m = new Y.Map(); for (const [k, x] of Object.entries(v)) m.set(k, toY(x)); return m }
  return v
}

const newId = () => {
  const a = new Uint8Array(10)
  crypto.getRandomValues(a)
  let s = ''
  for (const x of a) s += (x & 35).toString(36)
  return s
}

// Fill an EMPTY doc with a validated board. Points of free strokes become Y.Arrays (like live strokes).
export function fillDoc (doc, clean, { title, origin = 'import' } = {}) {
  const strokes = doc.getArray('strokes')
  const meta = doc.getMap('meta')
  const seen = new Set()
  doc.transact(() => {
    const maps = clean.objects.map(o => {
      // never read a prelim (not yet integrated) Y.Map: decide the id from the plain object first
      let id = typeof o.id === 'string' ? o.id : ''
      if (!id || seen.has(id)) id = newId()
      seen.add(id)
      const m = new Y.Map()
      for (const [k, v] of Object.entries(o)) {
        if (k === 'id') continue
        if (k === 'points' && FREE.has(o.tool)) { const a = new Y.Array(); a.push(v); m.set('points', a) } else m.set(k, v)
      }
      m.set('id', id)
      return m
    })
    if (maps.length) strokes.push(maps)
    for (const [k, v] of Object.entries(clean.meta || {})) if (k !== 'created') meta.set(k, v)
    if (title != null) meta.set('title', String(title).slice(0, MAX_TITLE))
    meta.set('created', Date.now())
    if (clean.roots) {
      for (const [name, r] of Object.entries(clean.roots)) {
        if (r.kind === 'map') { const t = doc.getMap(name); for (const [k, v] of Object.entries(r.data)) t.set(k, toY(v)) } else { const t = doc.getArray(name); if (r.data.length) t.push(r.data.map(toY)) }
      }
    }
  }, origin)
}

export function safeFileName (title) {
  const base = String(title || 'board').replace(/[\\/:*?"<>|\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60) || 'board'
  const d = new Date()
  const p = n => String(n).padStart(2, '0')
  return `${base}-${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${FILE_EXT}`
}

// test / devtools handle (pure functions, no state)
try { if (typeof window !== 'undefined') window.__swbFormat = { snapshotDoc, serializeBoard, parseBoardText, fillDoc } } catch {}
