// Awareness-driven UI: remote cursors (DOM overlay), laser trails + eraser ring (fx canvas), device list.
import { h, emitter } from './util.js'

const CURSOR_SVG = c => `<svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 2.8 19.6 10a.9.9 0 0 1-.1 1.7l-6.3 1.9-2.7 6a.9.9 0 0 1-1.7-.1L3 3.9a.8.8 0 0 1 1-1.1Z" fill="${c}" stroke="#fff" stroke-width="1.6" stroke-linejoin="round"/></svg>`
const LASER_LIFE = 1100

export class Presence {
  constructor ({ session, canvas, me, tv = false }) {
    this.session = session
    this.cv = canvas
    this.me = me
    this.tv = tv
    this.ev = emitter()
    this.cursors = new Map() // clientID -> {el, x, y, seen}
    this.trails = new Map() // clientID -> {c, pts:[{x,y,t}], seq}
    this.layer = h('div', { class: 'cursors' + (tv ? ' tv' : '') })
    canvas.overlay.append(this.layer)
    this.users = []

    this._onChange = ({ added, updated, removed }) => {
      for (const id of removed) this._drop(id)
      this._sync([...added, ...updated])
      this._list()
    }
    session.awareness.on('change', this._onChange)
    this._offView = canvas.view.ev.on('change', () => this._place())
    this._offFx = canvas.addFx((ctx, view, dpr, now) => this._paintFx(ctx, view, dpr, now))
    this._gc = setInterval(() => this._sweep(), 4000)
    this._sync([...session.awareness.getStates().keys()])
    this._list()
  }

  _sync (ids) {
    const states = this.session.awareness.getStates()
    const now = performance.now()
    for (const id of ids) {
      if (id === this.session.doc.clientID) continue
      const st = states.get(id)
      if (!st || !st.user) { this._drop(id); continue }
      const u = st.user
      const cur = st.cursor
      let c = this.cursors.get(id)
      if (cur && Number.isFinite(cur.x)) {
        if (!c) {
          const el = h('div', { class: 'rcursor' })
          el.innerHTML = CURSOR_SVG(u.color || '#8b5cf6')
          el.append(h('span', { class: 'rname' }))
          this.layer.append(el)
          c = { el, color: null }
          this.cursors.set(id, c)
        }
        if (c.color !== u.color) {
          c.color = u.color
          c.el.querySelector('path').setAttribute('fill', u.color || '#8b5cf6')
          c.el.style.setProperty('--c', u.color || '#8b5cf6')
        }
        const label = (u.kind === 'tv' ? '📺 ' : '') + (u.name || '')
        const nameEl = c.el.querySelector('.rname')
        if (nameEl.textContent !== label) nameEl.textContent = label
        c.x = cur.x; c.y = cur.y; c.seen = now
        c.el.classList.toggle('down', !!cur.down)
        c.el.classList.remove('gone')
        this._placeOne(c)
      } else if (c) {
        c.el.classList.add('gone')
      }
      // laser
      const L = st.laser
      if (L && Array.isArray(L.p) && L.p.length) {
        let tr = this.trails.get(id)
        if (!tr) { tr = { pts: [], seq: -1, c: L.c || u.color }; this.trails.set(id, tr) }
        if (L.s !== tr.seq) {
          tr.seq = L.s
          tr.c = L.c || u.color
          for (let i = 0; i + 1 < L.p.length; i += 2) tr.pts.push({ x: L.p[i], y: L.p[i + 1], t: now })
          this.cv.requestFx()
        }
      }
    }
  }

  addLocalLaser (x, y) {
    const id = 'local'
    let tr = this.trails.get(id)
    if (!tr) { tr = { pts: [], seq: 0, c: this.me.color }; this.trails.set(id, tr) }
    tr.c = this.me.color
    tr.pts.push({ x, y, t: performance.now() })
    this.cv.requestFx()
  }

  _drop (id) {
    const c = this.cursors.get(id)
    if (c) { c.el.remove(); this.cursors.delete(id) }
    this.trails.delete(id)
  }

  _sweep () {
    const now = performance.now()
    for (const [id, c] of this.cursors) {
      if (now - (c.seen || 0) > 30000) c.el.classList.add('gone')
    }
    const states = this.session.awareness.getStates()
    for (const id of [...this.cursors.keys()]) if (!states.has(id)) this._drop(id)
  }

  _placeOne (c) {
    const [sx, sy] = this.cv.view.toScreen(c.x, c.y)
    c.el.style.transform = `translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px)`
    const off = sx < -40 || sy < -40 || sx > this.cv.W + 40 || sy > this.cv.H + 40
    c.el.classList.toggle('off', off)
  }

  _place () { for (const c of this.cursors.values()) this._placeOne(c) }

  _paintFx (ctx, view, dpr, now) {
    let again = false
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'
    for (const [id, tr] of this.trails) {
      while (tr.pts.length && now - tr.pts[0].t > LASER_LIFE) tr.pts.shift()
      if (!tr.pts.length) { if (id !== 'local') this.trails.delete(id); continue }
      again = true
      const pts = tr.pts
      for (let pass = 0; pass < 2; pass++) {
        for (let i = 1; i < pts.length; i++) {
          const a = pts[i - 1]; const b = pts[i]
          const life = 1 - (now - b.t) / LASER_LIFE
          if (life <= 0) continue
          const [ax, ay] = view.toScreen(a.x, a.y)
          const [bx, by] = view.toScreen(b.x, b.y)
          ctx.globalAlpha = pass ? Math.min(1, life * 1.2) : life * 0.35
          ctx.strokeStyle = pass ? '#fff' : (tr.c || '#ef4444')
          ctx.lineWidth = pass ? 2.2 * life + 0.6 : 11 * life + 3
          ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke()
        }
      }
      const last = pts[pts.length - 1]
      const [lx, ly] = view.toScreen(last.x, last.y)
      const life = 1 - (now - last.t) / LASER_LIFE
      if (life > 0) {
        ctx.globalAlpha = life
        ctx.fillStyle = tr.c || '#ef4444'
        ctx.beginPath(); ctx.arc(lx, ly, 6, 0, Math.PI * 2); ctx.fill()
        ctx.fillStyle = '#fff'
        ctx.beginPath(); ctx.arc(lx, ly, 2.4, 0, Math.PI * 2); ctx.fill()
      }
    }
    ctx.globalAlpha = 1
    return again
  }

  _list () {
    const states = this.session.awareness.getStates()
    const users = []
    for (const [id, st] of states) {
      if (!st || !st.user) continue
      users.push({ id, self: id === this.session.doc.clientID, ...st.user })
    }
    users.sort((a, b) => (b.self - a.self) || String(a.name).localeCompare(String(b.name), 'he'))
    this.users = users
    this.ev.emit('users', users)
  }

  destroy () {
    clearInterval(this._gc)
    try { this.session.awareness.off('change', this._onChange) } catch {}
    this._offView()
    this._offFx()
    this.layer.remove()
  }
}
