// Layered canvas renderer bound to a board session.
//   bg  : background pattern (redrawn on view change / bg change)
//   ink : committed strokes  (static cache + "active" strokes that are still changing)
//   fx  : ephemeral effects (laser trails, eraser ring)
//   overlay (DOM): remote cursors, text editor
import * as Y from 'yjs'
import { View } from './view.js'
import { getEntry, invalidate, drawEntries, drawBackground, isDarkBg, contentBBox } from './render.js'
import { h } from './util.js'

const ACTIVE_MS = 450

export class BoardCanvas {
  constructor (stage, session) {
    this.stage = stage
    this.session = session
    this.view = new View()
    const mk = cls => h('canvas', { class: 'cv ' + cls })
    this.bgCv = mk('cv-bg')
    this.inkCv = mk('cv-ink')
    this.fxCv = mk('cv-fx')
    this.overlay = h('div', { class: 'overlay' })
    stage.append(this.bgCv, this.inkCv, this.fxCv, this.overlay)
    this.bgCtx = this.bgCv.getContext('2d')
    this.inkCtx = this.inkCv.getContext('2d')
    this.fxCtx = this.fxCv.getContext('2d')
    this.staticCv = document.createElement('canvas')
    this.staticCtx = this.staticCv.getContext('2d')
    this.staticValid = false

    this.all = session.strokes.toArray() // every object, array (z) order — what gets rendered
    this.layers = null // [layers] controller set by layers-panel.js: { pick(all), visible(all), render(cv, view, dpr, dark, cull) }
    this.active = new Map()
    this.hidden = new Set()
    this.bgKey = 'white'
    this.dpr = 1
    this.W = 1
    this.H = 1
    this.dirtyBg = true
    this.dirtyStatic = true
    this.raf = 0
    this.fxRaf = 0
    this.fxPainters = new Set()
    this.contentListeners = new Set()
    this._expireTimer = 0
    this._destroyed = false

    this._onDeep = (events) => {
      let structural = false
      for (const ev of events) {
        const t = ev.target
        if (t === session.strokes) structural = true
        else if (t instanceof Y.Map) this._touch(t)
        else if (t instanceof Y.Array) {
          const p = t.parent
          if (p instanceof Y.Map) this._touch(p)
        }
      }
      if (structural) {
        this.all = session.strokes.toArray()
        this.dirtyStatic = true
      }
      this._contentChanged()
      this.schedule()
    }
    session.strokes.observeDeep(this._onDeep)

    this.view.ev.on('change', () => {
      this.dirtyBg = true
      this.dirtyStatic = true
      this.schedule()
      this.requestFx()
    })

    this._ro = new ResizeObserver(() => this.resize())
    this._ro.observe(stage)
    this.resize()
  }

  _touch (m) {
    invalidate(m)
    if (!this.active.has(m)) this.dirtyStatic = true // it must leave the static cache
    this.active.set(m, performance.now())
    clearTimeout(this._expireTimer)
    this._expireTimer = setTimeout(() => this.schedule(), ACTIVE_MS + 30)
  }

  _contentChanged () {
    for (const fn of this.contentListeners) fn()
  }

  onContent (fn) { this.contentListeners.add(fn); return () => this.contentListeners.delete(fn) }

  setBackground (key) {
    if (key === this.bgKey) return
    this.bgKey = key
    this.dirtyBg = true
    this.dirtyStatic = true
    this.stage.dataset.bg = key
    this.schedule()
  }

  get dark () { return isDarkBg(this.bgKey) }

  hide (m) { this.hidden.add(m); this.dirtyStatic = true; this.schedule() }
  unhide (m) { this.hidden.delete(m); this.dirtyStatic = true; this.schedule() }

  resize () {
    const r = this.stage.getBoundingClientRect()
    const W = Math.max(1, Math.round(r.width)); const H = Math.max(1, Math.round(r.height))
    let dpr = Math.min(window.devicePixelRatio || 1, 3)
    // big TVs report huge CSS sizes; keep the backing store sane
    while (dpr > 1 && W * H * dpr * dpr > 9e6) dpr -= 0.25
    if (W === this.W && H === this.H && dpr === this.dpr) return
    this.W = W; this.H = H; this.dpr = dpr
    for (const cv of [this.bgCv, this.inkCv, this.fxCv, this.staticCv]) {
      cv.width = Math.round(W * dpr)
      cv.height = Math.round(H * dpr)
    }
    this.staticValid = false
    this.view.resize(W, H)
    this.dirtyBg = true
    this.dirtyStatic = true
    this.render()
    this.requestFx()
  }

  schedule () {
    if (this.raf || this._destroyed) return
    this.raf = requestAnimationFrame(() => { this.raf = 0; this.render() })
  }

  // [layers] `order` = the objects a user may hit-test / erase / select / edit (hidden + locked layers
  // filtered out by the layers controller); without layers it is simply every object.
  get order () { return this.layers ? this.layers.pick(this.all) : this.all }

  entries () { return this.all.map(getEntry) }

  contentBBox () { return contentBBox((this.layers ? this.layers.visible(this.all) : this.all).map(getEntry)) }

  isEmpty () {
    for (const m of this.all) {
      const e = getEntry(m)
      if (e.tool === 'eraser') continue
      if (e.kind === 'text' && !e.text) continue
      return false
    }
    return true
  }

  render () {
    if (this._destroyed) return
    const now = performance.now()
    for (const [m, t] of this.active) {
      if (now - t > ACTIVE_MS) { this.active.delete(m); this.dirtyStatic = true }
    }
    const { view, dpr } = this
    const pw = this.inkCv.width; const ph = this.inkCv.height
    if (this.dirtyBg) {
      drawBackground(this.bgCtx, this.bgKey, view, dpr, pw, ph)
      this.dirtyBg = false
    }
    const dark = this.dark
    const cull = view.worldRect(96)
    const ink = this.inkCtx
    if (this.layers && this.layers.render(this, view, dpr, dark, cull)) return // [layers] per-layer surfaces + opacity
    if (this.active.size === 0) {
      if (this.dirtyStatic) {
        ink.setTransform(1, 0, 0, 1, 0, 0)
        ink.clearRect(0, 0, pw, ph)
        drawEntries(ink, this._visible(null), view, dpr, dark, cull)
        this.dirtyStatic = false
        this.staticValid = false
      }
      return
    }
    if (this.dirtyStatic || !this.staticValid) {
      const sc = this.staticCtx
      sc.setTransform(1, 0, 0, 1, 0, 0)
      sc.clearRect(0, 0, pw, ph)
      drawEntries(sc, this._visible(this.active), view, dpr, dark, cull)
      this.dirtyStatic = false
      this.staticValid = true
    }
    ink.setTransform(1, 0, 0, 1, 0, 0)
    ink.globalCompositeOperation = 'source-over'
    ink.globalAlpha = 1
    ink.clearRect(0, 0, pw, ph)
    ink.drawImage(this.staticCv, 0, 0)
    const act = []
    for (const m of this.all) if (this.active.has(m) && !this.hidden.has(m)) act.push(getEntry(m))
    drawEntries(ink, act, view, dpr, dark, cull)
  }

  _visible (exclude) {
    const out = []
    for (const m of this.all) {
      if (this.hidden.has(m)) continue
      if (exclude && exclude.has(m)) continue
      out.push(getEntry(m))
    }
    return out
  }

  // ---------------------------------------------------------------- fx layer
  addFx (fn) { this.fxPainters.add(fn); this.requestFx(); return () => { this.fxPainters.delete(fn); this.requestFx() } }

  requestFx () {
    if (this.fxRaf || this._destroyed) return
    this.fxRaf = requestAnimationFrame(now => { this.fxRaf = 0; this._renderFx(now) })
  }

  _renderFx (now) {
    const ctx = this.fxCtx
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.clearRect(0, 0, this.fxCv.width, this.fxCv.height)
    let again = false
    for (const p of this.fxPainters) {
      try { if (p(ctx, this.view, this.dpr, now)) again = true } catch (e) { console.warn(e) }
    }
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.globalAlpha = 1
    if (again) this.requestFx()
  }

  destroy () {
    this._destroyed = true
    cancelAnimationFrame(this.raf)
    cancelAnimationFrame(this.fxRaf)
    clearTimeout(this._expireTimer)
    try { this.session.strokes.unobserveDeep(this._onDeep) } catch {}
    try { this._ro.disconnect() } catch {}
    this.view.stopAnim()
  }
}
