// "Me" editor: this device's display name + colour (shown on cursors and the device list).
import { h } from './util.js'
import { modal } from './ui.js'
import { PEOPLE_COLORS, getMe, setMe, KIND_EMOJI } from './prefs.js'

export function avatar (u, size = 30) {
  const name = String(u.name || '?').trim()
  const letter = u.kind === 'tv' ? KIND_EMOJI.tv : Array.from(name)[0] || '?'
  return h('span', { class: 'avatar', style: { '--c': u.color || '#8b5cf6', width: size + 'px', height: size + 'px', fontSize: Math.round(size * 0.48) + 'px' }, title: name }, letter)
}

export function openProfile (onSave) {
  const me = getMe()
  let color = me.color
  const input = h('input', { class: 'field', type: 'text', value: me.auto ? '' : me.name, placeholder: me.name, maxlength: '24', dir: 'auto', autocomplete: 'nickname', enterkeyhint: 'done' })
  const preview = h('div', { class: 'profile-preview' })
  const paint = () => {
    preview.replaceChildren(avatar({ name: input.value || me.name, color }, 56), h('div', { class: 'pp-name' }, input.value || me.name))
    for (const b of swatches.children) b.classList.toggle('sel', b.dataset.c === color)
  }
  const swatches = h('div', { class: 'swatches people' }, PEOPLE_COLORS.map(c =>
    h('button', { class: 'swatch', type: 'button', dataset: { c }, style: { '--c': c }, 'aria-label': c, onclick: () => { color = c; paint() } })
  ))
  input.addEventListener('input', paint)
  let m = null
  const save = () => {
    const next = setMe({ name: (input.value || me.name).trim(), color })
    m.close()
    if (onSave) onSave(next)
  }
  input.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); save() } })
  m = modal({
    title: 'איך יראו אותי · Me',
    body: h('div', { class: 'profile' },
      preview,
      h('label', { class: 'lbl' }, 'השם שלי (יופיע ליד הסמן)'),
      input,
      h('label', { class: 'lbl' }, 'הצבע שלי'),
      swatches
    ),
    actions: [
      { label: 'ביטול', kind: 'ghost' },
      { label: 'שמירה', kind: 'primary', onClick: () => { save(); return false } }
    ]
  })
  paint()
  return m
}
