// Generic UI primitives: toasts, modals, popovers, confirm, spatial (D-pad) navigation.
import { h } from './util.js'
import { icon } from './icons.js'

let layer = null
function uiLayer () {
  if (!layer || !layer.isConnected) {
    layer = h('div', { class: 'ui-layer' })
    document.body.append(layer)
  }
  return layer
}

// Enter transition that never depends on requestAnimationFrame alone: rAF does not fire in a background
// tab, which would leave a freshly opened modal/toast/popover stuck at opacity 0 until the tab is shown.
// Forcing a style flush commits the start state, so adding the class right away still animates.
function enter (el, cls = 'in') {
  void el.offsetWidth
  el.classList.add(cls)
}

// ------------------------------------------------------------------ toast
// Identical toasts never stack: a toast with the same `key` (default: the same text + kind) that is still
// on screen is refreshed in place (timer restarted) instead of adding another copy.
let toastBox = null
const liveToasts = new Map() // key -> { el, close, restart }
export function toast (msg, { action = null, actionLabel = '', timeout = 3200, kind = '', key = null } = {}) {
  if (!toastBox || !toastBox.isConnected) {
    toastBox = h('div', { class: 'toasts', role: 'status', 'aria-live': 'polite' })
    uiLayer().append(toastBox)
    liveToasts.clear()
  }
  const k = key || `${kind}|${msg}`
  const dup = liveToasts.get(k)
  if (dup && dup.el.isConnected && !dup.el.classList.contains('out')) {
    dup.el.querySelector('.toast-msg').textContent = msg
    dup.restart(timeout)
    return dup.close
  }
  const el = h('div', { class: 'toast ' + kind },
    h('span', { class: 'toast-msg' }, msg),
    action ? h('button', { class: 'toast-act', type: 'button', onclick: () => { close(); action() } }, actionLabel) : null
  )
  let timer = 0
  function close () {
    clearTimeout(timer)
    if (liveToasts.get(k) === entry) liveToasts.delete(k)
    el.classList.add('out')
    setTimeout(() => el.remove(), 260)
  }
  function restart (ms) {
    clearTimeout(timer)
    if (ms > 0) timer = setTimeout(close, ms)
  }
  const entry = { el, close, restart }
  liveToasts.set(k, entry)
  toastBox.append(el)
  while (toastBox.children.length > 3) toastBox.firstChild.remove()
  enter(el)
  restart(timeout)
  return close
}

// ------------------------------------------------------------------ modal
const openModals = []
export function modal ({ title = '', body = null, actions = [], className = '', onClose = null, dismissable = true, wide = false } = {}) {
  const prevFocus = document.activeElement
  const card = h('div', { class: 'modal-card ' + (wide ? 'wide ' : '') + className, role: 'dialog', 'aria-modal': 'true', 'aria-label': title || 'dialog' })
  const back = h('div', { class: 'modal-back' }, card)
  if (title || dismissable) {
    card.append(h('div', { class: 'modal-head' },
      h('h2', { class: 'modal-title' }, title),
      dismissable ? h('button', { class: 'icon-btn ghost modal-x', type: 'button', 'aria-label': 'סגור', title: 'סגור · Close', onclick: () => close() }, icon('x')) : null
    ))
  }
  if (body) card.append(h('div', { class: 'modal-body' }, body))
  if (actions.length) {
    card.append(h('div', { class: 'modal-actions' }, actions.map(a =>
      h('button', {
        class: 'btn ' + (a.kind || ''),
        type: 'button',
        autofocus: a.autofocus,
        onclick: async () => { const r = a.onClick ? await a.onClick() : undefined; if (r !== false) close(a.value) }
      }, a.icon ? icon(a.icon) : null, a.label)
    )))
  }
  let closed = false
  let resolveFn
  const done = new Promise(r => { resolveFn = r })
  function onKey (e) {
    if (e.key === 'Escape' && dismissable && openModals[openModals.length - 1] === api) { e.preventDefault(); close() }
  }
  function close (value) {
    if (closed) return
    closed = true
    document.removeEventListener('keydown', onKey, true)
    back.classList.remove('in')
    back.style.pointerEvents = 'none' // never let a fading backdrop swallow the next tap
    const i = openModals.indexOf(api)
    if (i >= 0) openModals.splice(i, 1)
    setTimeout(() => back.remove(), 220)
    if (onClose) onClose(value)
    resolveFn(value)
    try { if (prevFocus && prevFocus.focus) prevFocus.focus({ preventScroll: true }) } catch {}
  }
  back.addEventListener('pointerdown', e => { if (e.target === back && dismissable) close() })
  document.addEventListener('keydown', onKey, true)
  uiLayer().append(back)
  enter(back)
  const f = card.querySelector('[autofocus]') || card.querySelector('input,textarea,.btn.primary,button:not(.modal-x)')
  try { if (f) f.focus({ preventScroll: true }) } catch {}
  const api = { el: card, close, done }
  openModals.push(api)
  return api
}
export const anyModalOpen = () => openModals.length > 0

export function confirmDialog ({ title, text, okLabel = 'אישור', cancelLabel = 'ביטול', danger = false, icon: ic = null }) {
  const m = modal({
    title,
    body: h('p', { class: 'modal-text' }, text),
    actions: [
      { label: cancelLabel, value: false, kind: 'ghost' },
      { label: okLabel, value: true, kind: danger ? 'danger' : 'primary', autofocus: true, icon: ic }
    ]
  })
  return m.done.then(v => v === true)
}

export function promptDialog ({ title, value = '', placeholder = '', okLabel = 'שמור', maxLength = 60 }) {
  const input = h('input', { class: 'field', type: 'text', value, placeholder, maxlength: String(maxLength), dir: 'auto', enterkeyhint: 'done', autocomplete: 'off' })
  let m = null
  input.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); m.close(input.value) } })
  m = modal({
    title,
    body: input,
    actions: [
      { label: 'ביטול', value: null, kind: 'ghost' },
      { label: okLabel, kind: 'primary', onClick: () => { m.close(input.value); return false } }
    ]
  })
  requestAnimationFrame(() => { try { input.focus(); input.select() } catch {} })
  return m.done.then(v => (v == null ? null : String(v)))
}

// ------------------------------------------------------------------ popover
let currentPop = null
let lastOutsideClose = 0
export function closePopover () { if (currentPop) currentPop.close() }
export const popoverOpen = () => !!currentPop
// true right after a popover was dismissed by tapping outside it (so that tap doesn't also draw a dot)
export const popoverJustClosed = () => performance.now() - lastOutsideClose < 120

export function popover (anchor, content, { placement = 'auto', className = '', onClose = null, sheetOnPhone = false } = {}) {
  if (currentPop && currentPop.anchor === anchor) { currentPop.close(); return null }
  closePopover()
  const asSheet = sheetOnPhone && innerWidth < 560
  const el = h('div', { class: 'popover ' + (asSheet ? 'sheet ' : '') + className, role: 'dialog' }, content)
  uiLayer().append(el)
  anchor.classList.add('popped')
  anchor.setAttribute('aria-expanded', 'true')
  const place = () => {
    if (asSheet) return
    const r = anchor.getBoundingClientRect()
    const m = 10
    const spaceBelow = innerHeight - r.bottom - m - 8; const spaceAbove = r.top - m - 8
    let below = placement === 'below' || (placement === 'auto' && spaceBelow > spaceAbove)
    el.style.maxHeight = ''
    let ph = el.offsetHeight
    // flip when the preferred side is much too small, then cap to the space we have (content scrolls)
    if (below && ph > spaceBelow && spaceAbove > spaceBelow * 1.4) below = false
    else if (!below && ph > spaceAbove && spaceBelow > spaceAbove * 1.4) below = true
    const avail = Math.max(160, below ? spaceBelow : spaceAbove)
    if (ph > avail) { el.style.maxHeight = avail + 'px'; ph = avail }
    const pw = el.offsetWidth
    const top = below ? r.bottom + m : r.top - ph - m
    let left = r.left + r.width / 2 - pw / 2
    left = Math.max(8, Math.min(left, innerWidth - pw - 8))
    el.style.top = Math.max(8, top) + 'px'
    el.style.left = left + 'px'
    el.dataset.side = below ? 'below' : 'above'
  }
  place()
  enter(el)
  const onDown = e => {
    if (el.contains(e.target) || anchor.contains(e.target)) return
    lastOutsideClose = performance.now()
    close()
  }
  const onKey = e => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(); try { anchor.focus() } catch {} } }
  const onResize = () => place()
  setTimeout(() => {
    document.addEventListener('pointerdown', onDown, true)
  }, 0)
  document.addEventListener('keydown', onKey, true)
  addEventListener('resize', onResize)
  let closed = false
  function close () {
    if (closed) return
    closed = true
    document.removeEventListener('pointerdown', onDown, true)
    document.removeEventListener('keydown', onKey, true)
    removeEventListener('resize', onResize)
    anchor.classList.remove('popped')
    anchor.setAttribute('aria-expanded', 'false')
    el.classList.remove('in')
    el.style.pointerEvents = 'none'
    setTimeout(() => el.remove(), 180)
    if (currentPop === api) currentPop = null
    if (onClose) onClose()
  }
  const api = { el, anchor, close, place }
  currentPop = api
  return api
}

// ------------------------------------------------------------------ spatial navigation (TV remote D-pad)
export function spatialMove (root, dir) {
  const items = [...root.querySelectorAll('button:not([disabled]),[tabindex="0"],input,a[href]')]
    .filter(el => el.offsetParent !== null || el.getClientRects().length)
  if (!items.length) return false
  const cur = document.activeElement
  if (!cur || !items.includes(cur)) { items[0].focus(); return true }
  const r = cur.getBoundingClientRect()
  const cx = r.left + r.width / 2; const cy = r.top + r.height / 2
  let best = null; let bestScore = Infinity
  for (const el of items) {
    if (el === cur) continue
    const q = el.getBoundingClientRect()
    const qx = q.left + q.width / 2; const qy = q.top + q.height / 2
    const dx = qx - cx; const dy = qy - cy
    let primary, secondary
    if (dir === 'left') { if (dx >= -2) continue; primary = -dx; secondary = Math.abs(dy) }
    else if (dir === 'right') { if (dx <= 2) continue; primary = dx; secondary = Math.abs(dy) }
    else if (dir === 'up') { if (dy >= -2) continue; primary = -dy; secondary = Math.abs(dx) }
    else { if (dy <= 2) continue; primary = dy; secondary = Math.abs(dx) }
    const score = primary + secondary * 2.2
    if (score < bestScore) { bestScore = score; best = el }
  }
  if (best) { best.focus(); return true }
  return false
}

export function iconButton (name, label, onClick, { cls = '', title = '', id = null } = {}) {
  return h('button', {
    class: 'icon-btn ' + cls,
    type: 'button',
    id,
    'aria-label': label,
    title: title || label,
    onclick: onClick
  }, icon(name))
}
