// Pointer + wheel input: drawing tools, stroke eraser, shapes, text taps, laser, pan & pinch-zoom.
import * as Y from 'yjs'
import { getEntry, hitEntry } from './render.js'
import { rid, emitter, isTypingTarget } from './util.js'
import { widthKey } from './prefs.js'

const FREE_TOOLS = new Set(['pen', 'highlighter', 'eraser'])
const SHAPE_TOOLS = new Set(['line', 'arrow', 'rect', 'ellipse'])
const COMMIT_MOVE_PX = 3
const COMMIT_DELAY_MS = 70
const CANCEL_AGE_MS = 260

// Quantise to a power-of-two step relative to zoom: compact (float32/varint) and precise enough.
function quantStep (s) {
  const q = Math.pow(2, Math.floor(Math.log2(0.5 / s)))
  return Math.min(4, Math.max(1 / 64, q))
}
const quant = (v, q) => Math.round(v / q) * q

export class Input {
  constructor ({ stage, canvas, session, settings, me, tv = false }) {
    this.stage = stage
    this.cv = canvas
    this.view = canvas.view
    this.session = session
    this.settings = settings
    this.me = me
    this.tv = tv
    this.ev = emitter()
    this.pointers = new Map() // id -> {x, y, type}
    this.gesture = null // current single-pointer action
    this.pinch = null
    this.ignoreUntilAllUp = false
    this.penSeen = false
    this.spaceDown = false
    this.enabled = true
    this.textEditor = null // set by board (TextEditor)
    this.lastCursorSend = 0
    this.lastLaserSend = 0
    this.laserBuf = []
    this.hover = null // {x,y} screen, for eraser ring

    this._bind()
  }

  get tool () { return this.settings.tool }

  widthPx (tool = this.tool) { return this.settings.widths[widthKey(tool)] || 4 }

  // ---------------------------------------------------------------- binding
  _bind () {
    const st = this.stage
    this._down = e => this.onDown(e)
    this._move = e => this.onMove(e)
    this._up = e => this.onUp(e)
    this._cancel = e => this.onUp(e, true)
    this._leave = e => this.onLeave(e)
    this._wheel = e => this.onWheel(e)
    this._ctx = e => e.preventDefault()
    this._gesture = e => e.preventDefault()
    st.addEventListener('pointerdown', this._down)
    st.addEventListener('pointermove', this._move)
    st.addEventListener('pointerup', this._up)
    st.addEventListener('pointercancel', this._cancel)
    st.addEventListener('pointerleave', this._leave)
    st.addEventListener('wheel', this._wheel, { passive: false })
    st.addEventListener('contextmenu', this._ctx)
    // Safari pinch "gesture" events would zoom the whole page
    st.addEventListener('gesturestart', this._gesture)
    st.addEventListener('gesturechange', this._gesture)
    // iOS: stop the double-tap magnifier / scroll on the stage
    st.addEventListener('touchstart', this._touchBlock = e => { if (e.cancelable && !isTypingTarget(e.target)) e.preventDefault() }, { passive: false })
  }

  destroy () {
    const st = this.stage
    st.removeEventListener('pointerdown', this._down)
    st.removeEventListener('pointermove', this._move)
    st.removeEventListener('pointerup', this._up)
    st.removeEventListener('pointercancel', this._cancel)
    st.removeEventListener('pointerleave', this._leave)
    st.removeEventListener('wheel', this._wheel)
    st.removeEventListener('contextmenu', this._ctx)
    st.removeEventListener('gesturestart', this._gesture)
    st.removeEventListener('gesturechange', this._gesture)
    st.removeEventListener('touchstart', this._touchBlock)
    this.endGesture(true)
  }

  local (e) {
    const r = this.stage.getBoundingClientRect()
    return [e.clientX - r.left, e.clientY - r.top]
  }

  // ---------------------------------------------------------------- pointer events
  onDown (e) {
    if (!this.enabled) return
    // A pointer whose pointerup we never saw (released outside the window, lost capture, a devtools or
    // screenshot hiccup...) must not swallow this new stroke. A mouse or pen has one contact at a time,
    // so any leftover entry of the same type, or of the same id, is stale: finish it first.
    for (const [id, p] of [...this.pointers]) {
      if (id === e.pointerId || (e.pointerType !== 'touch' && p.type === e.pointerType)) this.dropStale(id)
    }
    if (this.textEditor && this.textEditor.active) {
      // tapping the canvas while typing commits the text and consumes the tap
      this.textEditor.commit()
      this.ignoreUntilAllUp = true
    }
    const [x, y] = this.local(e)
    this.pointers.set(e.pointerId, { x, y, type: e.pointerType, t: performance.now() })
    try { this.stage.setPointerCapture(e.pointerId) } catch {}
    // The tap that dismissed a popover must not leave a dot, but a real stroke still draws: mark the
    // gesture so a pointerup without movement is dropped instead of committed (see endGesture).
    const dismissTap = !!(this.blockDown && this.blockDown())
    if (e.pointerType === 'pen' && !this.penSeen) {
      this.penSeen = true
      this.ev.emit('pen-detected')
    }
    this.ev.emit('interact')
    if (this.ignoreUntilAllUp) return

    const touches = [...this.pointers.entries()].filter(([, p]) => p.type === 'touch')
    if (e.pointerType === 'touch' && touches.length >= 2) {
      // second finger: abandon a young stroke and start pinch/pan
      if (this.gesture) this.endGesture(true, true)
      const [a, b] = touches.slice(-2)
      this.startPinch(a[0], b[0])
      return
    }
    if (this.pinch || this.gesture) return

    const mousePan = e.pointerType === 'mouse' && (e.button === 1 || e.button === 2)
    const touchPans = e.pointerType === 'touch' && this.tool !== 'select' && (this.penSeen || !this.settings.fingerDraws) // [selection] a finger always selects
    // TV mode draws too (touch TVs, a laptop on HDMI, a pointer remote); its bar toggles pen <-> hand.
    if (mousePan || this.spaceDown || this.tool === 'hand' || touchPans) {
      this.gesture = { kind: 'pan', id: e.pointerId, lx: x, ly: y }
      this.stage.classList.add('panning')
      return
    }
    if (e.pointerType === 'mouse' && e.button !== 0) return
    this.startTool(e, x, y)
    if (dismissTap && this.gesture) this.gesture.dismissTap = true
  }

  onMove (e) {
    const p = this.pointers.get(e.pointerId)
    const [x, y] = this.local(e)
    if (e.pointerType !== 'touch') {
      this.hover = { x, y }
      if (this.tool === 'eraser' || this.tool === 'laser') this.cv.requestFx()
      this.sendCursor(x, y)
    }
    if (!p) return
    p.x = x; p.y = y
    if (this.pinch) { this.movePinch(); return }
    const g = this.gesture
    if (!g || g.id !== e.pointerId) return
    // Mouse button already released but the pointerup never arrived: end the gesture here instead of
    // letting a hover keep extending the stroke. Only trusted once this gesture has reported pressed
    // buttons on a move (some synthetic/odd sources always send buttons=0).
    if (e.pointerType === 'mouse') {
      if (e.buttons) g.sawButtons = true
      else if (g.sawButtons) { this.dropStale(e.pointerId); return }
    }
    if (e.pointerType === 'touch') this.sendCursor(x, y)
    switch (g.kind) {
      case 'pan':
        this.view.panBy(x - g.lx, y - g.ly)
        g.lx = x; g.ly = y
        break
      case 'free': this.moveFree(e, g); break
      case 'erase': this.moveErase(g, x, y); break
      case 'shape': this.moveShape(g, x, y, e); break
      case 'laser': this.moveLaser(g, x, y); break
      case 'select': if (this.selection) this.selection.move(e, x, y); break // selection.js hook
      case 'tap':
        if (Math.hypot(x - g.sx, y - g.sy) > 10) g.moved = true
        break
    }
  }

  onUp (e, cancelled = false) {
    const p = this.pointers.get(e.pointerId)
    this.pointers.delete(e.pointerId)
    try { this.stage.releasePointerCapture(e.pointerId) } catch {}
    if (this.pinch) {
      if (this.pinch.a === e.pointerId || this.pinch.b === e.pointerId) {
        this.pinch = null
        this.ignoreUntilAllUp = this.pointers.size > 0
        this.ev.emit('view-gesture-end')
      }
    } else if (this.gesture && this.gesture.id === e.pointerId) {
      if (p) {
        const g = this.gesture
        if (g.kind === 'free' && !cancelled) this.moveFree(e, g)
      }
      this.endGesture(cancelled)
    }
    if (this.pointers.size === 0) {
      this.ignoreUntilAllUp = false
      this.stage.classList.remove('panning')
    }
    if (e.pointerType === 'touch') this.clearCursorSoon()
  }

  // Forget a pointer whose pointerup was lost, committing whatever it had drawn so far.
  dropStale (id) {
    this.pointers.delete(id)
    try { this.stage.releasePointerCapture(id) } catch {}
    if (this.pinch && (this.pinch.a === id || this.pinch.b === id)) this.pinch = null
    const g = this.gesture
    if (g && g.id === id) {
      if (g.kind === 'free') this.flushFree(g)
      this.endGesture(g.kind === 'tap') // keep what was drawn; a half-seen text tap is dropped, not opened
    }
    if (this.pointers.size === 0) {
      this.ignoreUntilAllUp = false
      this.stage.classList.remove('panning')
    }
  }

  onLeave (e) {
    if (e.pointerType === 'mouse') {
      this.hover = null
      this.cv.requestFx()
      if (!this.pointers.size) this.session.setPresenceField('cursor', null)
    }
  }

  // ---------------------------------------------------------------- wheel / trackpad
  onWheel (e) {
    if (!this.enabled) return
    e.preventDefault()
    const [x, y] = this.local(e)
    let dx = e.deltaX; let dy = e.deltaY
    if (e.deltaMode === 1) { dx *= 16; dy *= 16 } else if (e.deltaMode === 2) { dx *= this.view.w; dy *= this.view.h }
    // Mouse wheel (coarse integer notches, no horizontal) zooms; trackpad two-finger scroll pans.
    // Any trackpad-looking event marks the device as a trackpad for a moment so a fast fling never zooms.
    const now = performance.now()
    const trackpadish = e.deltaX !== 0 || !Number.isInteger(e.deltaY) || Math.abs(e.deltaY) < 40
    if (trackpadish && e.deltaMode === 0) this._trackpadUntil = now + 900
    const mouseWheel = !e.shiftKey && (e.deltaMode === 1 || (!trackpadish && !(this._trackpadUntil > now)))
    if (e.ctrlKey || e.metaKey || mouseWheel) {
      const k = Math.exp(-dy * (e.ctrlKey ? 0.0105 : 0.0022))
      this.view.zoomAt(x, y, Math.min(1.6, Math.max(0.6, k)))
    } else if (e.shiftKey && !dx) {
      this.view.panBy(-dy, 0)
    } else {
      this.view.panBy(-dx, -dy)
    }
    this.ev.emit('interact')
  }

  // ---------------------------------------------------------------- pinch
  startPinch (a, b) {
    const pa = this.pointers.get(a); const pb = this.pointers.get(b)
    this.pinch = {
      a, b,
      mx: (pa.x + pb.x) / 2,
      my: (pa.y + pb.y) / 2,
      d: Math.max(10, Math.hypot(pa.x - pb.x, pa.y - pb.y))
    }
    this.session.setPresenceField('cursor', null)
  }

  movePinch () {
    const P = this.pinch
    const pa = this.pointers.get(P.a); const pb = this.pointers.get(P.b)
    if (!pa || !pb) return
    const mx = (pa.x + pb.x) / 2; const my = (pa.y + pb.y) / 2
    const d = Math.max(10, Math.hypot(pa.x - pb.x, pa.y - pb.y))
    const v = this.view
    // zoom about the previous midpoint, then follow the midpoint
    const k = d / P.d
    const [wx, wy] = v.toWorld(P.mx, P.my)
    const s = Math.min(24, Math.max(0.05, v.s * k))
    v.set(s, mx - wx * s, my - wy * s, { user: true })
    P.mx = mx; P.my = my; P.d = d
  }

  // ---------------------------------------------------------------- tools
  startTool (e, x, y) {
    const tool = this.tool
    // SELECT tool hook: selection.js owns the whole gesture (pick / marquee / move / resize)
    if (tool === 'select' && this.selection) {
      this.gesture = { kind: 'select', id: e.pointerId }
      this.selection.down(e, x, y)
      return
    }
    if (this.canDraw && !this.canDraw(tool, this.settings.eraserMode)) return // [layers] locked / hidden active layer
    const [wx, wy] = this.view.toWorld(x, y)
    if (FREE_TOOLS.has(tool) && !(tool === 'eraser' && this.settings.eraserMode === 'stroke')) {
      const pr = e.pointerType === 'pen' && tool === 'pen'
      this.gesture = {
        kind: 'free', id: e.pointerId, tool, pr,
        t0: performance.now(), sx: x, sy: y,
        buf: [], m: null, arr: null, lastX: NaN, lastY: NaN,
        q: quantStep(this.view.s)
      }
      this.addFreePoint(this.gesture, wx, wy, e.pressure)
      return
    }
    if (tool === 'eraser') {
      this.session.undo.stopCapturing()
      this.gesture = { kind: 'erase', id: e.pointerId, lx: x, ly: y, erased: 0 }
      this.moveErase(this.gesture, x, y)
      return
    }
    if (SHAPE_TOOLS.has(tool)) {
      this.gesture = { kind: 'shape', id: e.pointerId, tool, sx: x, sy: y, wx, wy, m: null, q: quantStep(this.view.s), t0: performance.now() }
      return
    }
    if (tool === 'text') {
      this.gesture = { kind: 'tap', id: e.pointerId, sx: x, sy: y, moved: false, tool }
      return
    }
    if (tool === 'laser') {
      this.gesture = { kind: 'laser', id: e.pointerId }
      this.moveLaser(this.gesture, x, y)
    }
  }

  endGesture (cancelled = false, byPinch = false) {
    const g = this.gesture
    this.gesture = null
    if (!g) return
    if (g.kind === 'free') {
      if (cancelled && byPinch && (performance.now() - g.t0 < CANCEL_AGE_MS || !g.m)) this.abortStroke(g)
      else if (!g.m && g.buf.length && !byPinch && !g.dismissTap) this.commitFree(g) // a tap = a dot
      this.session.undo.stopCapturing()
    } else if (g.kind === 'shape') {
      if (cancelled && byPinch && g.m) this.abortStroke(g)
      this.session.undo.stopCapturing()
    } else if (g.kind === 'erase') {
      this.session.undo.stopCapturing()
      if (g.erased) this.ev.emit('erased', g.erased)
    } else if (g.kind === 'tap') {
      if (!cancelled && !g.moved && !g.dismissTap && this.textEditor) {
        const [wx, wy] = this.view.toWorld(g.sx, g.sy)
        const hit = this.hitText(wx, wy)
        if (hit) this.textEditor.edit(hit)
        else this.textEditor.create(wx, wy)
      }
    } else if (g.kind === 'laser') {
      this.flushLaser(true)
    } else if (g.kind === 'select') {
      if (this.selection) this.selection.up(cancelled) // selection.js hook
    }
    this.cv.requestFx()
  }

  // ---- freehand
  addFreePoint (g, wx, wy, pressure) {
    const q = g.q
    const x = quant(wx, q); const y = quant(wy, q)
    const minD = 0.9 / this.view.s
    if (Number.isFinite(g.lastX) && Math.hypot(x - g.lastX, y - g.lastY) < minD) return false
    g.lastX = x; g.lastY = y
    if (g.pr) {
      const p = pressure > 0 ? Math.round(Math.min(1, pressure) * 64) / 64 : 0.5
      g.buf.push(x, y, p)
    } else g.buf.push(x, y)
    return true
  }

  moveFree (e, g) {
    const evs = typeof e.getCoalescedEvents === 'function' ? e.getCoalescedEvents() : null
    const list = evs && evs.length ? evs : [e]
    const r = this.stage.getBoundingClientRect()
    for (const ce of list) {
      const [wx, wy] = this.view.toWorld(ce.clientX - r.left, ce.clientY - r.top)
      this.addFreePoint(g, wx, wy, ce.pressure)
    }
    if (!g.m) {
      const [x, y] = this.local(e)
      const moved = Math.hypot(x - g.sx, y - g.sy) >= COMMIT_MOVE_PX
      if (moved || performance.now() - g.t0 > COMMIT_DELAY_MS) this.commitFree(g)
      return
    }
    this.flushFree(g)
  }

  commitFree (g) {
    const { session } = this
    session.undo.stopCapturing()
    const m = new Y.Map()
    const arr = new Y.Array()
    const pts = g.buf.splice(0)
    arr.push(pts)
    const widthWorld = this.widthPx(g.tool) / this.view.s
    m.set('id', rid(10))
    m.set('tool', g.tool)
    m.set('color', g.tool === 'eraser' ? '#000000' : this.settings.color)
    m.set('width', +widthWorld.toFixed(3))
    if (g.pr) m.set('pr', 1)
    m.set('points', arr)
    m.set('author', this.me.id)
    m.set('t', Date.now())
    session.doc.transact(() => session.strokes.push([m]), session.LOCAL)
    g.m = m
    g.arr = arr
    g.undoLen = session.undo.undoStack.length
  }

  flushFree (g) {
    if (!g.arr || !g.buf.length) return
    const pts = g.buf.splice(0)
    this.session.doc.transact(() => g.arr.push(pts), this.session.LOCAL)
  }

  abortStroke (g) {
    const { session } = this
    if (!g.m) return
    const before = (g.undoLen || 1) - 1
    session.doc.transact(() => {
      const i = session.strokes.toArray().indexOf(g.m)
      if (i >= 0) session.strokes.delete(i, 1)
    }, session.LOCAL)
    // drop the (now empty) undo step this stroke created
    const st = session.undo.undoStack
    if (st.length > before) st.splice(before)
    session.undo.stopCapturing()
    this.ev.emit('undo-changed')
  }

  // ---- stroke eraser
  moveErase (g, x, y) {
    const v = this.view
    const r = Math.max(6, this.widthPx('eraser') / 2) / v.s
    const steps = Math.max(1, Math.ceil(Math.hypot(x - g.lx, y - g.ly) / 6))
    const hits = new Set()
    const order = this.cv.order
    for (let k = 1; k <= steps; k++) {
      const sx = g.lx + (x - g.lx) * (k / steps)
      const sy = g.ly + (y - g.ly) * (k / steps)
      const [wx, wy] = v.toWorld(sx, sy)
      for (let i = order.length - 1; i >= 0; i--) {
        const m = order[i]
        if (hits.has(m)) continue
        if (hitEntry(getEntry(m), wx, wy, r)) hits.add(m)
      }
    }
    g.lx = x; g.ly = y
    if (!hits.size) return
    const { session } = this
    session.doc.transact(() => {
      const arr = session.strokes.toArray()
      const idx = []
      for (const m of hits) { const i = arr.indexOf(m); if (i >= 0) idx.push(i) }
      idx.sort((a, b) => b - a)
      for (const i of idx) session.strokes.delete(i, 1)
    }, session.LOCAL)
    g.erased += hits.size
    if (navigator.vibrate) { try { navigator.vibrate(8) } catch {} }
  }

  // ---- shapes
  moveShape (g, x, y, e) {
    if (!g.m && Math.hypot(x - g.sx, y - g.sy) < COMMIT_MOVE_PX) return
    let [wx, wy] = this.view.toWorld(x, y)
    if (e.shiftKey) [wx, wy] = constrain(g.tool, g.wx, g.wy, wx, wy)
    const q = g.q
    const pts = [quant(g.wx, q), quant(g.wy, q), quant(wx, q), quant(wy, q)]
    const { session } = this
    if (!g.m) {
      session.undo.stopCapturing()
      const m = new Y.Map()
      m.set('id', rid(10))
      m.set('tool', g.tool)
      m.set('color', this.settings.color)
      m.set('width', +(this.widthPx(g.tool) / this.view.s).toFixed(3))
      if (this.settings.fill && (g.tool === 'rect' || g.tool === 'ellipse')) m.set('fill', 1)
      m.set('points', pts)
      m.set('author', this.me.id)
      m.set('t', Date.now())
      session.doc.transact(() => session.strokes.push([m]), session.LOCAL)
      g.m = m
      g.undoLen = session.undo.undoStack.length
      return
    }
    session.doc.transact(() => g.m.set('points', pts), session.LOCAL)
  }

  // ---- text
  hitText (wx, wy) {
    const order = this.cv.order
    const pad = 6 / this.view.s
    for (let i = order.length - 1; i >= 0; i--) {
      const e = getEntry(order[i])
      if (e.kind !== 'text' || !e.bbox) continue
      const b = e.bbox
      if (wx >= b.x0 - pad && wx <= b.x1 + pad && wy >= b.y0 - pad && wy <= b.y1 + pad) return order[i]
    }
    return null
  }

  // ---- laser (ephemeral, via awareness)
  moveLaser (g, x, y) {
    const [wx, wy] = this.view.toWorld(x, y)
    this.ev.emit('laser-point', wx, wy)
    this.laserBuf.push(+wx.toFixed(1), +wy.toFixed(1))
    this.flushLaser(false)
  }

  flushLaser (force) {
    const now = performance.now()
    if (!force && now - this.lastLaserSend < 45) {
      clearTimeout(this._laserT)
      this._laserT = setTimeout(() => this.flushLaser(true), 50)
      return
    }
    if (!this.laserBuf.length && !force) return
    this.lastLaserSend = now
    this._laserSeq = (this._laserSeq || 0) + 1
    this.session.setPresenceField('laser', this.laserBuf.length ? { s: this._laserSeq, p: this.laserBuf.splice(0), c: this.me.color } : null)
  }

  // ---- presence cursor
  sendCursor (x, y) {
    const now = performance.now()
    if (now - this.lastCursorSend < 50) {
      clearTimeout(this._curT)
      this._curT = setTimeout(() => this.sendCursor(x, y), 55)
      return
    }
    this.lastCursorSend = now
    const [wx, wy] = this.view.toWorld(x, y)
    this.session.setPresenceField('cursor', { x: Math.round(wx * 10) / 10, y: Math.round(wy * 10) / 10, tool: this.tool, down: !!this.gesture })
  }

  clearCursorSoon () {
    clearTimeout(this._curClear)
    this._curClear = setTimeout(() => {
      if (!this.pointers.size) this.session.setPresenceField('cursor', null)
    }, 1200)
  }
}

function constrain (tool, x0, y0, x1, y1) {
  const dx = x1 - x0; const dy = y1 - y0
  if (tool === 'rect' || tool === 'ellipse') {
    const d = Math.max(Math.abs(dx), Math.abs(dy))
    return [x0 + Math.sign(dx || 1) * d, y0 + Math.sign(dy || 1) * d]
  }
  const a = Math.atan2(dy, dx)
  const snap = Math.round(a / (Math.PI / 12)) * (Math.PI / 12)
  const len = Math.hypot(dx, dy)
  return [x0 + Math.cos(snap) * len, y0 + Math.sin(snap) * len]
}
