// Named saves + board files: "Save as…" snapshots in a local library (IndexedDB "swhiteboard-saves"),
// a this-tab-only session save (sessionStorage), and download / import of .swhiteboard.json files.
//
// Opening anything (a save, the session save, an imported file) ALWAYS forks into a NEW board with a fresh
// code: it seeds that board's local Yjs store and navigates there. The live board is never overwritten,
// and a rejected file changes nothing anywhere.
import * as Y from 'yjs'
import { h, newCode, relTime, ROOM_PREFIX } from './util.js'
import { icon } from './icons.js'
import { toast, modal, confirmDialog, promptDialog } from './ui.js'
import { renderToCanvas } from './render.js'
import { touchRecent } from './prefs.js'
import {
  snapshotDoc, serializeBoard, parseBoardText, validateBoard, fillDoc, safeFileName,
  BoardFileError, MAX_BYTES, MAX_OBJECTS, FILE_EXT
} from './board-format.js'

const DB_NAME = 'swhiteboard-saves'
const DB_VERSION = 1
const S_INDEX = 'index' // light rows for the library list: { id, name, createdAt, objectCount, bytes, thumb, fromTitle }
const S_DATA = 'data' // the board file text, keyed by the same id
const SESSION_KEY = 'swb.sessionSave'

// ------------------------------------------------------------------ errors → Hebrew
const isQuota = e => !!e && (e.name === 'QuotaExceededError' || e.code === 22 || e.code === 1014 || /quota/i.test(String(e.message || '')))
export function errorHe (e) {
  if (e instanceof BoardFileError) return e.he
  if (isQuota(e)) return 'אין מספיק מקום באחסון של הדפדפן — מחקו שמירות ישנות או הורידו את הלוח כקובץ'
  if (e && e.name === 'InvalidStateError') return 'האחסון המקומי לא זמין (מצב גלישה פרטית?)'
  if (e && e.name === 'NotFoundError') return 'השמירה לא נמצאה — אולי נמחקה בלשונית אחרת'
  return 'משהו השתבש: ' + String((e && (e.message || e.name)) || e).slice(0, 120)
}

// ------------------------------------------------------------------ IndexedDB helpers
const req2p = r => new Promise((resolve, reject) => { r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error) })
const tx2p = tx => new Promise((resolve, reject) => {
  tx.oncomplete = () => resolve()
  tx.onerror = () => reject(tx.error)
  tx.onabort = () => reject(tx.error || new DOMException('Transaction aborted', 'AbortError'))
})

let dbp = null
function savesDB () {
  if (dbp) return dbp
  dbp = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') { reject(new DOMException('IndexedDB unavailable', 'InvalidStateError')); return }
    const r = indexedDB.open(DB_NAME, DB_VERSION)
    r.onupgradeneeded = () => {
      const db = r.result
      if (!db.objectStoreNames.contains(S_INDEX)) db.createObjectStore(S_INDEX, { keyPath: 'id' })
      if (!db.objectStoreNames.contains(S_DATA)) db.createObjectStore(S_DATA)
    }
    r.onsuccess = () => {
      const db = r.result
      db.onversionchange = () => { db.close(); dbp = null }
      db.onclose = () => { dbp = null }
      resolve(db)
    }
    r.onerror = () => { dbp = null; reject(r.error) }
    r.onblocked = () => { dbp = null; reject(new DOMException('Saves database is blocked by another tab', 'InvalidStateError')) }
  })
  return dbp
}

export async function listSaves () {
  const db = await savesDB()
  const rows = await req2p(db.transaction(S_INDEX, 'readonly').objectStore(S_INDEX).getAll())
  return rows.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
}

async function putSave (row, text) {
  const db = await savesDB()
  const tx = db.transaction([S_INDEX, S_DATA], 'readwrite')
  const done = tx2p(tx)
  try {
    tx.objectStore(S_DATA).put(text, row.id)
    tx.objectStore(S_INDEX).put(row)
  } catch (e) { try { tx.abort() } catch {} done.catch(() => {}); throw e } // all-or-nothing: no orphan rows
  await done
}

async function readSaveText (id) {
  const db = await savesDB()
  const text = await req2p(db.transaction(S_DATA, 'readonly').objectStore(S_DATA).get(id))
  if (typeof text !== 'string') throw new DOMException('missing', 'NotFoundError')
  return text
}

async function deleteSave (id) {
  const db = await savesDB()
  const tx = db.transaction([S_INDEX, S_DATA], 'readwrite')
  tx.objectStore(S_INDEX).delete(id)
  tx.objectStore(S_DATA).delete(id)
  await tx2p(tx)
}

async function renameSave (id, name) {
  const db = await savesDB()
  const tx = db.transaction(S_INDEX, 'readwrite')
  const st = tx.objectStore(S_INDEX)
  const row = await req2p(st.get(id))
  if (!row) throw new DOMException('missing', 'NotFoundError')
  row.name = name
  st.put(row)
  await tx2p(tx)
}

async function storageInfo () {
  try {
    if (!navigator.storage || !navigator.storage.estimate) return null
    const { usage, quota } = await navigator.storage.estimate()
    return { usage: usage || 0, quota: quota || 0 }
  } catch { return null }
}

// ------------------------------------------------------------------ snapshot helpers
const randomId = () => {
  const a = new Uint8Array(12)
  crypto.getRandomValues(a)
  return Array.from(a, x => x.toString(16).padStart(2, '0')).join('')
}

function thumbOf (objects, bg) {
  try {
    const c = renderToCanvas(objects, bg || 'white', { width: 240, height: 150, pad: 12, maxScale: 1.2 })
    let url = c.toDataURL('image/webp', 0.7)
    if (!url.startsWith('data:image/webp')) url = c.toDataURL('image/jpeg', 0.7)
    return url
  } catch { return '' }
}

// wrapped in a Unicode LTR isolate so "709 B" doesn't flip inside Hebrew text
const fmtBytes = n => '\u2066' + (n < 1024 ? `${n} B` : n < 1048576 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB`) + '\u2069'
const fmtDate = t => { try { return new Date(t).toLocaleString('he-IL', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) } catch { return '' } }

// Build the file text for the live board (validated; identity stripped by board-format).
function fileOf (session) {
  const file = snapshotDoc(session.doc)
  const text = serializeBoard(file)
  return { file, text }
}

// ------------------------------------------------------------------ fork into a NEW board
// Seeds the new room's local store exactly the way y-indexeddb keeps it ("updates" + "custom" stores),
// then the board opens offline-first from it and pushes the content up to the server as usual.
function openRoomDB (name) {
  return new Promise((resolve, reject) => {
    let fresh = false
    const r = indexedDB.open(name)
    r.onupgradeneeded = () => {
      fresh = true
      const db = r.result
      if (!db.objectStoreNames.contains('updates')) db.createObjectStore('updates', { autoIncrement: true })
      if (!db.objectStoreNames.contains('custom')) db.createObjectStore('custom')
    }
    r.onsuccess = () => resolve({ db: r.result, fresh })
    r.onerror = () => reject(r.error)
  })
}

export async function forkToNewBoard (clean, { title } = {}) {
  const doc = new Y.Doc()
  let update
  try {
    fillDoc(doc, clean, { title })
    update = Y.encodeStateAsUpdate(doc)
  } finally { doc.destroy() }
  for (let attempt = 0; attempt < 4; attempt++) {
    const code = newCode()
    const { db, fresh } = await openRoomDB(ROOM_PREFIX + code)
    try {
      if (!fresh) continue // that code already has local data (vanishingly rare): never mix, pick another
      const tx = db.transaction('updates', 'readwrite')
      tx.objectStore('updates').add(update)
      await tx2p(tx)
    } finally { db.close() }
    const name = title != null ? title : (clean.meta && clean.meta.title) || ''
    touchRecent(code, { title: name, n: clean.objects.length, thumb: thumbOf(clean.objects, clean.meta && clean.meta.bg) || undefined })
    return code
  }
  throw new Error('could not allocate a new board code')
}

// ------------------------------------------------------------------ session (this tab only)
function readSession () {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY)
    if (!raw) return null
    const o = JSON.parse(raw)
    return o && typeof o.text === 'string' ? o : null
  } catch { return null }
}

