const UPLOAD_SVG = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m17 8-5-5-5 5"/><path d="M12 3v12"/></svg>'
const SAVE_SVG = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><path d="M17 21v-8H7v8"/><path d="M7 3v5h8"/></svg>'
const svgIcon = s => { const t = document.createElement('template'); t.innerHTML = s; return t.content.firstChild }

// ------------------------------------------------------------------ the panel
// ctx: { app, session, code, titleOf: () => string, bgKey: () => string }
export function openSaves (ctx) {
  ensureStyles()
  const { app, session } = ctx
  let alive = true

  const statusEl = h('div', { class: 'sv-status', role: 'status', 'aria-live': 'polite', 'data-s': 'idle' })
  const setStatus = (s, text) => {
    statusEl.dataset.s = s
    statusEl.replaceChildren(h('span', { class: 'sv-dot' }), h('span', null, text))
  }
  setStatus('idle', 'השמירה האוטומטית במכשיר פעילה · כאן שומרים גרסאות בשם, לשונית וקבצים')

  const act = (ic, he, en, fn, { cls = '', disabled = false, soon = false } = {}) => {
    const b = h('button', { class: 'sv-act ' + cls, type: 'button', 'aria-disabled': disabled ? 'true' : null },
      typeof ic === 'string' ? icon(ic) : ic, h('span', null, he, h('small', null, en)), soon ? h('span', { class: 'sv-soon' }, 'בקרוב') : null)
    b.addEventListener('click', () => { if (!disabled) fn() })
    return b
  }

  const fileInput = h('input', { type: 'file', accept: `${FILE_EXT},.json,application/json`, style: { display: 'none' }, 'aria-hidden': 'true', tabindex: '-1' })
  fileInput.addEventListener('change', () => { const f = fileInput.files && fileInput.files[0]; fileInput.value = ''; if (f) importFile(f) })

  const actions = h('div', { class: 'sv-actions' },
    act(svgIcon(SAVE_SVG), 'שמירה בשם…', 'Save as — library on this device', saveAs, { cls: 'primary' }),
    act('copy', 'שמירה ללשונית הזו', 'Session save — this tab only', saveSession),
    act('download', 'הורדה כקובץ', `Download ${FILE_EXT}`, download),
    act(svgIcon(UPLOAD_SVG), 'פתיחת קובץ…', 'Import file → new board', () => fileInput.click()),
    act('cloud', 'שמירה באינטרנט', 'Online saves — coming soon', () => {}, { disabled: true, soon: true })
  )

  const sessionBox = h('div')
  const listBox = h('div', { class: 'sv-list' })
  const listHead = h('div', { class: 'sv-h' }, h('span', null, 'ספריית השמירות · Library'), h('small'))
  const storageEl = h('p', { class: 'fine' })

  const body = h('div', { class: 'sv-body' }, statusEl, actions, sessionBox, listHead, listBox, storageEl, fileInput)
  const m = modal({ title: 'שמירות וקבצים · Saves & files', body, wide: true, className: 'saves-card', onClose: () => { alive = false } })

  // ---- rendering
  function item ({ thumb, name, sub, note, cls = '', onOpen, extra = [] }) {
    return h('div', { class: 'sv-item ' + cls },
      h('div', { class: 'sv-thumb' + (thumb ? '' : ' none'), style: thumb ? { backgroundImage: `url("${thumb}")` } : null, role: 'img', 'aria-label': 'תצוגה מקדימה' }),
      h('div', { class: 'sv-info' }, h('span', { class: 'sv-name', dir: 'auto', title: name }, name), h('span', { class: 'sv-sub' }, sub), note || null),
      h('div', { class: 'sv-row-acts' },
        h('button', { class: 'btn primary sv-open', type: 'button', onclick: onOpen }, icon('plus'), 'פתיחה כלוח חדש'),
        ...extra)
    )
  }
  const iconBtn = (ic, label, fn, cls = '') => h('button', { class: 'btn icon ' + cls, type: 'button', 'aria-label': label, title: label, onclick: fn }, typeof ic === 'string' ? icon(ic) : ic)

  function paintSession () {
    const s = readSession()
    if (!s) { sessionBox.replaceChildren(); return }
    sessionBox.replaceChildren(
      h('div', { class: 'sv-h' }, h('span', null, 'שמירת לשונית · This tab only')),
      item({
        cls: 'session',
        thumb: s.thumb,
        name: s.name || 'שמירת לשונית',
        sub: `${relTime(s.savedAt)} · ${s.objectCount || 0} אובייקטים`,
        note: h('span', { class: 'sv-tab-note' }, 'נשמר רק בלשונית הזו — ייעלם כשהלשונית תיסגר'),
        onOpen: () => openText(s.text, s.name),
        extra: [iconBtn('trash', 'מחיקת שמירת הלשונית', () => { try { sessionStorage.removeItem(SESSION_KEY) } catch {} paintSession() }, 'ghost')]
      })
    )
  }

  async function paintList () {
    let rows
    try { rows = await listSaves() } catch (e) {
      if (!alive) return
      listBox.replaceChildren(h('div', { class: 'sv-empty' }, 'לא ניתן לקרוא את הספרייה: ' + errorHe(e)))
      setStatus('error', errorHe(e))
      return
    }
    if (!alive) return
    listHead.querySelector('small').textContent = rows.length ? `${rows.length} שמירות` : ''
    if (!rows.length) {
      listBox.replaceChildren(h('div', { class: 'sv-empty' }, 'עוד אין שמירות. "שמירה בשם…" שומרת עותק של הלוח כפי שהוא עכשיו.'))
    } else {
      listBox.replaceChildren(...rows.map(r => item({
        thumb: r.thumb,
        name: r.name,
        sub: h('span', { title: fmtDate(r.createdAt) }, `${relTime(r.createdAt)} · ${r.objectCount} אובייקטים · ${fmtBytes(r.bytes || 0)}`),
        onOpen: () => openSave(r),
        extra: [
          iconBtn('download', 'הורדה כקובץ · Download', () => downloadSave(r)),
          iconBtn('edit', 'שינוי שם · Rename', () => rename(r)),
          iconBtn('trash', 'מחיקה · Delete', () => remove(r), 'ghost')
        ]
      })))
    }
    const info = await storageInfo()
    if (alive && info && info.quota) storageEl.textContent = `אחסון הדפדפן: ${fmtBytes(info.usage)} בשימוש מתוך ${fmtBytes(info.quota)} · השמירות נשמרות במכשיר הזה בלבד`
    else if (alive) storageEl.textContent = 'השמירות נשמרות במכשיר הזה בלבד (בדפדפן הזה).'
  }

  // ---- actions
  async function saveAs () {
    const def = ctx.titleOf()
    const name = await promptDialog({ title: 'שמירה בשם · Save as', value: def, placeholder: 'שם השמירה', okLabel: 'שמירה', maxLength: 80 })
    if (name == null || !alive) return
    const finalName = name.trim() || def
    setStatus('saving', 'שומר…')
    try {
      const { file, text } = fileOf(session)
      const row = {
        id: randomId(),
        name: finalName,
        createdAt: Date.now(),
        objectCount: file.objects.length,
        bytes: text.length,
        thumb: thumbOf(file.objects, file.meta.bg),
        fromTitle: (file.meta.title || '').slice(0, 80)
      }
      await putSave(row, text)
      setStatus('saved', `נשמר ✓ "${finalName}" · ${row.objectCount} אובייקטים`)
      toast('נשמר בספרייה ✓')
      paintList()
    } catch (e) {
      console.warn('[saves] save failed', e)
      setStatus('error', 'השמירה נכשלה — ' + errorHe(e))
    }
  }

  function saveSession () {
    setStatus('saving', 'שומר ללשונית…')
    try {
      const { file, text } = fileOf(session)
      const rec = { name: ctx.titleOf(), savedAt: Date.now(), objectCount: file.objects.length, thumb: thumbOf(file.objects, file.meta.bg), text }
      try { sessionStorage.setItem(SESSION_KEY, JSON.stringify(rec)) } catch (e) {
        if (isQuota(e)) throw Object.assign(new Error('session quota'), { he: 'הלוח גדול מדי לשמירת לשונית — השתמשו ב"שמירה בשם…" או בהורדה כקובץ' })
        throw e
      }
      setStatus('saved', 'נשמר ללשונית ✓ — זמין רק בלשונית הזו עד שתיסגר')
      paintSession()
    } catch (e) {
      setStatus('error', 'שמירת הלשונית נכשלה — ' + (e.he || errorHe(e)))
    }
  }

  function triggerDownload (text, name) {
    const blob = new Blob([text], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = h('a', { href: url, download: name, style: { display: 'none' } })
    document.body.append(a)
    a.click()
    a.remove()
    setTimeout(() => URL.revokeObjectURL(url), 4000)
  }

  function download () {
    try {
      const { file, text } = fileOf(session)
      const name = safeFileName(ctx.titleOf())
      triggerDownload(text, name)
      setStatus('saved', `הקובץ ירד ✓ ${name} · ${file.objects.length} אובייקטים · ${fmtBytes(text.length)}`)
    } catch (e) {
      setStatus('error', 'ההורדה נכשלה — ' + errorHe(e))
    }
  }

  async function downloadSave (r) {
    try {
      const text = await readSaveText(r.id)
      triggerDownload(text, safeFileName(r.name))
      setStatus('saved', `הקובץ ירד ✓ "${r.name}"`)
    } catch (e) { setStatus('error', 'ההורדה נכשלה — ' + errorHe(e)) }
  }

  async function rename (r) {
    const name = await promptDialog({ title: 'שינוי שם · Rename', value: r.name, okLabel: 'שמירה', maxLength: 80 })
    if (name == null || !name.trim() || !alive) return
    try { await renameSave(r.id, name.trim()); setStatus('saved', 'השם עודכן ✓'); paintList() } catch (e) { setStatus('error', errorHe(e)) }
  }

  async function remove (r) {
    const ok = await confirmDialog({ title: 'למחוק את השמירה?', text: `"${r.name}" תימחק מהספרייה במכשיר הזה. הלוחות עצמם לא מושפעים.`, okLabel: 'מחיקה', danger: true, icon: 'trash' })
    if (!ok || !alive) return
    try { await deleteSave(r.id); setStatus('saved', 'השמירה נמחקה'); paintList() } catch (e) { setStatus('error', errorHe(e)) }
  }

  async function openText (text, name) {
    setStatus('saving', 'פותח לוח חדש…')
    try {
      const clean = parseBoardText(text)
      const code = await forkToNewBoard(clean, { title: name != null ? name : undefined })
      m.close()
      app.navigate('/b/' + code)
      toast(`נפתח כלוח חדש · ${clean.objects.length} אובייקטים`, { timeout: 3200 })
    } catch (e) {
      console.warn('[saves] open failed', e)
      setStatus('error', 'הפתיחה נכשלה — ' + errorHe(e))
    }
  }

  async function openSave (r) {
    let text
    try { text = await readSaveText(r.id) } catch (e) { setStatus('error', errorHe(e)); return }
    openText(text, r.name)
  }

  async function importFile (f) {
    setStatus('saving', `בודק את "${f.name}"…`)
    try {
      if (f.size > MAX_BYTES) throw new BoardFileError('too-big', `הקובץ גדול מדי (${fmtBytes(f.size)}; המקסימום 20MB)`)
      if (f.size === 0) throw new BoardFileError('empty', 'הקובץ ריק')
      const text = await f.text()
      const clean = parseBoardText(text)
      const title = (clean.meta.title || '').trim() || f.name.replace(/\.swhiteboard\.json$|\.json$/i, '')
      const code = await forkToNewBoard(clean, { title })
      m.close()
      app.navigate('/b/' + code)
      toast(`הקובץ נפתח כלוח חדש ✓ · ${clean.objects.length} אובייקטים`, { timeout: 3600 })
    } catch (e) {
      console.warn('[saves] import rejected', e)
      setStatus('error', 'הקובץ לא נטען — ' + errorHe(e) + ' · שום לוח לא השתנה')
    }
  }

  paintSession()
  paintList()
  return m
}

// For tests / other capabilities
export const _internal = { validateBoard, MAX_OBJECTS, SESSION_KEY, DB_NAME }
