// Per-device persisted state: identity (name/colour/kind), drawing settings, recent boards, saved views.
import { store, rid, isTVDevice, isTouch } from './util.js'

export const PALETTE = [
  { c: '#1e1e2e', n: 'שחור', en: 'Ink' },
  { c: '#ef4444', n: 'אדום', en: 'Red' },
  { c: '#f97316', n: 'כתום', en: 'Orange' },
  { c: '#eab308', n: 'צהוב', en: 'Yellow' },
  { c: '#22c55e', n: 'ירוק', en: 'Green' },
  { c: '#3b82f6', n: 'כחול', en: 'Blue' },
  { c: '#8b5cf6', n: 'סגול', en: 'Purple' },
  { c: '#ec4899', n: 'ורוד', en: 'Pink' }
]

// Bright, distinct colours for people (cursors, avatars) — readable on light and dark boards.
export const PEOPLE_COLORS = ['#f43f5e', '#f97316', '#eab308', '#22c55e', '#14b8a6', '#06b6d4', '#3b82f6', '#8b5cf6', '#d946ef', '#ec4899']

const ANIMALS = ['פנדה', 'ג׳ירפה', 'דולפין', 'ינשוף', 'שועל', 'קואלה', 'פינגווין', 'נמר', 'צב', 'זברה', 'לוטרה', 'קיפוד', 'תוכי', 'פיל', 'גור אריות', 'סנאי', 'לווייתן', 'פרפר', 'דבורה', 'צבי']

const K_ID = 'swb.id'
const K_ME = 'swb.me'
const K_SET = 'swb.settings'
const K_RECENT = 'swb.recent'
const K_VIEW = 'swb.view.'
const K_SEEN = 'swb.seen'

export function deviceKind () {
  if (isTVDevice) return 'tv'
  const w = Math.min(screen.width || innerWidth, screen.height || innerHeight)
  if (isTouch() && w < 600) return 'phone'
  if (isTouch() && w < 1100) return 'tablet'
  return 'computer'
}
export const KIND_EMOJI = { tv: '📺', phone: '📱', tablet: '📲', computer: '💻' }
export const KIND_NAME = { tv: 'טלוויזיה', phone: 'טלפון', tablet: 'טאבלט', computer: 'מחשב' }

export function deviceId () {
  let id = store.get(K_ID, null)
  if (!id) { id = 'd_' + rid(12); store.set(K_ID, id) }
  return id
}

export function getMe () {
  let me = store.get(K_ME, null)
  if (!me || typeof me !== 'object' || !me.name) {
    const a = ANIMALS[Math.floor(Math.random() * ANIMALS.length)]
    me = { name: a, color: PEOPLE_COLORS[Math.floor(Math.random() * PEOPLE_COLORS.length)], auto: true }
    store.set(K_ME, me)
  }
  if (!PEOPLE_COLORS.includes(me.color) && !/^#[0-9a-f]{6}$/i.test(me.color)) me.color = PEOPLE_COLORS[0]
  me.kind = deviceKind()
  me.id = deviceId()
  return me
}

export function setMe (patch) {
  const me = { ...getMe(), ...patch, auto: false }
  store.set(K_ME, { name: String(me.name || '').slice(0, 24) || 'אורח', color: me.color, auto: false })
  return getMe()
}

// Widths are SCREEN pixels at the moment of drawing (stored in world units = px / zoom),
// so what you see is what you get at any zoom level.
export const WIDTH_RANGE = {
  pen: [1, 40],
  highlighter: [6, 64],
  eraser: [8, 120],
  shape: [1, 24],
  text: [12, 120]
}
export const widthKey = tool => (tool === 'line' || tool === 'arrow' || tool === 'rect' || tool === 'ellipse') ? 'shape' : tool

const DEFAULT_SETTINGS = {
  tool: 'pen',
  color: '#1e1e2e',
  widths: { pen: 4, highlighter: 20, eraser: 28, shape: 4, text: 30 },
  shape: 'rect',
  fill: false,
  eraserMode: 'stroke',
  fingerDraws: true
}

export function getSettings () {
  const s = store.get(K_SET, {})
  return { ...DEFAULT_SETTINGS, ...s, widths: { ...DEFAULT_SETTINGS.widths, ...(s && s.widths) } }
}
export function saveSettings (s) { store.set(K_SET, s) }

// ------------------------------------------------------------------ recent boards
const MAX_RECENT = 30

export function getRecent () {
  const r = store.get(K_RECENT, [])
  return Array.isArray(r) ? r.filter(x => x && x.code).sort((a, b) => (b.t || 0) - (a.t || 0)) : []
}

export function touchRecent (code, patch = {}) {
  const list = getRecent()
  const i = list.findIndex(x => x.code === code)
  const cur = i >= 0 ? list.splice(i, 1)[0] : { code, created: Date.now() }
  const next = { ...cur, ...patch, code, t: Date.now() }
  list.unshift(next)
  while (list.length > MAX_RECENT) list.pop()
  try {
    store.set(K_RECENT, list)
  } catch {}
  // localStorage full? drop thumbnails of the oldest boards and retry
  if (JSON.stringify(store.get(K_RECENT, [])).length < 10 && list.length) {
    for (let k = list.length - 1; k > 2; k--) delete list[k].thumb
    store.set(K_RECENT, list)
  }
  return next
}

export function forgetRecent (code) {
  store.set(K_RECENT, getRecent().filter(x => x.code !== code))
}

export const getSavedView = code => store.get(K_VIEW + code, null)
export const saveView = (code, v) => store.set(K_VIEW + code, v)

export function seenOnce (key) {
  const s = store.get(K_SEEN, {})
  if (s[key]) return true
  s[key] = Date.now()
  store.set(K_SEEN, s)
  return false
}
