// Small shared helpers: codes, DOM builder, storage, time, platform sniffing.

export const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
export const CODE_LEN = 6
export const ROOM_PREFIX = 'swhiteboard:v1:'

export function newCode () {
  const a = new Uint8Array(CODE_LEN)
  crypto.getRandomValues(a)
  let s = ''
  for (const v of a) s += ALPHABET[v & 31] // 32 symbols, 256 % 32 === 0 -> unbiased
  return s
}

export function rid (n = 10) {
  const a = new Uint8Array(n)
  crypto.getRandomValues(a)
  let s = ''
  for (const v of a) s += (v & 35).toString(36)
  return s
}

// Lenient: real codes come from ALPHABET, but server-side test boards like TEST01 also exist.
export const cleanCode = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '')
export const isValidCode = c => /^[A-Z0-9]{4,12}$/.test(c)

export const boardPath = (code, { tv = false } = {}) => `/b/${code}${tv ? '?tv=1' : ''}`
export const boardUrl = (code, opts) => location.origin + boardPath(code, opts)
// Pages serves the app shell; its build supplies the separately hosted sync server.
// Same-origin deployments keep the original behaviour.
export const wsOrigin = () => (typeof __SYNC_ORIGIN__ !== 'undefined' && __SYNC_ORIGIN__
  ? __SYNC_ORIGIN__ : location.origin).replace(/^http/, 'ws')

// ------------------------------------------------------------------ DOM builder
export function h (tag, props, ...children) {
  const el = document.createElement(tag)
  if (props) {
    for (const k in props) {
      const v = props[k]
      if (v == null || v === false) continue
      if (k === 'class') el.className = v
      // setProperty, not Object.assign: CSS custom properties (e.g. '--c' on swatches/avatars) are
      // silently dropped by property assignment, which left every colour swatch empty.
      else if (k === 'style' && typeof v === 'object') { for (const p in v) el.style.setProperty(p.startsWith('--') ? p : p.replace(/[A-Z]/g, m => '-' + m.toLowerCase()), v[p]) }
      else if (k === 'html') el.innerHTML = v
      else if (k === 'dataset') Object.assign(el.dataset, v)
      else if (k === 'value') el.value = v
      else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2).toLowerCase(), v)
      else if (v === true) el.setAttribute(k, '')
      else el.setAttribute(k, v)
    }
  }
  append(el, children)
  return el
}
function append (el, children) {
  for (const c of children) {
    if (c == null || c === false) continue
    if (Array.isArray(c)) append(el, c)
    else el.append(c.nodeType ? c : document.createTextNode(String(c)))
  }
}

// ------------------------------------------------------------------ storage (never throws)
export const store = {
  get (k, d) {
    try {
      const v = localStorage.getItem(k)
      return v == null ? d : JSON.parse(v)
    } catch { return d }
  },
  set (k, v) { try { localStorage.setItem(k, JSON.stringify(v)) } catch {} },
  del (k) { try { localStorage.removeItem(k) } catch {} }
}

// ------------------------------------------------------------------ misc
export const clamp = (v, a, b) => v < a ? a : v > b ? b : v

export function debounce (fn, ms) {
  let t = 0
  const d = (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms) }
  d.flush = (...a) => { clearTimeout(t); fn(...a) }
  d.cancel = () => clearTimeout(t)
  return d
}

export function relTime (t) {
  const d = (Date.now() - t) / 1000
  if (d < 45) return 'עכשיו'
  if (d < 90) return 'לפני דקה'
  if (d < 3600) return `לפני ${Math.round(d / 60)} דק׳`
  if (d < 5400) return 'לפני שעה'
  if (d < 86400) return `לפני ${Math.round(d / 3600)} שע׳`
  if (d < 172800) return 'אתמול'
  try { return new Date(t).toLocaleDateString('he-IL', { day: 'numeric', month: 'short' }) } catch { return '' }
}

export const isTypingTarget = el =>
  !!el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable)

const UA = typeof navigator !== 'undefined' ? navigator.userAgent : ''
export const isIOS = /iPad|iPhone|iPod/.test(UA) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)
export const isAndroid = /Android/i.test(UA)
export const isTVDevice = /SMART-TV|SmartTV|Tizen|Web0S|webOS|NetCast|BRAVIA|AFT[A-Z]|Android TV|GoogleTV|CrKey|HbbTV|Viera|AppleTV|\bTV\b/i.test(UA)
export const isTouch = () => (navigator.maxTouchPoints || 0) > 0 || 'ontouchstart' in window
export const isStandalone = () =>
  (window.matchMedia && (matchMedia('(display-mode: standalone)').matches || matchMedia('(display-mode: fullscreen)').matches)) ||
  navigator.standalone === true

export function copyText (text) {
  if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(text).then(() => true, () => legacyCopy(text))
  return Promise.resolve(legacyCopy(text))
}
function legacyCopy (text) {
  const ta = h('textarea', { style: { position: 'fixed', opacity: '0', top: '0' } })
  ta.value = text
  document.body.append(ta)
  ta.select()
  let ok = false
  try { ok = document.execCommand('copy') } catch {}
  ta.remove()
  return ok
}

// Tiny event emitter
export function emitter () {
  const map = new Map()
  return {
    on (ev, fn) { if (!map.has(ev)) map.set(ev, new Set()); map.get(ev).add(fn); return () => map.get(ev).delete(fn) },
    emit (ev, ...a) { const s = map.get(ev); if (s) for (const fn of [...s]) fn(...a) }
  }
}
