// Home: create a board, join by code, recent boards (localStorage), install + identity.
import { h, newCode, cleanCode, isValidCode, relTime, isTVDevice, isStandalone, isTouch, CODE_LEN } from './util.js'
import { icon, logoSVG } from './icons.js'
import { getRecent, forgetRecent, getMe } from './prefs.js'
import { toast, confirmDialog } from './ui.js'
import { canInstall, canAddToHomeIOS, promptInstall, pwa } from './pwa.js'
import { openProfile, avatar } from './profile.js'

export function openHome (app, { autoNew = false } = {}) {
  document.title = 'Couch Board · לוח משותף'
  const root = h('div', { class: 'home' })
  const offs = []

  // ---- hero
  const meBtn = h('button', { class: 'me-chip', type: 'button', title: 'השם והצבע שלי · Me' })
  const paintMe = () => {
    const me = getMe()
    meBtn.replaceChildren(avatar(me, 28), h('span', null, me.name), icon('edit', 'tiny'))
  }
  meBtn.onclick = () => openProfile(() => paintMe())
  paintMe()

  const installBtn = h('button', { class: 'btn small ghost install-btn', type: 'button', hidden: true }, icon('install'), h('span', { class: 'ib-t' }, 'התקנת האפליקציה'))
  installBtn.onclick = () => promptInstall()
  const paintInstall = () => {
    const show = !isStandalone() && (canInstall() || canAddToHomeIOS())
    installBtn.hidden = !show
  }
  offs.push(pwa.ev.on('change', paintInstall))
  paintInstall()

  const head = h('header', { class: 'home-head' },
    h('div', { class: 'brand' }, h('span', { html: logoSVG(40) }), h('div', null, h('b', null, 'Couch Board'), h('small', null, 'לוח משותף לטלוויזיה ולטלפונים'))),
    h('div', { class: 'home-head-end' }, installBtn, meBtn)
  )

  // ---- create
  const createBtn = h('button', { class: 'big-action create', type: 'button' },
    h('span', { class: 'ba-icon' }, icon('plus')),
    h('span', { class: 'ba-t' }, h('b', null, 'לוח חדש'), h('small', null, 'Create a board — כל מכשיר יכול'))
  )
  createBtn.onclick = () => app.newBoard()

  // ---- join
  const codeInput = h('input', {
    class: 'code-input',
    type: 'text',
    inputmode: 'text',
    autocapitalize: 'characters',
    autocomplete: 'off',
    autocorrect: 'off',
    spellcheck: 'false',
    maxlength: '12',
    placeholder: 'ABC234',
    dir: 'ltr',
    'aria-label': 'קוד לוח · Board code',
    enterkeyhint: 'go'
  })
  const joinBtn = h('button', { class: 'btn primary', type: 'button', disabled: true }, 'הצטרפות', icon('chevronLeft', 'flip-ltr'))
  const join = () => {
    const c = cleanCode(codeInput.value)
    if (!isValidCode(c)) { codeInput.classList.add('shake'); setTimeout(() => codeInput.classList.remove('shake'), 400); toast('הקוד צריך להיות 6 תווים · 6 characters'); return }
    app.navigate('/b/' + c)
  }
  codeInput.addEventListener('input', () => {
    const v = cleanCode(codeInput.value)
    if (codeInput.value !== v) codeInput.value = v
    joinBtn.disabled = v.length < 4
    if (v.length === CODE_LEN) codeInput.classList.add('full')
    else codeInput.classList.remove('full')
  })
  codeInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); join() } })
  codeInput.addEventListener('paste', e => {
    const text = (e.clipboardData && e.clipboardData.getData('text')) || ''
    const m = text.match(/\/b\/([A-Za-z0-9]{4,12})/)
    if (m) { e.preventDefault(); codeInput.value = cleanCode(m[1]); codeInput.dispatchEvent(new Event('input')) }
  })
  joinBtn.onclick = join
  const joinCard = h('div', { class: 'join-card' },
    h('div', { class: 'jc-t' }, h('b', null, 'הצטרפות עם קוד'), h('small', null, 'Join with the code shown on the TV / phone')),
    h('div', { class: 'join-row' }, codeInput, joinBtn)
  )

  const actions = h('section', { class: 'home-actions' }, createBtn, joinCard)

  // ---- recent
  const recentWrap = h('section', { class: 'recent' })
  const paintRecent = () => {
    const list = getRecent()
    if (!list.length) {
      recentWrap.replaceChildren(
        h('div', { class: 'empty-recent' },
          h('div', { class: 'er-art', html: logoSVG(64) }),
          h('p', null, 'עוד אין לוחות במכשיר הזה.'),
          h('small', null, 'צרו לוח חדש, או סרקו את הקוד שמופיע על הטלוויזיה כדי להצטרף.'))
      )
      return
    }
    const grid = h('div', { class: 'recent-grid' }, list.map(r => {
      const card = h('div', { class: 'rcard', role: 'listitem' })
      const open = h('button', { class: 'rc-open', type: 'button', 'aria-label': `פתיחת ${r.title || r.code}`, onclick: () => app.navigate('/b/' + r.code) },
        h('div', { class: 'rc-thumb' + (r.thumb ? '' : ' none') }, r.thumb ? h('img', { src: r.thumb, alt: '', loading: 'lazy', decoding: 'async' }) : icon('pen')),
        h('div', { class: 'rc-meta' },
          h('b', { dir: 'auto' }, r.title || 'לוח ללא שם'),
          h('span', { class: 'rc-sub' }, h('span', { class: 'rc-code', dir: 'ltr' }, r.code), ' · ', relTime(r.t || Date.now())))
      )
      const tvLink = h('button', { class: 'icon-btn small ghost rc-tv', type: 'button', title: 'הצגה בטלוויזיה · Open as TV', 'aria-label': 'הצגה בטלוויזיה', onclick: () => app.navigate(`/b/${r.code}?tv=1`) }, icon('tv'))
      const del = h('button', { class: 'icon-btn small ghost rc-del', type: 'button', title: 'הסרה מהרשימה · Remove from list', 'aria-label': 'הסרה מהרשימה' }, icon('x'))
      del.onclick = async () => {
        const ok = await confirmDialog({ title: 'להסיר מהרשימה?', text: `הלוח ${r.code} יוסר מהרשימה במכשיר הזה בלבד. הלוח עצמו לא נמחק — אפשר תמיד לחזור אליו עם הקוד.`, okLabel: 'הסרה' })
        if (!ok) return
        forgetRecent(r.code)
        paintRecent()
      }
      card.append(open, h('div', { class: 'rc-tools' }, tvLink, del))
      return card
    }))
    grid.setAttribute('role', 'list')
    recentWrap.replaceChildren(
      h('div', { class: 'sec-head' }, h('h2', null, 'הלוחות שלי'), h('small', null, 'Recent boards on this device')),
      grid
    )
  }
  paintRecent()

  // ---- tips
  const tips = h('section', { class: 'tips' },
    tip('tv', 'על הטלוויזיה', 'פתחו לוח בדפדפן של הטלוויזיה עם ‎?tv=1 — מקבלים מסך מלא עם QR בפינה.'),
    tip('users', 'כמה מכשירים שרוצים', 'כל טלפון שסורק מצטרף. כמה לוחות במקביל, מכל מכשיר.'),
    tip('cloudOff', 'עובד בלי רשת', 'הכל נשמר במכשיר ומסתנכרן לבד כשחוזר החיבור.')
  )

  root.append(h('div', { class: 'home-inner' }, head, h('h1', { class: 'home-h1' }, 'ציירו יחד על ', h('span', { class: 'grad' }, 'המסך הגדול')), actions, recentWrap, tips,
    h('footer', { class: 'home-foot' }, h('span', { dir: 'ltr' }, location.host), ' · ', h('span', null, 'Couch Board v2'))))
  app.mount(root)

  if (isTVDevice && !isTouch()) {
    // remote-friendly: start focus on "new board"
    requestAnimationFrame(() => { try { createBtn.focus() } catch {} })
  } else if (!isTouch()) {
    requestAnimationFrame(() => { try { codeInput.focus({ preventScroll: true }) } catch {} })
  }
  if (autoNew) app.newBoard()

  const onStorage = e => { if (e.key && e.key.startsWith('swb.')) { paintRecent(); paintMe() } }
  addEventListener('storage', onStorage)
  const onVis = () => { if (document.visibilityState === 'visible') paintRecent() }
  document.addEventListener('visibilitychange', onVis)

  return {
    destroy () {
      removeEventListener('storage', onStorage)
      document.removeEventListener('visibilitychange', onVis)
      for (const f of offs) f()
    }
  }
}

function tip (ic, title, text) {
  return h('div', { class: 'tip' }, h('span', { class: 'tip-ic' }, icon(ic)), h('div', null, h('b', null, title), h('p', null, text)))
}

export { newCode }
