      const inside = []
      for (const m of this.cv.order) {
        if (!this.selectable(m)) continue
        const b = getEntry(m).bbox
        if (b.x0 >= r.x0 && b.x1 <= r.x1 && b.y0 >= r.y0 && b.y1 <= r.y1) inside.push(m)
      }
      this.items = this.expand([...g.base, ...inside])
