// Stroke geometry cache + drawing + hit-testing + background + export.
// Everything is in WORLD units; the caller sets the canvas transform from the View.
import * as Y from 'yjs'
import { exportGroups } from './layers.js' // [layers] per-layer export compositing

export const FONT_STACK = 'system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans Hebrew", "Arial Hebrew", "Heebo", Arial, sans-serif'
export const textFont = size => `500 ${size}px ${FONT_STACK}`
export const LINE_H = 1.25

export const BG = {
  white: { base: '#ffffff', dark: false },
  grid: { base: '#fbfbfd', line: 'rgba(30,41,59,.075)', major: 'rgba(30,41,59,.16)', dark: false },
  dots: { base: '#fbfbfd', dot: 'rgba(30,41,59,.26)', dark: false },
  dark: { base: '#161a2b', dot: 'rgba(226,232,240,.07)', dark: true }
}
export const BG_KEYS = ['white', 'grid', 'dots', 'dark']
export const isDarkBg = k => !!(BG[k] && BG[k].dark)

const FREE = new Set(['pen', 'highlighter', 'eraser'])
const SHAPES = new Set(['line', 'arrow', 'rect', 'ellipse'])
export const isShapeTool = t => SHAPES.has(t)
export const isFreeTool = t => FREE.has(t)

// ------------------------------------------------------------------ colour helpers
const lumCache = new Map()
export function luminance (c) {
  let v = lumCache.get(c)
  if (v !== undefined) return v
  let r = 0; let g = 0; let b = 0
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(c || '').trim())
  if (m) {
    let hx = m[1]
    if (hx.length === 3) hx = hx.split('').map(x => x + x).join('')
    r = parseInt(hx.slice(0, 2), 16) / 255; g = parseInt(hx.slice(2, 4), 16) / 255; b = parseInt(hx.slice(4, 6), 16) / 255
  }
  const lin = x => x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4)
  v = 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)
  if (lumCache.size > 256) lumCache.clear()
  lumCache.set(c, v)
  return v
}
// "Ink" adapts: very dark colours turn near-white on the dark background (and back), so a board stays readable.
export const inkColor = (c, dark) => (dark && luminance(c) < 0.06) ? '#eef2f7' : (c || '#1e1e2e')

// ------------------------------------------------------------------ text measuring
let mctx = null
const measureCtx = () => {
  if (!mctx) mctx = document.createElement('canvas').getContext('2d')
  return mctx
}
const measureW = (line) => {
  const ctx = measureCtx()
  ctx.font = textFont(100)
  return ctx.measureText(line).width / 100
}
const RTL_RE = /[֐-׿؀-ۿݐ-ݿיִ-﷿ﹰ-﻿]/
const LTR_RE = /[A-Za-zÀ-ɏͰ-ϿЀ-ӿ]/
export function detectDir (text) {
  for (const ch of String(text || '')) {
    if (RTL_RE.test(ch)) return 'rtl'
    if (LTR_RE.test(ch)) return 'ltr'
  }
  return null
}

// ------------------------------------------------------------------ entry cache
const cache = new WeakMap()
const num = (v, d = 0) => (typeof v === 'number' && Number.isFinite(v)) ? v : d

export function invalidate (m) {
  const e = cache.get(m)
  if (e) e.dirty = true
}

export function getEntry (m) {
  let e = cache.get(m)
  if (!e || e.dirty) {
    e = buildEntry(m)
    cache.set(m, e)
  }
  return e
}

const readPoints = raw => {
  if (raw instanceof Y.Array) return raw.toArray()
  if (Array.isArray(raw)) return raw
  return []
}

export function buildEntry (src) {
  const isY = src instanceof Y.Map
  const get = k => isY ? src.get(k) : src[k]
  const tool = String(get('tool') || 'pen')
  const pts = readPoints(get('points'))
  const e = {
    src,
    id: get('id'),
    tool,
    color: String(get('color') || '#1e1e2e'),
    width: Math.max(0.05, num(get('width'), 4)),
    stride: get('pr') ? 3 : 2,
    fill: !!get('fill'),
    text: '',
    dir: 'ltr',
    pts,
    path: null,
    hitPoly: null,
    bbox: null,
    kind: 'free'
  }
  if (tool === 'image') buildImage(e, get)
  else if (FREE.has(tool)) buildFree(e)
  else if (SHAPES.has(tool)) { buildShape(e); buildLabel(e, get) }
  else if (tool === 'text') buildText(e, get)
  else buildFree(e)
  return e
}

function bboxOf (pts, stride, pad) {
  let x0 = Infinity; let y0 = Infinity; let x1 = -Infinity; let y1 = -Infinity
  for (let i = 0; i + 1 < pts.length; i += stride) {
    const x = pts[i]; const y = pts[i + 1]
    if (x < x0) x0 = x
    if (x > x1) x1 = x
    if (y < y0) y0 = y
    if (y > y1) y1 = y
  }
  if (x0 === Infinity) return { x0: 0, y0: 0, x1: 0, y1: 0, empty: true }
  return { x0: x0 - pad, y0: y0 - pad, x1: x1 + pad, y1: y1 + pad }
}

const pressureFactor = p => Math.min(1.6, Math.max(0.25, 0.3 + 1.2 * num(p, 0.5)))

function buildFree (e) {
  e.kind = 'free'
  const { pts, stride, width } = e
  const n = (pts.length / stride) | 0
  e.n = n
  const usePressure = stride === 3 && e.tool === 'pen'
  e.filled = usePressure
  e.bbox = bboxOf(pts, stride, width * (usePressure ? 0.8 : 0.5) + 0.5)
  if (n === 0) { e.path = null; return }
  const p = new Path2D()
  if (usePressure) {
    for (let i = 0; i < n; i++) {
      const x = pts[i * 3]; const y = pts[i * 3 + 1]; const r = width * pressureFactor(pts[i * 3 + 2]) / 2
      p.moveTo(x + r, y)
      p.arc(x, y, r, 0, Math.PI * 2, true)
    }
    for (let i = 1; i < n; i++) {
      const ax = pts[(i - 1) * 3]; const ay = pts[(i - 1) * 3 + 1]
      const bx = pts[i * 3]; const by = pts[i * 3 + 1]
      const dx = bx - ax; const dy = by - ay; const len = Math.hypot(dx, dy)
      if (len < 1e-6) continue
      const nx = -dy / len; const ny = dx / len
      const ra = width * pressureFactor(pts[(i - 1) * 3 + 2]) / 2
      const rb = width * pressureFactor(pts[i * 3 + 2]) / 2
      p.moveTo(ax + nx * ra, ay + ny * ra)
      p.lineTo(bx + nx * rb, by + ny * rb)
      p.lineTo(bx - nx * rb, by - ny * rb)
      p.lineTo(ax - nx * ra, ay - ny * ra)
      p.closePath()
    }
    e.path = p
    return
  }
  const x0 = pts[0]; const y0 = pts[1]
  p.moveTo(x0, y0)
  if (n === 1) {
    p.lineTo(x0 + 0.01, y0)
  } else if (n === 2) {
    p.lineTo(pts[stride], pts[stride + 1])
  } else {
    for (let i = 1; i < n - 1; i++) {
      const x = pts[i * stride]; const y = pts[i * stride + 1]
      const nx = pts[(i + 1) * stride]; const ny = pts[(i + 1) * stride + 1]
      p.quadraticCurveTo(x, y, (x + nx) / 2, (y + ny) / 2)
    }
    p.lineTo(pts[(n - 1) * stride], pts[(n - 1) * stride + 1])
  }
  e.path = p
}

function arrowHead (x0, y0, x1, y1, w) {
  const len = Math.hypot(x1 - x0, y1 - y0)
  const head = Math.min(Math.max(w * 3.6, 12), len * 0.5)
  const a = Math.atan2(y1 - y0, x1 - x0)
  const sp = 0.48
  return [
    x1 - head * Math.cos(a - sp), y1 - head * Math.sin(a - sp),
    x1, y1,
    x1 - head * Math.cos(a + sp), y1 - head * Math.sin(a + sp)
  ]
}

function buildShape (e) {
  e.kind = 'shape'
  const [x0 = 0, y0 = 0, x1 = x0, y1 = y0] = e.pts.map(v => num(v))
  const w = e.width
  const p = new Path2D()
  const minx = Math.min(x0, x1); const maxx = Math.max(x0, x1)
  const miny = Math.min(y0, y1); const maxy = Math.max(y0, y1)
  e.geom = { x0, y0, x1, y1, minx, miny, maxx, maxy }
  let pad = w / 2 + 1
  switch (e.tool) {
    case 'line':
      p.moveTo(x0, y0); p.lineTo(x1, y1)
      e.hitPoly = [[x0, y0, x1, y1]]
      break
    case 'arrow': {
      p.moveTo(x0, y0); p.lineTo(x1, y1)
      const h = arrowHead(x0, y0, x1, y1, w)
      p.moveTo(h[0], h[1]); p.lineTo(h[2], h[3]); p.lineTo(h[4], h[5])
      e.hitPoly = [[x0, y0, x1, y1], [h[0], h[1], h[2], h[3], h[4], h[5]]]
      pad += Math.max(w * 3.6, 12)
      break
    }
    case 'rect':
      p.rect(minx, miny, maxx - minx, maxy - miny)
      e.hitPoly = [[minx, miny, maxx, miny, maxx, maxy, minx, maxy, minx, miny]]
      break
    case 'ellipse': {
      const cx = (minx + maxx) / 2; const cy = (miny + maxy) / 2
      const rx = Math.max(0.01, (maxx - minx) / 2); const ry = Math.max(0.01, (maxy - miny) / 2)
      p.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2)
      const poly = []
      for (let i = 0; i <= 48; i++) {
        const t = (i / 48) * Math.PI * 2
        poly.push(cx + rx * Math.cos(t), cy + ry * Math.sin(t))
      }
      e.hitPoly = [poly]
      e.geom.cx = cx; e.geom.cy = cy; e.geom.rx = rx; e.geom.ry = ry
      break
    }
  }
  e.path = p
  e.bbox = { x0: minx - pad, y0: miny - pad, x1: maxx + pad, y1: maxy + pad }
}

// ---- images: decoded asset cache (key -> HTMLImageElement), filled from the doc's 'assets' map
export const IMAGE_DATA_RE = /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/
const imgCache = new Map()
const readyFns = new Set()
export function onImageReady (fn) { readyFns.add(fn); return () => readyFns.delete(fn) }
export function setAssetData (key, url) {
  if (typeof key !== 'string' || imgCache.has(key) || typeof url !== 'string' || !IMAGE_DATA_RE.test(url)) return
  const img = new Image()
  const rec = { img, ready: false }
  imgCache.set(key, rec)
  img.onload = () => { rec.ready = true; for (const fn of readyFns) fn(key) }
  img.onerror = () => { rec.failed = true }
  img.src = url
}
export const imageFor = key => imgCache.get(key)
function buildImage (e, get) {
  e.kind = 'image'
  const [x0 = 0, y0 = 0, x1 = x0, y1 = y0] = e.pts.map(v => num(v))
  const minx = Math.min(x0, x1); const maxx = Math.max(x0, x1); const miny = Math.min(y0, y1); const maxy = Math.max(y0, y1)
  e.geom = { x0, y0, x1, y1, minx, miny, maxx, maxy }
  e.asset = String(get('asset') || '')
  e.bbox = { x0: minx, y0: miny, x1: maxx, y1: maxy }
}
function drawImageEntry (ctx, e, s) {
  const g = e.geom
  const w = g.maxx - g.minx; const hh = g.maxy - g.miny
  const rec = imgCache.get(e.asset)
  ctx.globalAlpha = 1
  ctx.globalCompositeOperation = 'source-over'
  if (rec && rec.ready) {
    ctx.imageSmoothingEnabled = true
    try { ctx.imageSmoothingQuality = 'high' } catch {}
    ctx.drawImage(rec.img, g.minx, g.miny, w, hh)
    return
  }
  // not loaded yet (or missing): a quiet placeholder of the right size
  ctx.fillStyle = 'rgba(148,163,184,.18)'
  ctx.fillRect(g.minx, g.miny, w, hh)
  ctx.strokeStyle = 'rgba(148,163,184,.6)'
  ctx.lineWidth = 1.5 / s
  ctx.setLineDash([6 / s, 5 / s])
  ctx.strokeRect(g.minx, g.miny, w, hh)
  ctx.setLineDash([])
}

// ---- shape labels: text INSIDE a rect / ellipse, centred, wrapped to the shape's width
export const LABEL_TOOLS = new Set(['rect', 'ellipse'])
export const labelHidden = new WeakSet() // shapes whose label is being edited (the editor paints it instead)
export const labelPad = (e) => Math.max(e.width, 4) + (e.lsize || 16) * 0.35
// inner box the label wraps to (an ellipse's inscribed rectangle is ~0.707 of its axes)
export function labelBox (e) {
  const g = e.geom
  const k = e.tool === 'ellipse' ? 0.7071 : 1
  const cx = (g.minx + g.maxx) / 2; const cy = (g.miny + g.maxy) / 2
  const hw = Math.max(1, ((g.maxx - g.minx) / 2) * k - labelPad(e)); const hh = Math.max(1, ((g.maxy - g.miny) / 2) * k - labelPad(e) * 0.5)
  return { cx, cy, w: hw * 2, h: hh * 2 }
}
export function wrapLines (text, size, maxW) {
  const out = []
  const fits = s => measureW(s) * size <= maxW
  for (const para of String(text).split('\n')) {
    if (!para) { out.push(''); continue }
    const words = para.split(/(\s+)/)
    let line = ''
    for (const w of words) {
      if (!w) continue
      const next = line + w
      if (!line || fits(next)) { line = next; continue }
      out.push(line.replace(/\s+$/, ''))
      line = /^\s+$/.test(w) ? '' : w
    }
    // a single word wider than the box breaks by characters
    while (line && !fits(line) && line.length > 1) {
      let i = line.length - 1
      while (i > 1 && !fits(line.slice(0, i))) i--
      out.push(line.slice(0, i)); line = line.slice(i)
    }
    out.push(line.replace(/\s+$/, ''))
  }
  return out
}
function buildLabel (e, get) {
  if (!LABEL_TOOLS.has(e.tool)) return
  const label = String(get('label') || '')
  if (!label) return
  e.label = label
  e.ldir = get('ldir') === 'rtl' ? 'rtl' : (get('ldir') === 'ltr' ? 'ltr' : (detectDir(label) || 'ltr'))
  e.lsize = Math.max(1, num(get('lsize'), 20))
  const b = labelBox(e)
  e.llines = wrapLines(label, e.lsize, b.w)
}
function drawLabel (ctx, e, dark) {
  if (!e.label || labelHidden.has(e.src)) return
  const b = labelBox(e)
  const size = e.lsize; const lh = size * LINE_H
  ctx.save()
  const g = e.geom
  ctx.beginPath(); ctx.rect(g.minx, g.miny, g.maxx - g.minx, g.maxy - g.miny); ctx.clip()
  ctx.globalAlpha = 1
  ctx.globalCompositeOperation = 'source-over'
  ctx.fillStyle = inkColor(e.color, dark)
  ctx.font = textFont(size)
  ctx.textBaseline = 'middle'
  ctx.textAlign = 'center'
  try { ctx.direction = e.ldir } catch {}
  let y = b.cy - (e.llines.length * lh) / 2 + lh / 2
  for (const line of e.llines) { if (line) ctx.fillText(line, b.cx, y); y += lh }
  ctx.restore()
}

function buildText (e, get) {
  e.kind = 'text'
  const text = String(get('text') || '')
  e.text = text
  e.dir = get('dir') === 'rtl' ? 'rtl' : 'ltr'
  const size = e.width
  e.lines = text.split('\n')
  let w = 0
  for (const line of e.lines) w = Math.max(w, measureW(line) * size)
  const h = Math.max(1, e.lines.length) * size * LINE_H
  const x = num(e.pts[0]); const y = num(e.pts[1])
  e.tw = w; e.th = h
  e.bbox = e.dir === 'rtl' ? { x0: x - w, y0: y, x1: x, y1: y + h } : { x0: x, y0: y, x1: x + w, y1: y + h }
}

// ------------------------------------------------------------------ drawing
export function drawEntry (ctx, e, s, dark) {
  if (!e) return
  const minW = 0.6 / s
  if (e.kind === 'image') { drawImageEntry(ctx, e, s); return }
  if (e.kind === 'text') {
    if (!e.text) return
    const size = e.width
    ctx.globalAlpha = 1
    ctx.globalCompositeOperation = 'source-over'
    ctx.fillStyle = inkColor(e.color, dark)
    ctx.font = textFont(size)
    ctx.textBaseline = 'top'
    const x = e.pts[0] || 0; let y = e.pts[1] || 0
    try { ctx.direction = e.dir } catch {}
    ctx.textAlign = e.dir === 'rtl' ? 'right' : 'left'
    const lh = size * LINE_H
    const pad = (lh - size) / 2
    for (const line of e.lines) {
      if (line) ctx.fillText(line, x, y + pad)
      y += lh
    }
    try { ctx.direction = 'inherit' } catch {}
    return
  }
  if (!e.path) return
  const col = inkColor(e.color, dark)
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  if (e.tool === 'eraser') {
    ctx.globalCompositeOperation = 'destination-out'
    ctx.globalAlpha = 1
    ctx.strokeStyle = '#000'
    ctx.lineWidth = Math.max(e.width, minW)
    ctx.stroke(e.path)
    ctx.globalCompositeOperation = 'source-over'
    return
  }
  ctx.globalCompositeOperation = 'source-over'
  if (e.tool === 'highlighter') {
    ctx.globalAlpha = dark ? 0.5 : 0.38
    ctx.strokeStyle = col
    ctx.lineCap = 'round'
    ctx.lineWidth = Math.max(e.width, minW)
    ctx.stroke(e.path)
    ctx.globalAlpha = 1
    return
  }
  if (e.kind === 'shape' && e.fill && (e.tool === 'rect' || e.tool === 'ellipse')) {
    ctx.globalAlpha = 0.22
    ctx.fillStyle = col
    ctx.fill(e.path)
    ctx.globalAlpha = 1
  }
  if (e.filled) {
    ctx.globalAlpha = 1
    ctx.fillStyle = col
    ctx.fill(e.path)
    return
  }
  ctx.globalAlpha = 1
  ctx.strokeStyle = col
  ctx.lineWidth = Math.max(e.width, minW)
  ctx.stroke(e.path)
  if (e.label) drawLabel(ctx, e, dark)
}

export const intersects = (b, r) => !(b.x1 < r.x0 || b.x0 > r.x1 || b.y1 < r.y0 || b.y0 > r.y1)

// Draw a list of entries with view transform {s,tx,ty}, device pixel ratio dpr.
export function drawEntries (ctx, entries, view, dpr, dark, cull) {
  ctx.setTransform(dpr * view.s, 0, 0, dpr * view.s, dpr * view.tx, dpr * view.ty)
  for (const e of entries) {
    if (!e || !e.bbox) continue
    if (cull && !intersects(e.bbox, cull)) continue
    drawEntry(ctx, e, view.s, dark)
  }
  ctx.globalAlpha = 1
  ctx.globalCompositeOperation = 'source-over'
}

const mod = (a, n) => ((a % n) + n) % n

export function drawBackground (ctx, bgKey, view, dpr, W, H) {
  const bg = BG[bgKey] || BG.white
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.globalAlpha = 1
  ctx.globalCompositeOperation = 'source-over'
  ctx.fillStyle = bg.base
  ctx.fillRect(0, 0, W, H)
  if (bgKey !== 'grid' && bgKey !== 'dots' && bgKey !== 'dark') return
  let step = 32
  while (step * view.s < 16) step *= 4
  while (step * view.s > 160) step /= 4
  const ss = step * view.s * dpr
  const ox = mod(view.tx * dpr, ss); const oy = mod(view.ty * dpr, ss)
  const baseIx = Math.round((0 - view.tx * dpr + ox) / ss) // world index of first column
  const baseIy = Math.round((0 - view.ty * dpr + oy) / ss)
  if (bgKey === 'grid') {
    const lw = Math.max(1, dpr * 0.8)
    for (let pass = 0; pass < 2; pass++) {
      ctx.beginPath()
      ctx.strokeStyle = pass ? bg.major : bg.line
      ctx.lineWidth = pass ? lw * 1.15 : lw
      let i = 0
      for (let x = ox; x <= W; x += ss, i++) {
        const major = mod(baseIx + i, 4) === 0
        if (major !== !!pass) continue
        const px = Math.round(x) + 0.5
        ctx.moveTo(px, 0); ctx.lineTo(px, H)
      }
      i = 0
      for (let y = oy; y <= H; y += ss, i++) {
        const major = mod(baseIy + i, 4) === 0
        if (major !== !!pass) continue
        const py = Math.round(y) + 0.5
        ctx.moveTo(0, py); ctx.lineTo(W, py)
      }
      ctx.stroke()
    }
    return
  }
  // dots (also the faint dark-mode texture)
  const big = bgKey === 'dark' ? 0 : 1
  if (bgKey === 'dark' && ss < 22 * dpr) return
  ctx.fillStyle = bg.dot
  const r = Math.max(1, dpr * (bgKey === 'dark' ? 1 : 1.15))
  let iy = 0
  for (let y = oy; y <= H + ss; y += ss, iy++) {
    let ix = 0
    for (let x = ox; x <= W + ss; x += ss, ix++) {
      const major = big && mod(baseIx + ix, 4) === 0 && mod(baseIy + iy, 4) === 0
      const rr = major ? r * 1.6 : r
      ctx.fillRect(x - rr, y - rr, rr * 2, rr * 2)
    }
  }
}

// ------------------------------------------------------------------ hit testing
function segDist2 (px, py, ax, ay, bx, by) {
  const dx = bx - ax; const dy = by - ay
  const l2 = dx * dx + dy * dy
  let t = l2 > 0 ? ((px - ax) * dx + (py - ay) * dy) / l2 : 0
  t = t < 0 ? 0 : t > 1 ? 1 : t
  const x = ax + t * dx - px; const y = ay + t * dy - py
  return x * x + y * y
}

function polyHit (poly, stride, x, y, rr) {
  const r2 = rr * rr
  const n = (poly.length / stride) | 0
  if (n === 1) {
    const dx = poly[0] - x; const dy = poly[1] - y
    return dx * dx + dy * dy <= r2
  }
  for (let i = 1; i < n; i++) {
    if (segDist2(x, y, poly[(i - 1) * stride], poly[(i - 1) * stride + 1], poly[i * stride], poly[i * stride + 1]) <= r2) return true
  }
  return false
}

export function hitEntry (e, x, y, r) {
  if (!e || !e.bbox || e.tool === 'eraser') return false
  const b = e.bbox
  if (x < b.x0 - r || x > b.x1 + r || y < b.y0 - r || y > b.y1 + r) return false
  if (e.kind === 'text' || e.kind === 'image') return true
  if (e.kind === 'free') {
    const half = e.filled ? e.width * 0.7 : e.width / 2
    return polyHit(e.pts, e.stride, x, y, r + half)
  }
  if (e.kind === 'shape') {
    const g = e.geom
    if (e.fill || e.label) {
      if (e.tool === 'rect' && x >= g.minx && x <= g.maxx && y >= g.miny && y <= g.maxy) return true
      if (e.tool === 'ellipse') {
        const nx = (x - g.cx) / g.rx; const ny = (y - g.cy) / g.ry
        if (nx * nx + ny * ny <= 1) return true
      }
    }
    for (const poly of e.hitPoly || []) if (polyHit(poly, 2, x, y, r + e.width / 2)) return true
  }
  return false
}

export function contentBBox (entries) {
  let x0 = Infinity; let y0 = Infinity; let x1 = -Infinity; let y1 = -Infinity
  for (const e of entries) {
    if (!e || !e.bbox || e.bbox.empty || e.tool === 'eraser') continue
    if (e.kind === 'text' && !e.text) continue
    const b = e.bbox
    if (b.x0 < x0) x0 = b.x0
    if (b.y0 < y0) y0 = b.y0
    if (b.x1 > x1) x1 = b.x1
    if (b.y1 > y1) y1 = b.y1
  }
  return x0 === Infinity ? null : { x0, y0, x1, y1 }
}

// ------------------------------------------------------------------ export / thumbnails
function makeCanvas (w, h) {
  const c = document.createElement('canvas')
  c.width = Math.max(1, Math.round(w)); c.height = Math.max(1, Math.round(h))
  return c
}

export function renderToCanvas (maps, bgKey, { maxDim = 4096, pad = 56, scale = 2, width = 0, height = 0, maxScale = 3 } = {}) {
  const groups = exportGroups(maps) // [layers] visible layers bottom-to-top, each { maps, opacity }
  const entries = groups.length === 1 ? groups[0].maps.map(getEntry) : groups.flatMap(g => g.maps).map(getEntry)
  const b = contentBBox(entries) || { x0: -320, y0: -200, x1: 320, y1: 200 }
  const bw = Math.max(1, b.x1 - b.x0); const bh = Math.max(1, b.y1 - b.y0)
  let s
  if (width && height) {
    s = Math.min((width - pad * 2) / bw, (height - pad * 2) / bh, maxScale)
  } else {
    s = Math.min(scale, (maxDim - pad * 2 * scale) / bw, (maxDim - pad * 2 * scale) / bh)
    width = Math.ceil(bw * s + pad * 2 * Math.min(scale, s * 2))
    height = Math.ceil(bh * s + pad * 2 * Math.min(scale, s * 2))
  }
  s = Math.max(s, 0.001)
  const view = { s, tx: width / 2 - ((b.x0 + b.x1) / 2) * s, ty: height / 2 - ((b.y0 + b.y1) / 2) * s }
  const out = makeCanvas(width, height)
  const ctx = out.getContext('2d')
  drawBackground(ctx, bgKey, view, 1, out.width, out.height)
  const layer = makeCanvas(width, height)
  const lctx = layer.getContext('2d')
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  for (const g of groups) { // [layers] each layer on its own surface (pixel eraser stays inside it), then composite
    lctx.setTransform(1, 0, 0, 1, 0, 0)
    lctx.clearRect(0, 0, layer.width, layer.height)
    drawEntries(lctx, g.maps.map(getEntry), view, 1, isDarkBg(bgKey), null)
    ctx.globalAlpha = g.opacity
    ctx.drawImage(layer, 0, 0)
  }
  ctx.globalAlpha = 1
  return out
}
