// Photoshop-style LAYERS — the data model (no DOM; the panel lives in layers-panel.js).
//
// Y.Doc shape:
//   doc.getMap('layers') : id -> Y.Map { name, visible, locked, opacity (0..1), order (number) }
//   every object Y.Map in 'strokes' may carry  layerId : string
// A missing layerId — or one naming a layer that no longer exists — means the fixed BASE layer, so old boards
// load unchanged and nothing can ever vanish because of a dangling id. The base layer is implicit: its entry
// in the map is created lazily only when someone renames / hides / locks / fades it. It is always the bottom
// layer and cannot be deleted or moved.
//
// Z-order inside a layer is still the order of the 'strokes' array. Layer order lives ONLY in each layer's
// `order` field, so reordering layers never re-inserts (re-creates) object Y.Maps.
//
// Undo (per device, session.undo, origin session.LOCAL): adding / deleting a layer and moving / copying
// objects between layers are undoable — deleting a layer removes its objects in the same transaction, so one
// undo brings the layer AND its contents back. Cosmetic toggles (visibility, lock, opacity, name, order) use
// an untracked origin so Ctrl+Z keeps undoing drawings, not eye-icon clicks.
import * as Y from 'yjs'
import { rid, store } from './util.js'

export const BASE = 'base'
export const LAYER_FIELD = 'layerId'
export const BASE_NAME = 'שכבת בסיס'
export const MAX_LAYERS = 32
export const LAYER_UI = { layersUi: true } // untracked transaction origin (not in the undo manager)

const K_ACTIVE = 'swb.layer.'

export const layersMap = doc => doc.getMap('layers')

const rd = (v, k) => (v instanceof Y.Map ? v.get(k) : (v && typeof v === 'object' ? v[k] : undefined))
const fin = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : d)
const clamp01 = v => (v < 0 ? 0 : v > 1 ? 1 : v)

function prelimGet (m, k) {
  // A Y.Map that is not yet in a doc keeps its fields in _prelimContent (get() would return undefined).
  if (m.doc) return m.get(k)
  return m._prelimContent ? m._prelimContent.get(k) : undefined
}

export function rawLayerId (m) {
  const v = m instanceof Y.Map ? prelimGet(m, LAYER_FIELD) : (m && m[LAYER_FIELD])
  return typeof v === 'string' && v ? v : BASE
}

function norm (id, v) {
  const base = id === BASE
  const name = String(rd(v, 'name') || '').trim()
  return {
    id,
    base,
    name: name || (base ? BASE_NAME : 'שכבה'),
    visible: rd(v, 'visible') !== false,
    locked: rd(v, 'locked') === true,
    opacity: clamp01(fin(rd(v, 'opacity'), 1)),
    order: base ? -Infinity : fin(rd(v, 'order'), 0)
  }
}

// -> { list: [layer, ...] bottom-to-top (base first), byId: Map }
export function readLayers (lmap) {
  const list = [norm(BASE, lmap ? lmap.get(BASE) : null)]
  if (lmap) {
    lmap.forEach((v, k) => {
      if (k === BASE || !v || typeof v !== 'object') return
      list.push(norm(k, v))
    })
  }
  list.sort((a, b) => (a.order - b.order) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
  const byId = new Map(list.map(l => [l.id, l]))
  return { list, byId }
}

// The layer an object really lives in (orphans fall back to base).
export function layerOf (state, m) {
  return state.byId.get(rawLayerId(m)) || state.byId.get(BASE)
}

// Group objects per VISIBLE layer, bottom-to-top, keeping array (z) order inside a layer. Empty layers skipped.
export function groupByLayer (maps, state, { visibleOnly = true } = {}) {
  const buckets = new Map()
  for (const m of maps) {
    const l = layerOf(state, m)
    if (visibleOnly && !l.visible) continue
    let b = buckets.get(l.id)
    if (!b) { b = { layer: l, maps: [] }; buckets.set(l.id, b) }
    b.maps.push(m)
  }
  const out = []
  for (const l of state.list) { const b = buckets.get(l.id); if (b) out.push(b) }
  return out
}

// Render groups for any list of object maps (export / thumbnails): reads the layers of the maps' own doc.
export function exportGroups (maps) {
  const first = maps.find(m => m instanceof Y.Map && m.doc)
  const state = readLayers(first ? layersMap(first.doc) : null)
  return groupByLayer(maps, state).map(g => ({ maps: g.maps, opacity: g.layer.opacity }))
}

// Interactive = may be hit-tested, erased, edited, selected or transformed.
export const isInteractive = (state, m) => { const l = layerOf(state, m); return l.visible && !l.locked }

// ------------------------------------------------------------------ per-device active layer
export const getActiveId = code => { const v = store.get(K_ACTIVE + code, BASE); return typeof v === 'string' && v ? v : BASE }
export const saveActiveId = (code, id) => store.set(K_ACTIVE + code, id)

// ------------------------------------------------------------------ operations
function ensureEntry (lmap, id) {
  let e = lmap.get(id)
  if (!(e instanceof Y.Map)) {
    const prev = e && typeof e === 'object' ? e : {}
    e = new Y.Map()
    for (const k of ['name', 'visible', 'locked', 'opacity', 'order']) if (prev[k] !== undefined) e.set(k, prev[k])
    lmap.set(id, e)
  }
  return e
}

export function addLayer (session, name) {
  const lmap = layersMap(session.doc)
  const { list } = readLayers(lmap)
  if (list.length >= MAX_LAYERS) return null
  const top = list.filter(l => !l.base).reduce((a, l) => Math.max(a, l.order), 0)
  let n = list.length
  const names = new Set(list.map(l => l.name))
  while (names.has(`שכבה ${n}`)) n++
  const id = 'L' + rid(8)
  session.undo.stopCapturing()
  session.doc.transact(() => {
    const e = new Y.Map()
    e.set('name', String(name || `שכבה ${n}`).slice(0, 40))
    e.set('visible', true)
    e.set('locked', false)
    e.set('opacity', 1)
    e.set('order', top + 1)
    lmap.set(id, e)
  }, session.LOCAL)
  session.undo.stopCapturing()
  return id
}

export function setLayerProp (session, id, key, value) {
  const lmap = layersMap(session.doc)
  if (id !== BASE && !lmap.has(id)) return
  if (key === 'name') value = String(value || '').trim().slice(0, 40)
  if (key === 'opacity') value = Math.round(clamp01(+value) * 100) / 100
  session.doc.transact(() => ensureEntry(lmap, id).set(key, value), LAYER_UI)
}

// dir: +1 = up (towards the top), -1 = down. The base layer never moves and nothing goes below it.
export function moveLayer (session, id, dir) {
  if (id === BASE) return false
  const lmap = layersMap(session.doc)
  const stack = readLayers(lmap).list.filter(l => !l.base)
  const i = stack.findIndex(l => l.id === id)
  const j = i + dir
  if (i < 0 || j < 0 || j >= stack.length) return false
  const a = stack[i]; const b = stack[j]
  session.doc.transact(() => {
    // renumber the whole stack 1..n in the new order: robust even if concurrent edits produced equal orders
    const next = stack.slice()
    next[i] = b; next[j] = a
    next.forEach((l, k) => { if (l.order !== k + 1) ensureEntry(lmap, l.id).set('order', k + 1) })
  }, LAYER_UI)
  return true
}

export function countInLayer (session, id) {
  let n = 0
  for (const m of session.strokes) if (rawLayerId(m) === id) n++
  return n
}

// Deletes the layer AND its objects in one undoable step (Ctrl+Z restores both). Returns the object count.
export function deleteLayer (session, id) {
  if (id === BASE) return 0
  const lmap = layersMap(session.doc)
  let n = 0
  session.undo.stopCapturing()
  session.doc.transact(() => {
    const arr = session.strokes.toArray()
    for (let i = arr.length - 1; i >= 0; i--) {
      if (rawLayerId(arr[i]) === id) { session.strokes.delete(i, 1); n++ }
    }
    lmap.delete(id)
  }, session.LOCAL)
  session.undo.stopCapturing()
  return n
}

// Re-tag objects in place (their Y.Maps are never re-inserted). Undoable.
export function moveToLayer (session, maps, target) {
  if (!maps.length) return 0
  session.undo.stopCapturing()
  session.doc.transact(() => {
    for (const m of maps) {
      if (!(m instanceof Y.Map) || !m.doc) continue
      if (target === BASE) { if (m.has(LAYER_FIELD)) m.delete(LAYER_FIELD) } else m.set(LAYER_FIELD, target)
    }
  }, session.LOCAL)
  session.undo.stopCapturing()
  return maps.length
}

function cloneValue (v) {
  if (v instanceof Y.Array) { const a = new Y.Array(); a.push(v.toArray().map(cloneValue)); return a }
  if (v instanceof Y.Map) { const m = new Y.Map(); v.forEach((x, k) => m.set(k, cloneValue(x))); return m }
  if (v instanceof Y.Text) return new Y.Text(v.toString())
  if (Array.isArray(v)) return v.slice()
  if (v && typeof v === 'object') return JSON.parse(JSON.stringify(v))
  return v
}

// Duplicate objects into another layer (appended on top of that layer). Undoable. Returns the new maps.
export function copyToLayer (session, maps, target, me) {
  const out = []
  if (!maps.length) return out
  session.undo.stopCapturing()
  session.doc.transact(() => {
    for (const m of maps) {
      if (!(m instanceof Y.Map) || !m.doc) continue
      const c = new Y.Map()
      m.forEach((v, k) => { if (k !== 'id' && k !== LAYER_FIELD) c.set(k, cloneValue(v)) })
      c.set('id', rid(10))
      c.set(LAYER_FIELD, target) // explicit (also for base): the new-object tagger leaves it alone
      if (me && me.id) c.set('author', me.id)
      c.set('t', Date.now())
      out.push(c)
    }
    session.strokes.push(out)
  }, session.LOCAL)
  session.undo.stopCapturing()
  return out
}

// ------------------------------------------------------------------ session install
// Tags every object this device creates (pen, shapes, text, eraser strokes, future tools) with the active
// layer, by wrapping this session's strokes.push/insert — the creators themselves need no changes. Only local
// edits (origin session.LOCAL) are tagged; imports/remote/undo are untouched.
export function installLayers (session, getActive) {
  const strokes = session.strokes
  const lmap = layersMap(session.doc)
  try { session.undo.addToScope(lmap) } catch (e) { console.warn('[layers] undo scope', e) }
  let last = null
  const tag = content => {
    const tr = session.doc._transaction
    if (!tr || tr.origin !== session.LOCAL || !Array.isArray(content)) return
    for (const m of content) {
      if (!(m instanceof Y.Map)) continue
      if (prelimGet(m, LAYER_FIELD) === undefined) {
        const id = getActive()
        if (id && id !== BASE) m.set(LAYER_FIELD, id)
      }
      last = m
    }
  }
  const origPush = strokes.push
  const origInsert = strokes.insert
  strokes.push = function (content) { tag(content); return origPush.call(this, content) }
  strokes.insert = function (index, content) { tag(content); return origInsert.call(this, index, content) }
  return {
    lastLocal () {
      if (!last || !last.doc || (last._item && last._item.deleted)) return null
      return last
    },
    destroy () {
      if (strokes.push !== origPush) delete strokes.push
      if (strokes.insert !== origInsert) delete strokes.insert
    }
  }
}
