// Camera for the infinite canvas.  screen = world * s + t   (screen = CSS pixels of the stage)
import { clamp, emitter } from './util.js'

export const MIN_SCALE = 0.05
export const MAX_SCALE = 24

export class View {
  constructor () {
    this.s = 1
    this.tx = 0
    this.ty = 0
    this.w = 1
    this.h = 1
    this.ev = emitter()
    this._raf = 0
    this.userMovedAt = 0 // last time the user panned/zoomed by hand (TV auto-fit backs off)
  }

  toWorld (sx, sy) { return [(sx - this.tx) / this.s, (sy - this.ty) / this.s] }
  toScreen (wx, wy) { return [wx * this.s + this.tx, wy * this.s + this.ty] }

  worldRect (margin = 0) {
    const [x0, y0] = this.toWorld(-margin, -margin)
    const [x1, y1] = this.toWorld(this.w + margin, this.h + margin)
    return { x0, y0, x1, y1 }
  }

  resize (w, h) {
    const first = this.w <= 1 && this.h <= 1
    // keep the world point at the centre stable across rotations / keyboard popups
    if (!first) {
      const [cx, cy] = this.toWorld(this.w / 2, this.h / 2)
      this.w = w; this.h = h
      this.tx = w / 2 - cx * this.s
      this.ty = h / 2 - cy * this.s
    } else {
      this.w = w; this.h = h
    }
    this.ev.emit('change', this)
  }

  set (s, tx, ty, { user = false } = {}) {
    s = clamp(s, MIN_SCALE, MAX_SCALE)
    if (!Number.isFinite(s) || !Number.isFinite(tx) || !Number.isFinite(ty)) return
    this.s = s; this.tx = tx; this.ty = ty
    if (user) { this.userMovedAt = Date.now(); this.stopAnim() }
    this.ev.emit('change', this)
  }

  panBy (dx, dy, opts = { user: true }) { this.set(this.s, this.tx + dx, this.ty + dy, opts) }

  setScaleAt (sx, sy, s, opts = { user: true }) {
    s = clamp(s, MIN_SCALE, MAX_SCALE)
    const [wx, wy] = this.toWorld(sx, sy)
    this.set(s, sx - wx * s, sy - wy * s, opts)
  }

  zoomAt (sx, sy, factor, opts) { this.setScaleAt(sx, sy, this.s * factor, opts) }

  zoomCenter (factor, animate = true) {
    const s = clamp(this.s * factor, MIN_SCALE, MAX_SCALE)
    const cx = this.w / 2; const cy = this.h / 2
    const [wx, wy] = this.toWorld(cx, cy)
    const t = [cx - wx * s, cy - wy * s]
    if (animate) this.animateTo(s, t[0], t[1], 200, true)
    else this.set(s, t[0], t[1], { user: true })
  }

  centerOn (wx, wy, s = this.s, animate = true) {
    const tx = this.w / 2 - wx * s; const ty = this.h / 2 - wy * s
    if (animate) this.animateTo(s, tx, ty, 260, true)
    else this.set(s, tx, ty, { user: true })
  }

  // Fit a world bbox {x0,y0,x1,y1} into the stage (minus insets in CSS px).
  fitTarget (b, { padding = 48, insets = { top: 0, right: 0, bottom: 0, left: 0 }, maxScale = 2, minScale = MIN_SCALE } = {}) {
    const aw = Math.max(40, this.w - insets.left - insets.right - padding * 2)
    const ah = Math.max(40, this.h - insets.top - insets.bottom - padding * 2)
    const bw = Math.max(1, b.x1 - b.x0); const bh = Math.max(1, b.y1 - b.y0)
    const s = clamp(Math.min(aw / bw, ah / bh), minScale, maxScale)
    const cx = insets.left + padding + aw / 2
    const cy = insets.top + padding + ah / 2
    return { s, tx: cx - ((b.x0 + b.x1) / 2) * s, ty: cy - ((b.y0 + b.y1) / 2) * s }
  }

  fit (b, opts = {}) {
    const t = this.fitTarget(b, opts)
    if (opts.animate === false) this.set(t.s, t.tx, t.ty, { user: !!opts.user })
    else this.animateTo(t.s, t.tx, t.ty, opts.ms || 420, !!opts.user)
  }

  stopAnim () { if (this._raf) cancelAnimationFrame(this._raf); this._raf = 0 }

  // Smooth camera move. Interpolates in log-scale so zoom feels linear.
  animateTo (s, tx, ty, ms = 300, user = false) {
    this.stopAnim()
    s = clamp(s, MIN_SCALE, MAX_SCALE)
    const reduce = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
    if (reduce || ms <= 0) { this.set(s, tx, ty, { user }); return }
    const s0 = this.s
    // anchor: keep the interpolation of the screen-centre world point coherent
    const c0 = this.toWorld(this.w / 2, this.h / 2)
    const c1 = [(this.w / 2 - tx) / s, (this.h / 2 - ty) / s]
    const t0 = performance.now()
    const ease = t => 1 - Math.pow(1 - t, 3)
    const step = now => {
      const k = Math.min(1, (now - t0) / ms)
      const e = ease(k)
      const si = Math.exp(Math.log(s0) + (Math.log(s) - Math.log(s0)) * e)
      const cx = c0[0] + (c1[0] - c0[0]) * e
      const cy = c0[1] + (c1[1] - c0[1]) * e
      this.s = si
      this.tx = this.w / 2 - cx * si
      this.ty = this.h / 2 - cy * si
      if (user) this.userMovedAt = Date.now()
      this.ev.emit('change', this)
      if (k < 1) this._raf = requestAnimationFrame(step)
      else { this._raf = 0; this.set(s, tx, ty, { user }) }
    }
    this._raf = requestAnimationFrame(step)
  }

  serialize () { return { s: +this.s.toFixed(4), x: +this.tx.toFixed(1), y: +this.ty.toFixed(1), w: this.w, h: this.h } }

  restore (v) {
    if (!v || !Number.isFinite(v.s)) return false
    // re-centre relative to the old stage size so rotating / another window size keeps the same centre
    const cx = ((v.w || this.w) / 2 - v.x) / v.s
    const cy = ((v.h || this.h) / 2 - v.y) / v.s
    this.set(v.s, this.w / 2 - cx * v.s, this.h / 2 - cy * v.s)
    return true
  }
}
