// In-place text editing: a positioned <textarea> over the canvas; commits to a Y.Map stroke {tool:'text'}.
// Anchor rule: LTR text grows rightwards from its anchor (left edge), RTL (Hebrew) grows leftwards (right edge).
import * as Y from 'yjs'
import { h, rid } from './util.js'
import { FONT_STACK, LINE_H, detectDir, getEntry, inkColor, labelBox, labelHidden, invalidate } from './render.js'

let measure = null
const textWidth = (line, px) => {
  if (!measure) measure = document.createElement('canvas').getContext('2d')
  measure.font = `500 ${px}px ${FONT_STACK}`
  return measure.measureText(line).width
}

export class TextEditor {
  constructor ({ canvas, session, settings, me, onDone }) {
    this.cv = canvas
    this.session = session
    this.settings = settings
    this.me = me
    this.onDone = onDone || (() => {})
    this.active = false
    this.st = null
    this.ta = h('textarea', {
      class: 'text-editor',
      rows: '1',
      spellcheck: 'false',
      autocomplete: 'off',
      autocapitalize: 'sentences',
      dir: 'auto',
      'aria-label': 'טקסט · Text'
    })
    this.ta.addEventListener('input', () => this.layout())
    this.ta.addEventListener('keydown', e => {
      e.stopPropagation()
      if (e.key === 'Escape') { e.preventDefault(); this.commit() }
      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); this.commit() }
    })
    this.ta.addEventListener('pointerdown', e => e.stopPropagation())
    this.ta.addEventListener('blur', () => setTimeout(() => {
      if (this.active && document.activeElement !== this.ta) this.commit()
    }, 150))
    this._offView = canvas.view.ev.on('change', () => { if (this.active) this.layout() })
    this._onDeep = () => { if (this.active && this.st && this.st.label) this.layout() }
    session.strokes.observeDeep(this._onDeep)
  }

  get defaultDir () { return document.documentElement.dir === 'rtl' ? 'rtl' : 'ltr' }

  create (wx, wy) {
    const size = (this.settings.widths.text || 30) / this.cv.view.s
    this.open({ m: null, x: wx, y: wy - size * 0.62, size, color: this.settings.color, text: '', dir: null, bbox: null })
  }

  edit (m) {
    const e = getEntry(m)
    this.cv.hide(m)
    this.open({ m, x: e.pts[0] || 0, y: e.pts[1] || 0, size: e.width, color: e.color, text: e.text, dir: e.dir || 'ltr', bbox: { ...e.bbox } })
  }

  // Edit the text label INSIDE a rect / ellipse (stored on the shape as label / ldir / lsize).
  editLabel (m) {
    if (this.active) this.commit()
    const e = getEntry(m)
    const size = e.lsize || Math.max(12, Math.min(40, (this.settings.widths.text || 30) / this.cv.view.s))
    this.st = { m, label: true, size, color: e.color, text: e.label || '', dir: e.ldir || null }
    this.active = true
    labelHidden.add(m); invalidate(m); this.cv.dirtyStatic = true; this.cv.schedule()
    const ta = this.ta
    ta.value = this.st.text
    ta.classList.add('label-editor')
    if (!ta.isConnected) this.cv.overlay.append(ta)
    this.layout()
    try { ta.focus({ preventScroll: true }); ta.setSelectionRange(ta.value.length, ta.value.length) } catch {}
    requestAnimationFrame(() => { if (this.active && document.activeElement !== ta) { try { ta.focus({ preventScroll: true }) } catch {} } })
  }

  layoutLabel () {
    const st = this.st
    const { view } = this.cv
    const ta = this.ta
    if (!st.m.doc) { this.cancel(); return }
    const e = getEntry(st.m)
    const b = labelBox({ ...e, lsize: st.size })
    const px = st.size * view.s
    const dir = detectDir(ta.value) || st.dir || this.defaultDir
    st.liveDir = dir
    const w = Math.max(24, b.w * view.s)
    const lines = Math.max(1, Math.ceil(ta.scrollHeight / (px * LINE_H)) || ta.value.split('\n').length)
    const hgt = Math.max(px * LINE_H, Math.min(b.h * view.s, lines * px * LINE_H))
    const col = inkColor(st.color, this.cv.dark)
    ta.setAttribute('dir', dir)
    Object.assign(ta.style, { font: `500 ${px}px ${FONT_STACK}`, lineHeight: String(LINE_H), color: col, caretColor: col, textAlign: 'center', width: w + 'px', height: hgt + 'px' })
    // re-measure after the width is set so wrapping is known
    const h2 = Math.max(px * LINE_H, ta.scrollHeight)
    ta.style.height = h2 + 'px'
    const [sx, sy] = view.toScreen(b.cx, b.cy)
    ta.style.left = (sx - w / 2) + 'px'
    ta.style.top = (sy - h2 / 2) + 'px'
  }

  open (st) {
    if (this.active) this.commit()
    this.st = st
    this.active = true
    const ta = this.ta
    ta.value = st.text || ''
    if (!ta.isConnected) this.cv.overlay.append(ta)
    this.layout()
    const focus = () => {
      try {
        ta.focus({ preventScroll: true })
        const n = ta.value.length
        ta.setSelectionRange(n, n)
      } catch {}
    }
    focus() // synchronous: still inside the tap gesture, so iOS/Android show the keyboard
    requestAnimationFrame(() => { if (this.active && document.activeElement !== ta) focus() })
  }

  layout () {
    const st = this.st
    if (!st) return
    if (st.label) { this.layoutLabel(); return }
    const { view } = this.cv
    const ta = this.ta
    const px = st.size * view.s
    const col = inkColor(st.color, this.cv.dark)
    const dir = detectDir(ta.value) || st.dir || this.defaultDir
    st.liveDir = dir
    // an existing text that flips direction keeps its visual position: anchor moves to the other edge
    st.ax = (st.bbox && st.dir && dir !== st.dir) ? (dir === 'rtl' ? st.bbox.x1 : st.bbox.x0) : st.x
    const lines = ta.value.split('\n')
    let w = px * 1.5
    for (const line of lines) w = Math.max(w, textWidth(line || ' ', px) + px * 0.6)
    w = Math.ceil(w)
    ta.setAttribute('dir', dir)
    Object.assign(ta.style, {
      font: `500 ${px}px ${FONT_STACK}`,
      lineHeight: String(LINE_H),
      color: col,
      caretColor: col,
      textAlign: dir === 'rtl' ? 'right' : 'left',
      width: w + 'px',
      height: Math.ceil(Math.max(1, lines.length) * px * LINE_H + 2) + 'px'
    })
    const [sx, sy] = view.toScreen(st.ax, st.y)
    ta.style.top = sy + 'px'
    ta.style.left = (dir === 'rtl' ? sx - w : sx) + 'px'
  }

  commit () {
    if (!this.active) return
    const st = this.st
    this.active = false
    this.st = null
    const text = this.ta.value.replace(/\s+$/, '')
    const dir = detectDir(text) || st.liveDir || st.dir || this.defaultDir
    const ax = st.ax != null ? st.ax : st.x
    if (this.ta.isConnected) this.ta.remove()
    const { session } = this
    if (st.label) {
      this.ta.classList.remove('label-editor')
      labelHidden.delete(st.m); invalidate(st.m); this.cv.dirtyStatic = true; this.cv.schedule()
      const prev = getEntry(st.m)
      if (st.m.doc && (text !== (prev.label || '') || (text && dir !== prev.ldir))) {
        session.undo.stopCapturing()
        session.doc.transact(() => {
          if (text) { st.m.set('label', text); st.m.set('ldir', dir); if (!st.m.get('lsize')) st.m.set('lsize', +st.size.toFixed(3)) } else { st.m.delete('label'); st.m.delete('ldir') }
        }, session.LOCAL)
        session.undo.stopCapturing()
      }
      this.onDone()
      return
    }
    session.undo.stopCapturing()
    if (st.m) {
      this.cv.unhide(st.m)
      const prev = getEntry(st.m)
      if (!text) {
        session.doc.transact(() => {
          const i = session.strokes.toArray().indexOf(st.m)
          if (i >= 0) session.strokes.delete(i, 1)
        }, session.LOCAL)
      } else if (text !== prev.text || dir !== prev.dir) {
        session.doc.transact(() => {
          if (dir !== prev.dir) st.m.set('points', [ax, st.y])
          st.m.set('text', text)
          st.m.set('dir', dir)
        }, session.LOCAL)
      }
    } else if (text) {
      const m = new Y.Map()
      m.set('id', rid(10))
      m.set('tool', 'text')
      m.set('color', st.color)
      m.set('width', +st.size.toFixed(3))
      m.set('points', [ax, st.y])
      m.set('text', text)
      m.set('dir', dir)
      m.set('author', this.me.id)
      m.set('t', Date.now())
      session.doc.transact(() => session.strokes.push([m]), session.LOCAL)
    }
    session.undo.stopCapturing()
    this.onDone()
  }

  cancel () {
    if (!this.active) return
    const st = this.st
    this.active = false
    this.st = null
    if (this.ta.isConnected) this.ta.remove()
    this.ta.classList.remove('label-editor')
    if (st && st.label) { labelHidden.delete(st.m); invalidate(st.m); this.cv.dirtyStatic = true; this.cv.schedule() } else if (st && st.m) this.cv.unhide(st.m)
    this.onDone()
  }

  destroy () {
    this.cancel()
    this._offView()
    try { this.session.strokes.unobserveDeep(this._onDeep) } catch {}
  }
}
