// IMAGES: file picker / drag-and-drop / clipboard paste -> downscaled, content-addressed assets.
//
// Y.Doc shape:
//   doc.getMap('assets') : 'sha256-<hex>' -> 'data:image/<type>;base64,...'   (<= 1.5 MB binary, <= 2048 px/side)
//   an image object in 'strokes': { id, tool:'image', asset:<key>, iw, ih, points:[x0,y0,x1,y1] }  (world rect)
// Assets live outside the undo scope (undo removes/restores the object; its bytes stay addressable), are
// written in the SAME transaction as the object (so a remote device never sees an object without its asset),
// sync like everything else and persist offline through y-indexeddb. Same bytes = same key = stored once.
import * as Y from 'yjs'
import { h, rid } from './util.js'
import { toast } from './ui.js'
import { setAssetData, onImageReady, IMAGE_DATA_RE } from './render.js'
import { registerObjectType, registerRoot } from './board-format.js'

registerObjectType('image')
registerRoot('assets')

export const ACCEPT = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']
const MAX_IN = 10 * 1024 * 1024
const MAX_OUT = 1.5 * 1024 * 1024
const MAX_SIDE = 2048
const r3 = v => Math.round(v * 1000) / 1000

export const assetsMap = doc => doc.getMap('assets')

async function hashKey (buf) {
  if (globalThis.crypto && crypto.subtle && crypto.subtle.digest) {
    const d = await crypto.subtle.digest('SHA-256', buf)
    return 'sha256-' + [...new Uint8Array(d)].map(b => b.toString(16).padStart(2, '0')).join('')
  }
  // insecure-context fallback (never on https / localhost): two FNV-1a lanes
  const a = new Uint8Array(buf)
  let h1 = 0x811c9dc5; let h2 = 0x01000193 ^ a.length
  for (let i = 0; i < a.length; i++) { h1 = Math.imul(h1 ^ a[i], 16777619); h2 = Math.imul(h2 ^ a[i], 2246822519) }
  return 'fnv-' + (h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0') + a.length.toString(16)
}

function loadImg (blob) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob)
    const img = new Image()
    img.onload = () => { URL.revokeObjectURL(url); resolve(img) }
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('decode')) }
    img.src = url
  })
}
const toBlob = (c, type, q) => new Promise(resolve => { try { c.toBlob(b => resolve(b), type, q) } catch { resolve(null) } })
const toDataURL = blob => new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(String(r.result)); r.onerror = reject; r.readAsDataURL(blob) })

// Downscale to <= 2048 px per side and re-encode until <= 1.5 MB (small originals are kept byte-for-byte).
async function encode (file) {
  const img = await loadImg(file)
  const w = img.naturalWidth; const hh = img.naturalHeight
  if (!w || !hh) throw new Error('decode')
  if (Math.max(w, hh) <= MAX_SIDE && file.size <= MAX_OUT) return { blob: file, w, h: hh }
  const alpha = file.type !== 'image/jpeg'
  let scale = Math.min(1, MAX_SIDE / Math.max(w, hh))
  for (let attempt = 0; attempt < 10; attempt++) {
    const cw = Math.max(1, Math.round(w * scale)); const ch = Math.max(1, Math.round(hh * scale))
    const c = document.createElement('canvas')
    c.width = cw; c.height = ch
    const ctx = c.getContext('2d')
    if (!alpha) { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, cw, ch) }
    ctx.imageSmoothingQuality = 'high'
    ctx.drawImage(img, 0, 0, cw, ch)
    for (const q of [0.9, 0.82, 0.72, 0.6]) {
      let b = await toBlob(c, 'image/webp', q)
      if (!b || b.type !== 'image/webp') b = await toBlob(c, alpha ? 'image/png' : 'image/jpeg', q)
      if (b && b.size <= MAX_OUT) return { blob: b, w: cw, h: ch }
      if (b && b.type === 'image/png') break // png ignores quality: shrink instead
    }
    scale *= 0.75
  }
  throw new Error('too-big')
}

export function installImages ({ session, cv, input, selection, me }) {
  const amap = assetsMap(session.doc)
  amap.forEach((v, k) => setAssetData(k, v))
  const onAssets = ev => ev.keysChanged.forEach(k => setAssetData(k, amap.get(k)))
  amap.observe(onAssets)
  const offReady = onImageReady(() => { cv.dirtyStatic = true; cv.schedule() })

  function place (key, dataURL, w, hh, at, i) {
    const s = cv.view.s
    let ww = w / s; let wh = hh / s
    const k = Math.min(1, (cv.W * 0.6 / s) / ww, (cv.H * 0.6 / s) / wh)
    ww *= k; wh *= k
    let [cx, cy] = at || cv.view.toWorld(cv.W / 2, cv.H / 2)
    cx += (i * 24) / s; cy += (i * 24) / s
    const m = new Y.Map()
    m.set('id', rid(10))
    m.set('tool', 'image')
    m.set('asset', key)
    m.set('iw', w)
    m.set('ih', hh)
    m.set('points', [r3(cx - ww / 2), r3(cy - wh / 2), r3(cx + ww / 2), r3(cy + wh / 2)])
    m.set('author', me.id)
    m.set('t', Date.now())
    session.undo.stopCapturing()
    session.doc.transact(() => {
      if (!amap.has(key)) amap.set(key, dataURL)
      session.strokes.push([m])
    }, session.LOCAL)
    session.undo.stopCapturing()
    return m
  }

  async function addFiles (files, at) {
    const list = [...files]
    if (!list.length) return 0
    if (input.canDraw && !input.canDraw('pen')) return 0 // [layers] locked / hidden active layer
    const added = []
    let i = 0
    for (const f of list) {
      if (!ACCEPT.includes(f.type)) { toast('סוג קובץ לא נתמך — אפשר להוסיף רק PNG, JPEG, WebP או GIF', { kind: 'warn', timeout: 3600 }); continue }
      if (f.size > MAX_IN) { toast(`התמונה "${String(f.name || '').slice(0, 40)}" גדולה מדי (מעל 10MB)`, { kind: 'warn', timeout: 3600 }); continue }
      try {
        const { blob, w, h: hh } = await encode(f)
        const buf = await blob.arrayBuffer()
        const key = await hashKey(buf)
        const url = await toDataURL(blob)
        if (!IMAGE_DATA_RE.test(url)) throw new Error('type')
        setAssetData(key, url)
        added.push(place(key, url, w, hh, at, i++))
      } catch (e) {
        console.warn('[images]', e)
        toast('לא הצלחנו לקרוא את התמונה', { kind: 'warn', timeout: 3000 })
      }
    }
    if (added.length) {
      input.ev.emit('undo-changed')
      if (selection) {
        if (selection.onWantSelect) selection.onWantSelect()
        selection.set(added)
      }
      toast(added.length === 1 ? 'התמונה נוספה · Image added' : `נוספו ${added.length} תמונות`, { key: 'img', timeout: 1400 })
    }
    return added.length
  }

  // ---------------------------------------------------------------- picker
  const picker = h('input', { type: 'file', accept: ACCEPT.join(','), multiple: true, style: { display: 'none' } })
  picker.addEventListener('change', () => { const fs = [...picker.files]; picker.value = ''; addFiles(fs, null) })
  document.body.append(picker)
  const pick = () => picker.click()

  // ---------------------------------------------------------------- drag and drop
  const st = cv.stage
  const hasFiles = e => !!(e.dataTransfer && [...(e.dataTransfer.types || [])].includes('Files'))
  const onOver = e => { if (hasFiles(e)) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; st.classList.add('drop-on') } }
  const onLeave = () => st.classList.remove('drop-on')
  const onDrop = e => {
    st.classList.remove('drop-on')
    if (!hasFiles(e)) return
    e.preventDefault()
    const r = st.getBoundingClientRect()
    addFiles(e.dataTransfer.files, cv.view.toWorld(e.clientX - r.left, e.clientY - r.top))
  }
  st.addEventListener('dragover', onOver)
  st.addEventListener('dragleave', onLeave)
  st.addEventListener('drop', onDrop)

  // ---------------------------------------------------------------- clipboard (called by selection's paste router)
  const pasteHandler = (dt, at) => {
    const files = [...(dt.files || [])].filter(f => f.type && f.type.startsWith('image/'))
    if (!files.length) return false
    addFiles(files, at)
    return true
  }
  if (selection) selection.pasteHandlers.push(pasteHandler)

  return {
    pick,
    addFiles,
    destroy () {
      try { amap.unobserve(onAssets) } catch {}
      offReady()
      picker.remove()
      st.removeEventListener('dragover', onOver)
      st.removeEventListener('dragleave', onLeave)
      st.removeEventListener('drop', onDrop)
      if (selection) selection.pasteHandlers = selection.pasteHandlers.filter(f => f !== pasteHandler)
    }
  }
}
