// QR codes rendered as crisp inline SVG from the bundled `qrcode` lib (works offline, scales to any size).
import QR from 'qrcode'

const cache = new Map()

export function qrSVG (text, { ecl = 'M', margin = 2, dark = '#0b0d1a', light = '#ffffff', label = '' } = {}) {
  const key = [text, ecl, margin, dark, light].join('|')
  let d = cache.get(key)
  let total
  if (!d) {
    const q = QR.create(String(text), { errorCorrectionLevel: ecl })
    const size = q.modules.size
    const data = q.modules.data
    let path = ''
    for (let y = 0; y < size; y++) {
      let x = 0
      while (x < size) {
        if (!data[y * size + x]) { x++; continue }
        let run = 1
        while (x + run < size && data[y * size + x + run]) run++
        path += `M${x + margin} ${y + margin}h${run}v1h-${run}z`
        x += run
      }
    }
    total = size + margin * 2
    d = { path, total }
    if (cache.size > 24) cache.clear()
    cache.set(key, d)
  }
  total = d.total
  const aria = label ? ` role="img" aria-label="${label.replace(/"/g, '&quot;')}"` : ' aria-hidden="true"'
  return `<svg class="qr-svg" viewBox="0 0 ${total} ${total}" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg"${aria}><rect width="${total}" height="${total}" fill="${light}"/><path d="${d.path}" fill="${dark}"/></svg>`
}

export function qrElement (text, opts = {}) {
  const wrap = document.createElement('div')
  wrap.className = 'qr ' + (opts.className || '')
  wrap.innerHTML = qrSVG(text, opts)
  return wrap
}
