// Imported first: tiny compat shims for older TV browsers (Tizen / webOS Chromium 6x-7x).
/* eslint-disable no-extend-native */
if (typeof globalThis === 'undefined') {
  try { window.globalThis = window } catch {}
}
if (typeof queueMicrotask !== 'function') {
  window.queueMicrotask = fn => Promise.resolve().then(fn)
}
if (!Element.prototype.closest) {
  Element.prototype.closest = function (sel) {
    let el = this
    while (el && el.nodeType === 1) { if (el.matches(sel)) return el; el = el.parentElement }
    return null
  }
}
if (typeof Element.prototype.replaceChildren !== 'function') {
  Element.prototype.replaceChildren = function (...nodes) {
    while (this.firstChild) this.removeChild(this.firstChild)
    this.append(...nodes)
  }
}
