// PWA plumbing: service worker registration + update prompt, install prompt, fullscreen, wake lock.
import { emitter, isIOS, isStandalone, h } from './util.js'
import { toast, modal } from './ui.js'
import { icon } from './icons.js'

export const pwa = {
  ev: emitter(),
  deferred: null,
  installed: false,
  reg: null
}

const secure = () => window.isSecureContext || location.hostname === 'localhost' || location.hostname === '127.0.0.1'

export function initPWA () {
  addEventListener('beforeinstallprompt', e => {
    e.preventDefault()
    pwa.deferred = e
    pwa.ev.emit('change')
  })
  addEventListener('appinstalled', () => {
    pwa.deferred = null
    pwa.installed = true
    pwa.ev.emit('change')
    toast('האפליקציה הותקנה ✓ · App installed')
  })
  if ('serviceWorker' in navigator && secure()) {
    if (document.readyState === 'complete') registerSW()
    else addEventListener('load', registerSW, { once: true })
  }
}

let wantReload = false
async function registerSW () {
  try {
    const reg = await navigator.serviceWorker.register('/sw.js', { scope: '/' })
    pwa.reg = reg
    const offer = w => {
      if (!w || !navigator.serviceWorker.controller) return // first install: nothing to replace
      toast('גרסה חדשה זמינה · Update ready', {
        timeout: 0,
        actionLabel: 'רענון',
        action: () => { wantReload = true; w.postMessage({ type: 'SKIP_WAITING' }) }
      })
    }
    if (reg.waiting) offer(reg.waiting)
    reg.addEventListener('updatefound', () => {
      const w = reg.installing
      if (!w) return
      w.addEventListener('statechange', () => { if (w.state === 'installed') offer(w) })
    })
    navigator.serviceWorker.addEventListener('controllerchange', () => { if (wantReload) location.reload() })
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') reg.update().catch(() => {})
    })
  } catch (e) {
    console.warn('[couchboard] service worker not registered:', e && e.message)
  }
}

export const canInstall = () => !!pwa.deferred
export const canAddToHomeIOS = () => isIOS && !isStandalone()

export async function promptInstall () {
  if (pwa.deferred) {
    const d = pwa.deferred
    pwa.deferred = null
    pwa.ev.emit('change')
    try {
      d.prompt()
      const r = await d.userChoice
      if (r && r.outcome === 'accepted') toast('מתקין… · Installing')
    } catch {}
    return
  }
  showAddToHomeHint()
}

export function showAddToHomeHint (reason = '') {
  const steps = isIOS
    ? [
        ['share', 'לחצו על כפתור השיתוף בסרגל של Safari', 'Tap Safari’s Share button'],
        ['plus', 'בחרו "הוספה למסך הבית"', 'Choose “Add to Home Screen”'],
        ['check', 'פתחו את Couch Board מהמסך הראשי — במסך מלא', 'Open it from the home screen — full screen']
      ]
    : [
        ['more', 'פתחו את תפריט הדפדפן ⋮', 'Open the browser menu ⋮'],
        ['install', 'בחרו "התקנת אפליקציה" או "הוספה למסך הבית"', 'Choose “Install app” / “Add to Home screen”'],
        ['check', 'האפליקציה תיפתח במסך מלא ותעבוד גם בלי רשת', 'It opens full screen and works offline']
      ]
  modal({
    title: isIOS ? 'הוספה למסך הבית' : 'התקנת האפליקציה',
    body: h('div', { class: 'a2hs' },
      reason ? h('p', { class: 'modal-text' }, reason) : null,
      h('ol', { class: 'steps' }, steps.map(([ic, he, en], i) =>
        h('li', null,
          h('span', { class: 'step-n' }, String(i + 1)),
          h('span', { class: 'step-ic' }, icon(ic)),
          h('span', { class: 'step-t' }, h('b', null, he), h('small', { dir: 'ltr' }, en))
        )))
    ),
    actions: [{ label: 'הבנתי', kind: 'primary', autofocus: true }]
  })
}

// ------------------------------------------------------------------ fullscreen
const de = () => document.documentElement
export const fullscreenSupported = () => !!(de().requestFullscreen || de().webkitRequestFullscreen)
export const isFullscreen = () => !!(document.fullscreenElement || document.webkitFullscreenElement)

export async function toggleFullscreen () {
  if (!fullscreenSupported()) {
    if (isStandalone()) { toast('האפליקציה כבר במסך מלא'); return }
    showAddToHomeHint(isIOS
      ? 'ב-iPhone הדפדפן לא תומך במסך מלא לדפים. הוסיפו את Couch Board למסך הבית — היא תיפתח במסך מלא.'
      : 'הדפדפן הזה לא תומך במסך מלא. התקינו את האפליקציה כדי לקבל מסך מלא.')
    return
  }
  try {
    if (isFullscreen()) {
      if (document.exitFullscreen) await document.exitFullscreen()
      else if (document.webkitExitFullscreen) document.webkitExitFullscreen()
    } else {
      const el = de()
      if (el.requestFullscreen) await el.requestFullscreen({ navigationUI: 'hide' })
      else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen()
    }
  } catch (e) {
    toast('לא הצלחנו לעבור למסך מלא')
  }
}

export function onFullscreenChange (fn) {
  document.addEventListener('fullscreenchange', fn)
  document.addEventListener('webkitfullscreenchange', fn)
  return () => {
    document.removeEventListener('fullscreenchange', fn)
    document.removeEventListener('webkitfullscreenchange', fn)
  }
}

// ------------------------------------------------------------------ wake lock (TV mode keeps the screen on)
export function keepAwake () {
  let lock = null
  let stopped = false
  const req = async () => {
    if (stopped || !('wakeLock' in navigator) || document.visibilityState !== 'visible') return
    try { lock = await navigator.wakeLock.request('screen') } catch {}
  }
  const onVis = () => { if (document.visibilityState === 'visible') req() }
  document.addEventListener('visibilitychange', onVis)
  req()
  return () => {
    stopped = true
    document.removeEventListener('visibilitychange', onVis)
    try { if (lock) lock.release() } catch {}
  }
}
