// Share sheet (big QR + code + link) and the "Show on TV" helper.
import { h, boardUrl, copyText } from './util.js'
import { modal, toast } from './ui.js'
import { qrElement } from './qr.js'
import { icon } from './icons.js'

const prettyUrl = u => u.replace(/^https?:\/\//, '')

function codeBlock (code) {
  return h('div', { class: 'code-big', dir: 'ltr', 'aria-label': 'קוד הלוח ' + code.split('').join(' ') },
    code.split('').map(ch => h('span', null, ch)))
}

async function nativeShare (data) {
  if (!navigator.share) return false
  try { await navigator.share(data); return true } catch (e) { return e && e.name === 'AbortError' }
}

export function openShare ({ code, title }) {
  const url = boardUrl(code)
  const copyBtn = h('button', { class: 'btn', type: 'button' }, icon('copy'), 'העתקת קישור')
  copyBtn.onclick = async () => {
    const ok = await copyText(url)
    copyBtn.replaceChildren(icon(ok ? 'check' : 'x'), ok ? 'הועתק!' : 'לא הצלחנו להעתיק')
    setTimeout(() => copyBtn.replaceChildren(icon('copy'), 'העתקת קישור'), 1800)
  }
  const shareBtn = navigator.share
    ? h('button', { class: 'btn primary', type: 'button', onclick: () => nativeShare({ title: 'Couch Board · ' + (title || code), text: `בואו לצייר איתי על הלוח · קוד ${code}`, url }) }, icon('share'), 'שיתוף…')
    : null
  const body = h('div', { class: 'share' },
    h('div', { class: 'share-qr' }, qrElement(url, { ecl: 'M', margin: 2, label: 'QR ' + url })),
    h('div', { class: 'share-side' },
      h('p', { class: 'share-lead' }, 'סרקו עם המצלמה של הטלפון, או הקלידו את הקוד במסך הבית'),
      codeBlock(code),
      h('div', { class: 'share-url', dir: 'ltr' }, prettyUrl(url)),
      h('div', { class: 'share-actions' }, shareBtn, copyBtn)
    )
  )
  return modal({ title: 'הזמנה ללוח · Invite', body, wide: true, className: 'share-modal' })
}

export function openTvHelper ({ code, title, onOpenHere }) {
  const tvUrl = boardUrl(code, { tv: true })
  const copyBtn = h('button', { class: 'btn', type: 'button' }, icon('copy'), 'העתקה')
  copyBtn.onclick = async () => {
    const ok = await copyText(tvUrl)
    copyBtn.replaceChildren(icon(ok ? 'check' : 'x'), ok ? 'הועתק!' : 'לא הצלחנו')
    setTimeout(() => copyBtn.replaceChildren(icon('copy'), 'העתקה'), 1800)
  }
  let m = null
  const body = h('div', { class: 'tvhelp' },
    h('ol', { class: 'steps' },
      h('li', null, h('span', { class: 'step-n' }, '1'), h('span', { class: 'step-t' },
        h('b', null, 'בדפדפן של הטלוויזיה פתחו את הכתובת:'),
        h('div', { class: 'tv-url', dir: 'ltr' }, prettyUrl(tvUrl)),
        h('small', null, 'הטלוויזיה תציג את הלוח במסך מלא עם קוד QR בפינה. אפשר לשלוט בשלט: חיצים + OK.')
      )),
      h('li', null, h('span', { class: 'step-n' }, '2'), h('span', { class: 'step-t' },
        h('b', null, 'כולם סורקים את הקוד שעל המסך'),
        h('small', null, 'כל טלפון שסורק מצטרף לאותו לוח. אפשר גם כמה טלוויזיות.')
      ))
    ),
    h('div', { class: 'tv-actions' },
      copyBtn,
      navigator.share ? h('button', { class: 'btn', type: 'button', onclick: () => nativeShare({ title: 'Couch Board TV', url: tvUrl }) }, icon('share'), 'שליחה למכשיר') : null,
      h('button', { class: 'btn primary', type: 'button', onclick: () => { m.close(); onOpenHere() } }, icon('tv'), 'המסך הזה הוא הטלוויזיה')
    ),
    h('p', { class: 'fine' }, 'טיפ: מחשב שמחובר לטלוויזיה ב-HDMI? לחצו "המסך הזה הוא הטלוויזיה" ואז מסך מלא.')
  )
  m = modal({ title: 'הצגה בטלוויזיה · Show on TV', body, className: 'tv-modal' })
  return m
}

export function copyBoardLink (code) {
  copyText(boardUrl(code)).then(ok => toast(ok ? 'הקישור הועתק' : 'לא הצלחנו להעתיק'))
}
