// The board screen: session + canvas + input + presence + chrome (top bar, toolbar, menus) + TV mode.
import { createSession } from './sync.js'
import { BoardCanvas } from './canvas.js'
import { Input } from './input.js'
import { Presence } from './presence.js'
import { TextEditor } from './text.js'
import { h, debounce, isTypingTarget, isTouch, isIOS, isStandalone, boardUrl, clamp } from './util.js'
import { icon } from './icons.js'
import { toast, modal, confirmDialog, promptDialog, popover, closePopover, popoverOpen, popoverJustClosed, anyModalOpen, spatialMove } from './ui.js'
import { PALETTE, getSettings, saveSettings, WIDTH_RANGE, widthKey, getSavedView, saveView, touchRecent, seenOnce, getMe, KIND_EMOJI, KIND_NAME } from './prefs.js'
import { BG_KEYS, renderToCanvas, isDarkBg, inkColor } from './render.js'
import { openShare, openTvHelper, copyBoardLink } from './share.js'
import { qrSVG } from './qr.js'
import { toggleFullscreen, isFullscreen, onFullscreenChange, keepAwake, canInstall, canAddToHomeIOS, promptInstall, pwa } from './pwa.js'
import { openProfile, avatar } from './profile.js'
import { openSaves } from './saves.js' // [saves] named saves / file export-import panel
import { Selection } from './selection.js' // [selection] select / move / resize / group / align
import { installLayersUI } from './layers-panel.js' // [layers] panel + per-layer renderer
import { installImages } from './images.js' // [images] picker / drop / paste

const TOOLS = {
  select: { icon: 'select', he: 'בחירה', en: 'Select', key: 'V' }, // [selection]
  pen: { icon: 'pen', he: 'עט', en: 'Pen', key: 'P' },
  highlighter: { icon: 'highlighter', he: 'מרקר', en: 'Highlighter', key: 'H' },
  eraser: { icon: 'eraser', he: 'מחק', en: 'Eraser', key: 'E' },
  line: { icon: 'line', he: 'קו', en: 'Line', key: 'L' },
  arrow: { icon: 'arrow', he: 'חץ', en: 'Arrow', key: 'A' },
  rect: { icon: 'rect', he: 'מלבן', en: 'Rectangle', key: 'R' },
  ellipse: { icon: 'ellipse', he: 'עיגול', en: 'Ellipse', key: 'O' },
  text: { icon: 'text', he: 'טקסט', en: 'Text', key: 'T' },
  laser: { icon: 'laser', he: 'לייזר', en: 'Laser', key: 'K' },
  hand: { icon: 'hand', he: 'הזזה', en: 'Pan', key: 'M' }
}
const INLINE_TOOLS = ['select', 'pen', 'highlighter', 'eraser', 'line', 'arrow', 'rect', 'ellipse', 'text', 'laser', 'hand']
const GROUP_TOOLS = ['select', 'text', 'line', 'arrow', 'rect', 'ellipse', 'laser', 'hand']
const PHONE_TOOLS = ['pen', 'highlighter', 'eraser']
const BG_INFO = {
  white: { icon: 'square', he: 'לבן', en: 'White' },
  grid: { icon: 'grid', he: 'משבצות', en: 'Grid' },
  dots: { icon: 'dots', he: 'נקודות', en: 'Dots' },
  dark: { icon: 'moon', he: 'כהה', en: 'Dark' }
}
const BACK_KEYS = new Set(['Escape', 'Backspace', 'GoBack', 'BrowserBack', 'XF86Back'])
const BACK_CODES = new Set([10009, 461, 8, 27])

const label = (t) => `${t.he} · ${t.en}${t.key ? ` (${t.key})` : ''}`

export function openBoard (app, code, { tv = false } = {}) {
  const baseMe = getMe()
  const me = { ...baseMe }
  if (tv) { me.kind = 'tv'; if (baseMe.auto) me.name = 'טלוויזיה' }
  const settings = getSettings()
  if (!TOOLS[settings.tool]) settings.tool = 'pen'
  // TV view has no toolbar: it draws with the pen (touch TV, laptop on HDMI, pointer remote) and its
  // remote bar toggles draw <-> pan. This choice is per-view and never overwrites the device's settings.
  if (tv) settings.tool = 'pen'

  // ---------------------------------------------------------------- DOM skeleton
  const root = h('div', { class: 'board' + (tv ? ' tv-mode' : ''), dataset: { tool: settings.tool } })
  const stage = h('div', { class: 'stage', dataset: { bg: 'white' } })
  root.append(stage)
  app.mount(root)
  document.title = `Couch Board · ${code}`

  const session = createSession(code, me)
  const cv = new BoardCanvas(stage, session)
  const input = new Input({ stage, canvas: cv, session, settings, me, tv })
  const presence = new Presence({ session, canvas: cv, me, tv })
  const textEd = new TextEditor({ canvas: cv, session, settings, me, onDone: () => {} })
  input.textEditor = textEd
  const selection = new Selection({ canvas: cv, session, input, root, me }) // [selection]
  input.selection = selection
  const layersUI = installLayersUI({ session, cv, input, selection, code }) // [layers]
  selection.layersUI = layersUI
  selection.onWantSelect = () => setTool('select') // [clipboard] paste lands selected
  const images = tv ? null : installImages({ session, cv, input, selection, me }) // [images]
  input.blockDown = () => popoverJustClosed()
  input.ev.on('laser-point', (x, y) => presence.addLocalLaser(x, y))

  let users = [] // presence list (declared early: status painters read it)
  const cleanups = []
  const on = (target, ev, fn, opts) => { target.addEventListener(ev, fn, opts); cleanups.push(() => target.removeEventListener(ev, fn, opts)) }

  // ---------------------------------------------------------------- meta (title / bg)
  const titleOf = () => (session.meta.get('title') || '').trim() || `לוח ${code}`
  const applyMeta = () => {
    const bg = BG_KEYS.includes(session.meta.get('bg')) ? session.meta.get('bg') : 'white'
    cv.setBackground(bg)
    root.dataset.bg = bg
    root.classList.toggle('bg-dark', isDarkBg(bg))
    if (titleEl) titleEl.textContent = titleOf()
    document.title = `${titleOf()} · Couch Board`
    paintSwatches()
    touchRecent(code, { title: session.meta.get('title') || '' })
  }
  session.meta.observe(applyMeta)
  const setMeta = (k, v) => session.doc.transact(() => session.meta.set(k, v), 'meta')

  // ---------------------------------------------------------------- chrome: top bar
  let titleEl = null
  const statusDot = h('span', { class: 'sdot', 'data-s': 'connecting' })
  const statusText = h('span', { class: 'stext' }, 'מתחבר…')
  const statusBtn = h('button', { class: 'chip status-chip', type: 'button', 'aria-label': 'מצב חיבור · Connection', title: 'מצב חיבור · Connection' }, statusDot, statusText)
  const devCount = h('span', { class: 'dcount' }, '1')
  const devAvatars = h('span', { class: 'avatars' })
  const devBtn = h('button', { class: 'chip devices-chip', type: 'button', 'aria-label': 'מכשירים מחוברים · Devices', title: 'מכשירים מחוברים · Devices' }, devAvatars, devCount, h('span', { class: 'dlabel' }, ' מחוברים'))

  const homeBtn = h('button', { class: 'icon-btn', type: 'button', 'aria-label': 'כל הלוחות · Home', title: 'כל הלוחות · Home', onclick: () => app.navigate('/') }, icon('home'))
  titleEl = h('span', { class: 'title-text' }, titleOf())
  const titleBtn = h('button', { class: 'title-chip', type: 'button', title: 'שינוי שם · Rename', 'aria-label': 'שם הלוח · Board name' }, titleEl, icon('edit', 'tiny'))
  const codeBtn = h('button', { class: 'code-chip', type: 'button', dir: 'ltr', title: 'הזמנה · Invite', 'aria-label': 'קוד הלוח ' + code }, code)

  const shareBtn = h('button', { class: 'btn primary small share-btn', type: 'button', 'aria-label': 'הזמנה · Invite', title: 'הזמנה · Invite (QR)' }, icon('qr'), h('span', { class: 'lbl-wide' }, 'הזמנה'))
  const tvBtn = h('button', { class: 'icon-btn wide-only', type: 'button', 'aria-label': 'הצגה בטלוויזיה · Show on TV', title: 'הצגה בטלוויזיה · Show on TV' }, icon('tv'))
  const fsBtn = h('button', { class: 'icon-btn wide-only', type: 'button', 'aria-label': 'מסך מלא · Fullscreen', title: 'מסך מלא · Fullscreen (F)' }, icon('fullscreen'))
  const moreBtn = h('button', { class: 'icon-btn', type: 'button', 'aria-label': 'עוד · More', title: 'עוד · More', 'aria-haspopup': 'true' }, icon('more'))

  const topbar = h('header', { class: 'topbar' },
    h('div', { class: 'tb-group tb-start' }, homeBtn, h('div', { class: 'title-wrap' }, titleBtn, codeBtn)),
    h('div', { class: 'tb-group tb-end' }, statusBtn, devBtn, shareBtn, tvBtn, fsBtn, moreBtn)
  )

  // ---------------------------------------------------------------- chrome: toolbar
  const toolBtns = new Map() // tool -> [buttons]
  const mkTool = (t, cls = '') => {
    const T = TOOLS[t]
    const b = h('button', { class: 'tool ' + cls, type: 'button', dataset: { tool: t }, 'aria-label': label(T), title: label(T), 'aria-pressed': 'false' }, icon(T.icon))
    b.addEventListener('click', () => onToolClick(t, b))
    if (!toolBtns.has(t)) toolBtns.set(t, [])
    toolBtns.get(t).push(b)
    return b
  }
  const groupBtn = h('button', { class: 'tool group narrow-only', type: 'button', 'aria-label': 'צורות ועוד · Shapes', title: 'צורות ועוד · Shapes', 'aria-haspopup': 'true' },
    h('span', { class: 'gicon' }, icon('shapes')), h('span', { class: 'gcaret' }, icon('chevronDown', 'tiny')))
  groupBtn.addEventListener('click', () => openGroup())

  const swatchRow = h('div', { class: 'tb-swatches xwide-only' })
  const styleDot = h('span', { class: 'style-dot' })
  const styleBtn = h('button', { class: 'tool style-btn', type: 'button', 'aria-label': 'צבע ועובי · Color & size', title: 'צבע ועובי · Color & size', 'aria-haspopup': 'true' }, styleDot)
  styleBtn.addEventListener('click', () => openStyle())

  const layersBtn = h('button', { class: 'tool layers-btn', type: 'button', 'aria-label': 'שכבות · Layers', title: 'שכבות · Layers', 'aria-haspopup': 'true' }, icon('layers'))
  layersBtn.addEventListener('click', () => layersUI.openPanel(layersBtn))
  const paintLayersBtn = () => {
    const n = layersUI.state.list.length
    const cur = layersUI.state.byId.get(layersUI.activeId())
    layersBtn.title = `שכבות · Layers — פעילה: ${cur ? cur.name : ''}`
    layersBtn.setAttribute('aria-label', layersBtn.title)
    const old = layersBtn.querySelector('.lyr-n')
    if (old) old.remove()
    if (n > 1) layersBtn.append(h('span', { class: 'lyr-n' }, String(n)))
  }
  layersUI.onChange(paintLayersBtn)
  const imageBtn = h('button', { class: 'tool image-btn', type: 'button', 'aria-label': 'הוספת תמונה · Image', title: 'הוספת תמונה · Image (PNG/JPEG/WebP/GIF)' }, icon('image'))
  imageBtn.addEventListener('click', () => images && images.pick())
  paintLayersBtn()

  const undoBtn = h('button', { class: 'tool', type: 'button', 'aria-label': 'ביטול · Undo (Ctrl+Z)', title: 'ביטול · Undo (Ctrl+Z)', disabled: true, onclick: () => doUndo() }, icon('undo', 'flip'))
  const redoBtn = h('button', { class: 'tool', type: 'button', 'aria-label': 'חזרה · Redo (Ctrl+Shift+Z)', title: 'חזרה · Redo (Ctrl+Shift+Z)', disabled: true, onclick: () => doRedo() }, icon('redo', 'flip'))

  const toolbar = h('nav', { class: 'toolbar', 'aria-label': 'כלים · Tools' },
    h('div', { class: 'tb-tools' },
      INLINE_TOOLS.map(t => mkTool(t, PHONE_TOOLS.includes(t) ? '' : 'wide-only')),
      groupBtn
    ),
    h('span', { class: 'tb-sep' }),
    swatchRow,
    styleBtn,
    layersBtn,
    imageBtn,
    h('span', { class: 'tb-sep' }),
    undoBtn, redoBtn
  )

  // zoom pill
  const zoomPct = h('button', { class: 'zoom-pct', type: 'button', title: 'התאמה לתוכן · Fit (0)', 'aria-label': 'התאמה לתוכן · Fit' }, '100%')
  const zoomPill = h('div', { class: 'zoom-pill' },
    h('button', { class: 'icon-btn small wide-only', type: 'button', 'aria-label': 'הקטנה · Zoom out', title: 'הקטנה · Zoom out (-)', onclick: () => cv.view.zoomCenter(1 / 1.25) }, icon('minus')),
    zoomPct,
    h('button', { class: 'icon-btn small wide-only', type: 'button', 'aria-label': 'הגדלה · Zoom in', title: 'הגדלה · Zoom in (+)', onclick: () => cv.view.zoomCenter(1.25) }, icon('plus'))
  )
  zoomPct.addEventListener('click', () => fitContent(true))

  const emptyHint = h('div', { class: 'empty-hint', 'aria-hidden': 'true' },
    h('div', { class: 'eh-art', html: '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M10 46c8-14 14 4 22-8s12 2 20-8"/><path d="M44 16l6-6 4 4-6 6z"/><path d="M41 19l4 4"/></svg>' }),
    h('b', null, 'הלוח ריק — תתחילו לצייר'),
    h('span', null, isTouch() ? 'אצבע אחת מציירת · שתי אצבעות מזיזות וזום' : 'גררו כדי לצייר · גלגלת = הזזה · Ctrl+גלגלת = זום'),
    h('button', { class: 'btn small eh-invite', type: 'button', onclick: () => openShare({ code, title: titleOf() }) }, icon('qr'), 'הזמינו עוד מכשירים')
  )
  const chrome = h('div', { class: 'chrome' }, emptyHint, topbar, toolbar, zoomPill)
  if (!tv) root.append(chrome)

  // ---------------------------------------------------------------- TV chrome
  let tvCorner = null; let tvWelcome = null; let tvBar = null; let tvCount = null
  let tvDrawBtn = null; let tvFsBtn = null; let tvUndoBtn = null
  let releaseWake = null
  if (tv) buildTV()

  function buildTV () {
    const url = boardUrl(code)
    tvCount = h('span', { class: 'tv-count' }, '')
    tvCorner = h('aside', { class: 'tv-corner', 'aria-label': 'הצטרפות · Join' },
      h('div', { class: 'tv-qr', html: qrSVG(url, { ecl: 'M', margin: 2 }) }),
      h('div', { class: 'tv-info' },
        h('div', { class: 'tv-join' }, 'סרקו כדי לצייר'),
        h('div', { class: 'tv-code', dir: 'ltr' }, code),
        h('div', { class: 'tv-url', dir: 'ltr' }, location.host + '/b/' + code),
        tvCount
      )
    )
    tvWelcome = h('div', { class: 'tv-welcome' },
      h('div', { class: 'tvw-card' },
        h('div', { class: 'tvw-qr', html: qrSVG(url, { ecl: 'M', margin: 2 }) }),
        h('div', { class: 'tvw-side' },
          h('h1', null, '📺 ', h('span', null, titleOf())),
          h('p', { class: 'tvw-lead' }, 'סרקו את הקוד עם המצלמה של הטלפון וציירו על המסך הגדול'),
          h('div', { class: 'tvw-or' }, 'או היכנסו לאתר והקלידו את הקוד:'),
          h('div', { class: 'tvw-code', dir: 'ltr' }, code.split('').map(c => h('span', null, c))),
          h('div', { class: 'tvw-url', dir: 'ltr' }, location.host),
          h('div', { class: 'tvw-people' })
        )
      )
    )
    const tvb = (ic, he, fn, extra = {}, icls = '') => h('button', { class: 'tv-btn', type: 'button', onclick: fn, 'aria-label': he, ...extra }, icon(ic, icls), h('span', null, he))
    tvDrawBtn = tvb('pen', 'ציור', () => setTool(settings.tool === 'hand' ? 'pen' : 'hand'))
    tvFsBtn = tvb('fullscreen', 'מסך מלא', () => toggleFullscreen())
    tvBar = h('nav', { class: 'tv-bar', 'aria-label': 'שליטה בשלט · Remote' },
      tvb('fit', 'התאמה', () => fitContent(true, true)),
      tvb('plus', 'הגדלה', () => cv.view.zoomCenter(1.3)),
      tvb('minus', 'הקטנה', () => cv.view.zoomCenter(1 / 1.3)),
      tvDrawBtn,
      (tvUndoBtn = tvb('undo', 'ביטול', () => doUndo(), { title: 'ביטול הקו האחרון שלי · Undo (Ctrl+Z)' }, 'flip')),
      tvb('image', 'רקע', () => cycleBg()),
      tvb('qr', 'קוד גדול', () => toggleBigQR()),
      tvFsBtn,
      tvb('exit', 'יציאה', () => app.navigate('/b/' + code))
    )
    root.append(tvWelcome, tvCorner, tvBar)
    releaseWake = keepAwake()
    cleanups.push(() => releaseWake && releaseWake())
    // first visit: fullscreen hint (browsers require a user gesture for fullscreen)
    setTimeout(() => {
      if (!isFullscreen()) toast('לחצו OK על "מסך מלא" לתצוגה הכי גדולה', { timeout: 5000 })
    }, 1500)
  }

  let bigQR = false
  function toggleBigQR (force) {
    bigQR = force != null ? force : !bigQR
    root.classList.toggle('tv-big', bigQR)
  }

  // TV remote: idle-dim the bar; first key only wakes it
  let tvIdleT = 0
  const tvWake = () => {
    if (!tv) return false
    const wasIdle = root.classList.contains('tv-idle')
    root.classList.remove('tv-idle')
    clearTimeout(tvIdleT)
    tvIdleT = setTimeout(() => root.classList.add('tv-idle'), 9000)
    return wasIdle
  }
  if (tv) { tvWake(); cleanups.push(() => clearTimeout(tvIdleT)) }

  // ---------------------------------------------------------------- tools
  function paintTvDraw () {
    if (!tvDrawBtn) return
    const draw = settings.tool !== 'hand'
    tvDrawBtn.replaceChildren(icon(draw ? 'pen' : 'hand'), h('span', null, draw ? 'ציור' : 'הזזה'))
    tvDrawBtn.classList.toggle('on', draw)
    tvDrawBtn.setAttribute('aria-pressed', String(draw))
    tvDrawBtn.setAttribute('aria-label', draw ? 'מצב ציור · Draw (לחצו להזזה)' : 'מצב הזזה · Pan (לחצו לציור)')
    tvDrawBtn.title = draw ? 'ציור על המסך · Draw — לחיצה עוברת להזזה' : 'הזזת הלוח · Pan — לחיצה עוברת לציור'
  }

  function setTool (t) {
    if (!TOOLS[t]) return
    if (textEd.active && t !== 'text') textEd.commit()
    settings.tool = t
    selection.setTool(t) // [selection]
    if (!tv) saveSettings(settings)
    root.dataset.tool = t
    paintTvDraw()
    for (const [k, list] of toolBtns) for (const b of list) { b.classList.toggle('on', k === t); b.setAttribute('aria-pressed', String(k === t)) }
    const inGroup = GROUP_TOOLS.includes(t)
    groupBtn.classList.toggle('on', inGroup)
    groupBtn.querySelector('.gicon').replaceChildren(icon(inGroup ? TOOLS[t].icon : (TOOLS[settings.shape] ? TOOLS[settings.shape].icon : 'shapes')))
    if (['line', 'arrow', 'rect', 'ellipse'].includes(t)) { settings.shape = t; saveSettings(settings) }
    paintStyle()
    session.setPresenceField('tool', t)
    cv.requestFx()
  }

  function onToolClick (t, btn) {
    if (settings.tool === t && (t === 'eraser' || t === 'pen' || t === 'highlighter' || t === 'text' || ['line', 'arrow', 'rect', 'ellipse'].includes(t))) {
      openStyle(btn)
      return
    }
    setTool(t)
  }

  function openGroup () {
    const items = GROUP_TOOLS.map(t => {
      const T = TOOLS[t]
      const b = h('button', { class: 'pop-tool' + (settings.tool === t ? ' on' : ''), type: 'button', 'aria-label': label(T) },
        icon(T.icon), h('span', null, T.he))
      b.onclick = () => { setTool(t); closePopover() }
      return b
    })
    const fillToggle = h('button', { class: 'toggle-row', type: 'button', 'aria-pressed': String(!!settings.fill) },
      h('span', { class: 'tg-sw' + (settings.fill ? ' on' : '') }), h('span', null, 'מילוי לצורות · Fill shapes'))
    fillToggle.onclick = () => {
      settings.fill = !settings.fill; saveSettings(settings)
      fillToggle.querySelector('.tg-sw').classList.toggle('on', settings.fill)
      fillToggle.setAttribute('aria-pressed', String(settings.fill))
    }
    popover(groupBtn, h('div', { class: 'pop-group' }, h('div', { class: 'pop-tools' }, items), fillToggle), { placement: 'above' })
  }

  // ---------------------------------------------------------------- style (colour + width)
  function paintStyle () {
    const t = settings.tool
    const c = inkColor(settings.color, cv.dark)
    styleDot.style.setProperty('--c', c)
    const wk = widthKey(t)
    const [lo, hi] = WIDTH_RANGE[wk] || [1, 40]
    const w = settings.widths[wk] || 4
    const k = (w - lo) / Math.max(1, hi - lo)
    styleDot.style.setProperty('--s', (0.32 + 0.6 * k).toFixed(3))
    styleBtn.classList.toggle('is-eraser', t === 'eraser')
    paintSwatches()
  }

  function paintSwatches () {
    for (const b of document.querySelectorAll('.tb-swatches .swatch[data-c], .pop-style .swatch[data-c]')) {
      b.classList.toggle('sel', b.dataset.c === settings.color)
      b.style.setProperty('--ink', inkColor(b.dataset.c, cv.dark))
    }
  }

  function pickColor (c) {
    settings.color = c
    saveSettings(settings)
    if (settings.tool === 'select' && selection.items.size) selection.applyStyle({ color: c }) // [edit] recolour the selection
    if (['eraser', 'hand', 'laser'].includes(settings.tool)) setTool(settings.lastDraw || 'pen')
    paintStyle()
  }

  for (const p of PALETTE) {
    swatchRow.append(h('button', { class: 'swatch', type: 'button', dataset: { c: p.c }, style: { '--c': p.c }, 'aria-label': `${p.n} · ${p.en}`, title: `${p.n} · ${p.en}`, onclick: () => pickColor(p.c) }))
  }

  function openStyle (anchor = styleBtn) {
    if (settings.tool === 'select' && selection.styleTargets().length) return openSelStyle(anchor) // [edit]
    const t = settings.tool
    const wk = widthKey(t)
    const [lo, hi] = WIDTH_RANGE[wk] || [1, 40]
    const content = h('div', { class: 'pop-style' })
    if (t !== 'eraser') {
      const sw = h('div', { class: 'swatches' }, PALETTE.map(p =>
        h('button', { class: 'swatch big', type: 'button', dataset: { c: p.c }, style: { '--c': p.c }, 'aria-label': `${p.n} · ${p.en}`, title: p.n, onclick: () => { pickColor(p.c); preview() } })))
      const custom = h('input', { type: 'color', class: 'color-input', value: /^#[0-9a-f]{6}$/i.test(settings.color) ? settings.color : '#1e1e2e', 'aria-label': 'צבע מותאם · Custom color' })
      custom.addEventListener('input', () => { pickColor(custom.value); preview() })
      sw.append(h('label', { class: 'swatch big custom', title: 'צבע אחר · Custom' }, custom, icon('palette'), h('span', { class: 'cs-t' }, 'אחר')))
      content.append(h('div', { class: 'pop-label' }, 'צבע · Color'), sw)
    }
    const slider = h('input', { type: 'range', class: 'range', min: String(lo), max: String(hi), step: '1', value: String(settings.widths[wk] || lo), 'aria-label': 'עובי · Size' })
    const val = h('span', { class: 'range-val' }, '')
    const pv = h('canvas', { class: 'width-preview', width: '520', height: '120' })
    function preview () {
      const w = +slider.value
      val.textContent = t === 'text' ? `${w}px` : `${w}`
      const ctx = pv.getContext('2d')
      const dpr = 2
      ctx.setTransform(1, 0, 0, 1, 0, 0)
      ctx.clearRect(0, 0, pv.width, pv.height)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      const col = t === 'eraser' ? '#94a3b8' : inkColor(settings.color, false)
      if (t === 'text') {
        ctx.fillStyle = col
        ctx.font = `500 ${Math.min(w, 52)}px system-ui, sans-serif`
        ctx.textBaseline = 'middle'
        ctx.textAlign = 'center'
        ctx.fillText('שלום Hello', 130, 30)
        return
      }
      ctx.lineCap = 'round'; ctx.lineJoin = 'round'
      ctx.strokeStyle = col
      ctx.globalAlpha = t === 'highlighter' ? 0.4 : 1
      ctx.lineWidth = Math.min(w, 54)
      if (t === 'eraser') ctx.setLineDash([2, Math.max(4, w * 0.6)])
      ctx.beginPath()
      ctx.moveTo(24, 38)
      ctx.bezierCurveTo(80, -4, 150, 64, 236, 20)
      ctx.stroke()
      ctx.globalAlpha = 1
      ctx.setLineDash([])
    }
    slider.addEventListener('input', () => { settings.widths[wk] = +slider.value; saveSettings(settings); paintStyle(); preview() })
    content.append(
      h('div', { class: 'pop-label' }, t === 'text' ? 'גודל טקסט · Text size' : t === 'eraser' ? 'גודל מחק · Eraser size' : 'עובי · Size', val),
      h('div', { class: 'range-row' }, slider),
      pv
    )
    if (t === 'eraser') {
      const seg = h('div', { class: 'seg' },
        [['stroke', 'מחיקת קו שלם', 'Whole strokes'], ['pixel', 'מחיקה חופשית', 'Pixel eraser']].map(([m, he, en]) => {
          const b = h('button', { class: 'seg-btn' + (settings.eraserMode === m ? ' on' : ''), type: 'button', 'aria-pressed': String(settings.eraserMode === m) }, icon(m === 'stroke' ? 'eraserStroke' : 'eraserPixel'), h('span', null, he, h('small', null, en)))
          b.onclick = () => {
            settings.eraserMode = m; saveSettings(settings)
            for (const x of seg.children) { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', String(x === b)) }
          }
          return b
        }))
      content.append(h('div', { class: 'pop-label' }, 'סוג מחק · Eraser'), seg)
    }
    if (t === 'rect' || t === 'ellipse') {
      const fillToggle = h('button', { class: 'toggle-row', type: 'button', 'aria-pressed': String(!!settings.fill) },
        h('span', { class: 'tg-sw' + (settings.fill ? ' on' : '') }), h('span', null, 'מילוי · Fill'))
      fillToggle.onclick = () => {
        settings.fill = !settings.fill; saveSettings(settings)
        fillToggle.querySelector('.tg-sw').classList.toggle('on', settings.fill)
      }
      content.append(fillToggle)
    }
    popover(anchor, content, { placement: 'above', className: 'style-pop' })
    paintSwatches()
    preview()
  }

  // [edit] style popover for the current selection: colour, stroke width / text size and fill apply to it
  function openSelStyle (anchor) {
    const ms = selection.styleTargets()
    const first = ms[0]
    const ft = first.get('tool')
    const wk = widthKey(ft)
    const [lo, hi] = WIDTH_RANGE[wk] || [1, 40]
    const s = cv.view.s
    const cur = Math.round(Math.min(hi, Math.max(lo, (+first.get('width') || 4) * s)))
    const fc = String(first.get('color') || settings.color)
    const content = h('div', { class: 'pop-style' })
    const sw = h('div', { class: 'swatches' }, PALETTE.map(p =>
      h('button', { class: 'swatch big' + (p.c === fc ? ' sel' : ''), type: 'button', dataset: { c: p.c }, style: { '--c': p.c, '--ink': inkColor(p.c, cv.dark) }, 'aria-label': `${p.n} · ${p.en}`, title: p.n, onclick: () => { pickColor(p.c); for (const b of sw.querySelectorAll('.swatch[data-c]')) b.classList.toggle('sel', b.dataset.c === p.c) } })))
    const custom = h('input', { type: 'color', class: 'color-input', value: /^#[0-9a-f]{6}$/i.test(fc) ? fc : '#1e1e2e', 'aria-label': 'צבע מותאם · Custom color' })
    custom.addEventListener('input', () => pickColor(custom.value))
    sw.append(h('label', { class: 'swatch big custom', title: 'צבע אחר · Custom' }, custom, icon('palette'), h('span', { class: 'cs-t' }, 'אחר')))
    const slider = h('input', { type: 'range', class: 'range', min: String(lo), max: String(hi), step: '1', value: String(cur), 'aria-label': 'עובי · Size' })
    const val = h('span', { class: 'range-val' }, wk === 'text' ? `${cur}px` : String(cur))
    slider.addEventListener('input', () => {
      const v = +slider.value
      val.textContent = wk === 'text' ? `${v}px` : String(v)
      const w = +(v / cv.view.s).toFixed(3)
      selection.applyStyle(wk === 'text' ? { textSize: w } : { width: w })
    })
    content.append(
      h('div', { class: 'pop-label' }, `עיצוב ${ms.length} פריטים · Style selection`),
      h('div', { class: 'pop-label' }, 'צבע · Color'), sw,
      h('div', { class: 'pop-label' }, wk === 'text' ? 'גודל טקסט · Text size' : 'עובי קו · Stroke width', val),
      h('div', { class: 'range-row' }, slider)
    )
    if (ms.some(m => m.get('tool') === 'rect' || m.get('tool') === 'ellipse')) {
      let on = ms.some(m => m.get('fill'))
      const fillToggle = h('button', { class: 'toggle-row', type: 'button', 'aria-pressed': String(on) }, h('span', { class: 'tg-sw' + (on ? ' on' : '') }), h('span', null, 'מילוי · Fill'))
      fillToggle.onclick = () => {
        on = !on
        selection.applyStyle({ fill: on })
        fillToggle.querySelector('.tg-sw').classList.toggle('on', on)
        fillToggle.setAttribute('aria-pressed', String(on))
      }
      content.append(fillToggle)
    }
    popover(anchor, content, { placement: 'above', className: 'style-pop' })
  }

  // ---------------------------------------------------------------- undo / redo / clear
  const updUndo = () => {
    undoBtn.disabled = session.undo.undoStack.length === 0
    redoBtn.disabled = session.undo.redoStack.length === 0
    if (tvUndoBtn) {
      tvUndoBtn.classList.toggle('dim', undoBtn.disabled)
      tvUndoBtn.setAttribute('aria-disabled', String(undoBtn.disabled))
    }
  }
  for (const ev of ['stack-item-added', 'stack-item-popped', 'stack-cleared', 'stack-item-updated']) session.undo.on(ev, updUndo)
  input.ev.on('undo-changed', updUndo)
  function doUndo () { if (textEd.active) textEd.commit(); session.undo.undo(); updUndo() }
  function doRedo () { if (textEd.active) textEd.commit(); session.undo.redo(); updUndo() }

  async function clearBoard () {
    if (cv.isEmpty()) { toast('הלוח כבר ריק'); return }
    const ok = await confirmDialog({
      title: 'לנקות את הלוח?',
      text: 'כל הציורים יימחקו אצל כל המכשירים המחוברים. אפשר לבטל מיד אחרי (Ctrl+Z).',
      okLabel: 'ניקוי הלוח',
      danger: true,
      icon: 'trash'
    })
    if (!ok) return
    session.undo.stopCapturing()
    session.doc.transact(() => session.strokes.delete(0, session.strokes.length), session.LOCAL)
    session.undo.stopCapturing()
    updUndo()
    toast('הלוח נוקה', { actionLabel: 'ביטול', action: () => doUndo(), timeout: 6000 })
  }

  // ---------------------------------------------------------------- background / export
  function setBg (k) { setMeta('bg', k) }
  function cycleBg () {
    const cur = BG_KEYS.indexOf(cv.bgKey)
    const next = BG_KEYS[(cur + 1) % BG_KEYS.length]
    setBg(next)
    toast(`רקע: ${BG_INFO[next].he} · ${BG_INFO[next].en}`, { key: 'bg', timeout: 1400 })
  }

  async function exportPNG () {
    if (cv.isEmpty()) { toast('אין עדיין מה לייצא — ציירו משהו 🙂'); return }
    const out = renderToCanvas(session.strokes.toArray(), cv.bgKey, { maxDim: 4096, scale: 2 })
    const name = `couchboard-${code}-${new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-')}.png`
    const blob = await new Promise(resolve => out.toBlob(resolve, 'image/png'))
    if (!blob) { toast('הייצוא נכשל'); return }
    const file = typeof File === 'function' ? new File([blob], name, { type: 'image/png' }) : null
    if ((isIOS || (isTouch() && innerWidth < 700)) && file && navigator.canShare && navigator.canShare({ files: [file] })) {
      try { await navigator.share({ files: [file], title: titleOf() }); return } catch (e) { if (e && e.name === 'AbortError') return }
    }
    const url = URL.createObjectURL(blob)
    const a = h('a', { href: url, download: name, style: { display: 'none' } })
    document.body.append(a)
    a.click()
    a.remove()
    setTimeout(() => URL.revokeObjectURL(url), 4000)
    toast('התמונה נשמרה · PNG exported')
  }

  // ---------------------------------------------------------------- view
  const insets = () => {
    if (tv) {
      const r = tvCorner && !root.classList.contains('tv-empty') ? tvCorner.getBoundingClientRect() : null
      return { top: 16, bottom: 16 + (tvBar ? (tvBar.offsetHeight || 70) + 18 : 0), left: 16, right: r ? Math.min(r.width + 24, cv.W * 0.35) : 16 }
    }
    const top = topbar.getBoundingClientRect().bottom || 64
    const tbr = toolbar.getBoundingClientRect()
    return { top: top + 4, bottom: tbr.height ? cv.H - tbr.top + 4 : 80, left: 8, right: 8 }
  }
  function fitContent (animate = true, user = false) {
    const b = cv.contentBBox()
    if (!b) {
      const v = cv.view
      if (animate) v.animateTo(1, v.w / 2, v.h / 2, 320, user)
      else v.set(1, v.w / 2, v.h / 2, { user })
      return
    }
    const ins = insets()
    cv.view.fit(b, { padding: tv ? 40 : 36, insets: ins, maxScale: tv ? 4 : 1.5, animate, user })
  }

  const updZoom = () => { zoomPct.textContent = Math.round(cv.view.s * 100) + '%' }
  cv.view.ev.on('change', updZoom)
  const persistView = debounce(() => { if (!tv) saveView(code, cv.view.serialize()) }, 400)
  cv.view.ev.on('change', persistView)

  let fitted = false
  const savedView = tv ? null : getSavedView(code)
  if (savedView) { cv.view.restore(savedView); fitted = true } else cv.view.set(1, cv.W / 2, cv.H / 2)
  updZoom()

  // ---------------------------------------------------------------- recents + thumbnail
  const makeThumb = () => {
    try {
      const strokes = session.strokes.toArray()
      const c = renderToCanvas(strokes, cv.bgKey, { width: 360, height: 220, pad: 18, maxScale: 1.2 })
      let url = c.toDataURL('image/webp', 0.72)
      if (!url.startsWith('data:image/webp')) url = c.toDataURL('image/jpeg', 0.72)
      touchRecent(code, { thumb: url, title: session.meta.get('title') || '', n: strokes.length })
    } catch {}
  }
  const thumbSoon = debounce(makeThumb, 2500)
  touchRecent(code, {})
  cleanups.push(() => { thumbSoon.cancel(); makeThumb() })
  on(window, 'pagehide', () => makeThumb())

  // TV: keep content fitted as people draw (unless the remote/hand moved the camera recently)
  let localInteractAt = 0
  input.ev.on('interact', () => { localInteractAt = Date.now() })
  const tvRefit = debounce(() => {
    if (!tv) return
    if (Date.now() - cv.view.userMovedAt < 20000) return
    if (Date.now() - localInteractAt < 20000) return // drawing on the TV itself: never move the camera under the pen
    if (input.pointers.size) return
    fitContent(true)
  }, 650)

  const onContent = () => {
    const empty = cv.isEmpty()
    root.classList.toggle('is-empty', empty)
    if (tv) {
      root.classList.toggle('tv-empty', empty)
      tvRefit()
    }
    thumbSoon()
  }
  cv.onContent(onContent)

  session.whenLocal().then(() => {
    if (!fitted && !cv.isEmpty()) { fitContent(false); fitted = true }
    onContent()
    applyMeta()
  })
  session.on('server-synced', () => {
    onContent()
    if (!fitted && !cv.isEmpty() && Date.now() - cv.view.userMovedAt > 3000) { fitContent(true); fitted = true }
    if (tv) tvRefit()
    if (!session.meta.get('created')) setMeta('created', Date.now())
  })

  // ---------------------------------------------------------------- connection status
  let lastStatus = null
  function paintStatus (s) {
    lastStatus = s
    let key, he
    if (s.wsSynced) { key = 'online'; he = 'מחובר' }
    else if (s.p2p > 0) { key = 'p2p'; he = 'ישיר (p2p)' }
    else if (!s.online || s.ws === 'disconnected') { key = 'offline'; he = 'לא מקוון' }
    else { key = 'connecting'; he = 'מתחבר…' }
    if (key !== 'p2p' && s.p2p > 0) he += ` · p2p ${s.p2p}`
    statusDot.dataset.s = key
    statusText.textContent = he
    statusBtn.dataset.s = key
    root.dataset.net = key
    if (tvCount) paintTvCount()
  }
  session.on('status', paintStatus)
  paintStatus(session.status)
  // A friendly heads-up when the network goes away / comes back. While the server is down the websocket
  // flaps (disconnected -> connecting -> disconnected on every backoff retry), so the toast is tied to an
  // OFFLINE EPISODE, not to status flips: an episode starts when we are cut off and ends only when we are
  // really connected again (server synced or a p2p peer). One pending timer, at most one warning per
  // episode, a cooldown across episodes, and "back online" only after we actually said we were offline.
  const OFF_DELAY_MS = 4000
  const OFF_COOLDOWN_MS = 30000
  const isConnected = s => !!(s.wsSynced || s.p2p > 0)
  let offTimer = 0
  let offEpisode = false // warned (or chose not to) since the last real connection
  let offAnnounced = false // a warning was shown and not yet answered by "back online"
  let offToastClose = null
  let lastOffToastAt = -Infinity
  const cancelOffTimer = () => { clearTimeout(offTimer); offTimer = 0 }
  session.on('status', s => {
    if (isConnected(s)) {
      cancelOffTimer()
      offEpisode = false
      if (offToastClose) { offToastClose(); offToastClose = null }
      if (offAnnounced && s.wsSynced) {
        offAnnounced = false
        toast('חזרנו לרשת ✓ הכל מסונכרן', { key: 'net-back', timeout: 2200 })
      }
      return
    }
    const off = !s.online || s.ws === 'disconnected'
    if (!off || offTimer || offEpisode) return
    offTimer = setTimeout(() => {
      offTimer = 0
      if (isConnected(lastStatus || session.status)) return
      offEpisode = true
      if (Date.now() - lastOffToastAt < OFF_COOLDOWN_MS) return
      lastOffToastAt = Date.now()
      offAnnounced = true
      offToastClose = toast('אין חיבור — ממשיכים לצייר, הכל נשמר במכשיר ויסתנכרן אוטומטית', { key: 'net-off', timeout: 4500, kind: 'warn' })
    }, OFF_DELAY_MS)
  })
  cleanups.push(cancelOffTimer)

  function statusDetails () {
    const s = lastStatus || session.status
    const row = (ok, he, en, detail) => h('div', { class: 'srow' },
      h('span', { class: 'sdot', 'data-s': ok === true ? 'online' : ok === 'warn' ? 'connecting' : 'offline' }),
      h('span', { class: 'st' }, h('b', null, he), h('small', null, en)),
      h('span', { class: 'sv' }, detail))
    const body = h('div', { class: 'pop-status' },
      row(s.wsSynced ? true : s.ws === 'connecting' ? 'warn' : false, 'שרת', 'Server sync', s.wsSynced ? 'מסונכרן' : s.ws === 'connecting' ? 'מתחבר…' : 'מנותק'),
      row(s.p2p > 0 ? true : s.rtc ? 'warn' : false, 'חיבור ישיר', 'Peer-to-peer (WebRTC)', !s.rtc ? 'לא נתמך' : s.p2p > 0 ? `${s.p2p} מכשירים` : s.signaling ? 'מחפש…' : 'כבוי'),
      row(s.idb ? true : false, 'שמירה במכשיר', 'Saved on this device', s.idb ? 'פעיל' : 'לא זמין'),
      h('p', { class: 'fine' }, 'הלוח עובד גם בלי רשת. כל שינוי נשמר במכשיר ומסתנכרן ברגע שיש חיבור — דרך השרת או ישירות בין המכשירים.')
    )
    popover(statusBtn, body, { placement: 'below', className: 'status-pop' })
  }
  statusBtn.addEventListener('click', statusDetails)

  // ---------------------------------------------------------------- devices
  function paintUsers (list) {
    users = list
    const n = list.length
    devCount.textContent = String(n)
    devBtn.querySelector('.dlabel').textContent = n === 1 ? ' רק אני' : ' מחוברים'
    devAvatars.replaceChildren(...list.slice(0, 4).map(u => avatar(u, 22)))
    devBtn.classList.toggle('solo', n <= 1)
    if (tvCount) paintTvCount()
    if (tv && tvWelcome) {
      const ppl = tvWelcome.querySelector('.tvw-people')
      const others = list.filter(u => !u.self)
      ppl.replaceChildren(...(others.length
        ? [h('span', null, `${others.length} מחוברים:`), ...others.slice(0, 8).map(u => h('span', { class: 'tvw-p' }, avatar(u, 30), u.name))]
        : [h('span', { class: 'muted' }, 'מחכים לטלפון הראשון…')]))
    }
  }
  function paintTvCount () {
    const n = users.filter(u => !u.self).length
    tvCount.textContent = n ? `${n} מצטרפים · ${n} joined` : ''
    tvCount.classList.toggle('none', !n)
  }
  presence.ev.on('users', paintUsers)
  paintUsers(presence.users)

  function devicesPop () {
    const list = h('div', { class: 'dev-list' }, users.map(u =>
      h('div', { class: 'dev' + (u.self ? ' self' : '') },
        avatar(u, 34),
        h('span', { class: 'dev-n' }, h('b', null, u.name || '—'), h('small', null, `${KIND_EMOJI[u.kind] || '•'} ${KIND_NAME[u.kind] || ''}${u.self ? ' · אני' : ''}`)),
        u.self ? h('button', { class: 'btn small ghost', type: 'button', onclick: () => { closePopover(); editMe() } }, icon('edit'), 'שינוי') : null
      )))
    const body = h('div', { class: 'pop-devices' },
      h('div', { class: 'pop-label' }, `${users.length} ${users.length === 1 ? 'מכשיר' : 'מכשירים'} על הלוח · Devices`),
      list,
      h('button', { class: 'btn primary block', type: 'button', onclick: () => { closePopover(); openShare({ code, title: titleOf() }) } }, icon('qr'), 'הזמנת עוד מכשירים')
    )
    popover(devBtn, body, { placement: 'below', className: 'devices-pop' })
  }
  devBtn.addEventListener('click', devicesPop)

  function editMe () {
    openProfile(next => {
      Object.assign(me, { name: next.name, color: next.color })
      session.setPresence({ user: { name: me.name, color: me.color, kind: me.kind, id: me.id } })
      toast(`שלום ${me.name} 👋`)
    })
  }

  // ---------------------------------------------------------------- more menu
  function moreMenu () {
    const item = (ic, he, en, fn, cls = '') => h('button', { class: 'menu-item ' + cls, type: 'button', onclick: () => { closePopover(); fn() } },
      icon(ic), h('span', { class: 'mi-t' }, he, h('small', null, en)))
    const bgSeg = h('div', { class: 'seg bg-seg' }, BG_KEYS.map(k => {
      const b = h('button', { class: 'seg-btn' + (cv.bgKey === k ? ' on' : ''), type: 'button', 'aria-pressed': String(cv.bgKey === k), title: BG_INFO[k].en },
        h('span', { class: 'bg-thumb', dataset: { bg: k } }), h('span', null, BG_INFO[k].he))
      b.onclick = () => { setBg(k); for (const x of bgSeg.children) x.classList.toggle('on', x === b) }
      return b
    }))
    const fingerRow = h('button', { class: 'toggle-row', type: 'button', 'aria-pressed': String(settings.fingerDraws) },
      h('span', { class: 'tg-sw' + (settings.fingerDraws ? ' on' : '') }),
      h('span', null, 'ציור באצבע', h('small', null, 'כבוי = אצבע מזיזה, רק עט מצייר')))
    fingerRow.onclick = () => {
      settings.fingerDraws = !settings.fingerDraws; saveSettings(settings)
      fingerRow.querySelector('.tg-sw').classList.toggle('on', settings.fingerDraws)
    }
    const installable = canInstall() || canAddToHomeIOS() || (!isStandalone() && isTouch())
    const body = h('div', { class: 'menu' },
      h('div', { class: 'pop-label' }, 'רקע · Background'),
      bgSeg,
      h('div', { class: 'menu-sep' }),
      item('layers', 'שכבות', 'Layers', () => layersUI.openPanel(moreBtn)),
      item('image', 'הוספת תמונה', 'Add image', () => images && images.pick()),
      item('frame', 'שמירות וקבצים', 'Save as · Library · File', () => openSaves({ app, session, code, titleOf })), // [saves] hook
      item('download', 'שמירה כתמונה', 'Export PNG', exportPNG),
      item('tv', 'הצגה בטלוויזיה', 'Show on TV', showOnTv),
      item(isFullscreen() ? 'exitFullscreen' : 'fullscreen', isFullscreen() ? 'יציאה ממסך מלא' : 'מסך מלא', 'Fullscreen', () => toggleFullscreen()),
      installable && !isStandalone() ? item('install', 'התקנת האפליקציה', 'Install app', () => promptInstall()) : null,
      item('link', 'העתקת קישור', 'Copy link', () => copyBoardLink(code)),
      item('edit', 'השם והצבע שלי', `Me: ${me.name}`, editMe),
      isTouch() ? fingerRow : null,
      !isTouch() ? item('keyboard', 'קיצורי מקלדת', 'Keyboard shortcuts', showShortcuts) : null,
      h('div', { class: 'menu-sep' }),
      item('plus', 'לוח חדש', 'New board', () => app.newBoard()),
      item('trash', 'ניקוי הלוח', 'Clear board', clearBoard, 'danger')
    )
    popover(moreBtn, body, { placement: 'below', className: 'more-pop', sheetOnPhone: true })
  }
  moreBtn.addEventListener('click', moreMenu)

  function showOnTv () {
    openTvHelper({ code, title: titleOf(), onOpenHere: () => app.navigate(`/b/${code}?tv=1`) })
  }

  // top-bar actions
  shareBtn.addEventListener('click', () => openShare({ code, title: titleOf() }))
  codeBtn.addEventListener('click', () => openShare({ code, title: titleOf() }))
  tvBtn.addEventListener('click', showOnTv)
  fsBtn.addEventListener('click', () => toggleFullscreen())
  titleBtn.addEventListener('click', async () => {
    const v = await promptDialog({ title: 'שם הלוח · Board name', value: session.meta.get('title') || '', placeholder: `לוח ${code}`, maxLength: 48 })
    if (v != null) setMeta('title', v.trim())
  })
  const paintFs = () => {
    const fs = isFullscreen()
    fsBtn.replaceChildren(icon(fs ? 'exitFullscreen' : 'fullscreen'))
    root.classList.toggle('is-fs', fs)
    if (tvFsBtn) tvFsBtn.replaceChildren(icon(fs ? 'exitFullscreen' : 'fullscreen'), h('span', null, fs ? 'יציאה ממסך מלא' : 'מסך מלא'))
  }
  cleanups.push(onFullscreenChange(paintFs))
  cleanups.push(pwa.ev.on('change', () => {}))

  // ---------------------------------------------------------------- keyboard
  function showShortcuts () {
    const rows = [
      ['V', 'בחירה'], ['P', 'עט'], ['H', 'מרקר'], ['E', 'מחק'], ['L', 'קו'], ['A', 'חץ'], ['R', 'מלבן'], ['O', 'עיגול'], ['T', 'טקסט'], ['K', 'לייזר'],
      ['Space + גרירה', 'הזזת הלוח'], ['גלגלת / Ctrl+גלגלת', 'הזזה / זום'], ['1–8', 'צבעים'], ['[  ]', 'עובי'],
      ['Ctrl+C / X / V', 'העתקה / גזירה / הדבקה'], ['Ctrl+Z', 'ביטול'], ['Ctrl+Shift+Z / Ctrl+Y', 'חזרה'], ['+ / −', 'זום'], ['0', 'התאמה לתוכן'], ['Shift+0', 'זום 100%'], ['F', 'מסך מלא'], ['Shift+Del', 'ניקוי הלוח']
    ]
    modal({
      title: 'קיצורי מקלדת · Shortcuts',
      body: h('div', { class: 'shortcuts' }, rows.map(([k, d]) => h('div', { class: 'sc' }, h('kbd', { dir: 'ltr' }, k), h('span', null, d))))
    })
  }

  const onKeyDown = e => {
    if (tv) return onTvKey(e)
    if (anyModalOpen()) return
    const tgt = e.target
    if (isTypingTarget(tgt)) return
    const mod = e.ctrlKey || e.metaKey
    const k = e.key
    if (mod && (k === 'z' || k === 'Z')) { e.preventDefault(); e.shiftKey ? doRedo() : doUndo(); return }
    if (mod && (k === 'y' || k === 'Y')) { e.preventDefault(); doRedo(); return }
    if (mod && (k === '=' || k === '+')) { e.preventDefault(); cv.view.zoomCenter(1.25); return }
    if (mod && k === '-') { e.preventDefault(); cv.view.zoomCenter(1 / 1.25); return }
    if (mod && k === '0') { e.preventDefault(); cv.view.centerOn(...cv.view.toWorld(cv.W / 2, cv.H / 2), 1); return }
    if (mod || e.altKey) return
    if (k === ' ' && !e.repeat) {
      e.preventDefault()
      input.spaceDown = true
      root.classList.add('space-pan')
      return
    }
    if (k === 'Escape') { if (popoverOpen()) closePopover(); return }
    if ((k === 'Delete' || k === 'Backspace') && e.shiftKey) { e.preventDefault(); clearBoard(); return }
    const lower = k.length === 1 ? k.toLowerCase() : k
    const toolKey = { v: 'select', p: 'pen', h: 'highlighter', e: 'eraser', l: 'line', a: 'arrow', r: 'rect', o: 'ellipse', t: 'text', k: 'laser', m: 'hand' }[lower] ||
      // Hebrew keyboard layout positions (ר=P? no) — map physical keys via e.code
      { KeyV: 'select', KeyP: 'pen', KeyH: 'highlighter', KeyE: 'eraser', KeyL: 'line', KeyA: 'arrow', KeyR: 'rect', KeyO: 'ellipse', KeyT: 'text', KeyK: 'laser', KeyM: 'hand' }[e.code]
    if (toolKey) { e.preventDefault(); setTool(toolKey); return }
    if (/^[1-8]$/.test(k)) { e.preventDefault(); pickColor(PALETTE[+k - 1].c); return }
    if (k === '[' || k === ']' || e.code === 'BracketLeft' || e.code === 'BracketRight') {
      e.preventDefault()
      const wk = widthKey(settings.tool)
      const [lo, hi] = WIDTH_RANGE[wk]
      const cur = settings.widths[wk]
      const step = Math.max(1, Math.round(cur * 0.18))
      const dirUp = k === ']' || e.code === 'BracketRight'
      settings.widths[wk] = clamp(cur + (dirUp ? step : -step), lo, hi)
      saveSettings(settings)
      paintStyle()
      toast(`עובי: ${settings.widths[wk]}`, { key: 'width', timeout: 800 })
      return
    }
    if (k === '+' || k === '=') { e.preventDefault(); cv.view.zoomCenter(1.25); return }
    if (k === '-' || k === '_') { e.preventDefault(); cv.view.zoomCenter(1 / 1.25); return }
    if (k === '0' || k === ')') {
      e.preventDefault()
      if (e.shiftKey) cv.view.centerOn(...cv.view.toWorld(cv.W / 2, cv.H / 2), 1)
      else fitContent(true, true)
      return
    }
    if (lower === 'f' || e.code === 'KeyF') { e.preventDefault(); toggleFullscreen(); return }
    if (k === '?') { e.preventDefault(); showShortcuts() }
  }
  const onKeyUp = e => {
    if (e.key === ' ') { input.spaceDown = false; root.classList.remove('space-pan') }
  }
  on(document, 'keydown', onKeyDown)
  on(document, 'keyup', onKeyUp)
  on(window, 'blur', () => { input.spaceDown = false; root.classList.remove('space-pan') })

  function onTvKey (e) {
    const k = e.key
    if ((e.ctrlKey || e.metaKey) && !anyModalOpen() && !isTypingTarget(e.target)) {
      if (k === 'z' || k === 'Z') { e.preventDefault(); e.shiftKey ? doRedo() : doUndo(); return }
      if (k === 'y' || k === 'Y') { e.preventDefault(); doRedo(); return }
    }
    const code = e.keyCode || e.which
    const isBack = BACK_KEYS.has(k) || BACK_CODES.has(code)
    const isArrow = k && k.startsWith('Arrow')
    if (anyModalOpen()) return
    if (isTypingTarget(e.target)) return
    const woke = tvWake()
    if (isBack) {
      e.preventDefault()
      if (popoverOpen()) closePopover()
      else if (bigQR) toggleBigQR(false)
      else if (!woke) root.classList.add('tv-idle')
      return
    }
    if (isArrow || k === 'Enter' || k === ' ' || code === 13) {
      if (woke && !tvBar.contains(document.activeElement)) { e.preventDefault(); tvBar.querySelector('button').focus(); return }
      if (isArrow) {
        e.preventDefault()
        if (!tvBar.contains(document.activeElement)) { tvBar.querySelector('button').focus(); return }
        const dir = k.replace('Arrow', '').toLowerCase()
        spatialMove(tvBar, dir)
        return
      }
      if (!tvBar.contains(document.activeElement)) { e.preventDefault(); tvBar.querySelector('button').focus() }
      return
    }
    if (k === '+' || k === '=' || k === 'ChannelUp' || code === 427 || k === 'PageUp') { e.preventDefault(); cv.view.zoomCenter(1.3); return }
    if (k === '-' || k === 'ChannelDown' || code === 428 || k === 'PageDown') { e.preventDefault(); cv.view.zoomCenter(1 / 1.3); return }
    if (k === '0' || k === 'Home') { e.preventDefault(); fitContent(true, true); return }
    if (k === 'f' || k === 'F') { e.preventDefault(); toggleFullscreen() }
  }

  if (tv) {
    on(document, 'pointermove', () => tvWake())
    on(window, 'resize', () => tvRefit())
  }

  // ---------------------------------------------------------------- hints
  input.ev.on('pen-detected', () => {
    if (!seenOnce('pen-hint')) toast('✍️ זוהה עט — העט מצייר, אצבע מזיזה וזום (מניעת כף יד)', { timeout: 4200 })
  })
  input.ev.on('erased', n => { if (n > 0 && !seenOnce('erase-hint')) toast('המחק מוחק קווים שלמים · אפשר לשנות בלחיצה נוספת על המחק', { timeout: 3800 }) })
  if (!tv && isTouch() && !seenOnce('touch-hint')) {
    setTimeout(() => toast('אצבע אחת מציירת · שתי אצבעות מזיזות ומזמזמות', { timeout: 4200 }), 900)
  }

  // ---------------------------------------------------------------- go
  setTool(settings.tool)
  applyMeta()
  updUndo()
  paintFs()
  root.classList.add('is-empty')
  void root.offsetWidth // commit the start state so the fade-in still transitions
  root.classList.add('ready')

  function destroy () {
    closePopover()
    for (const fn of cleanups.splice(0)) { try { fn() } catch {} }
    try { session.meta.unobserve(applyMeta) } catch {}
    textEd.destroy()
    presence.destroy()
    if (images) images.destroy() // [images]
    layersUI.destroy() // [layers]
    selection.destroy() // [selection]
    input.destroy()
    cv.destroy()
    session.destroy()
  }

  return { destroy, session, canvas: cv }
}
