// Couch Board v2 — client entry. Tiny router: "/" home, "/b/<CODE>" board, "?tv=1" TV mode.
import './shim.js'
import { h, newCode, cleanCode, isValidCode } from './util.js'
import { openHome } from './home.js'
import { openBoard } from './board.js'
import { initPWA } from './pwa.js'
import { toast } from './ui.js'

const appEl = document.getElementById('app') || document.body.appendChild(h('div', { id: 'app' }))

let current = null

const app = {
  mount (el) {
    appEl.replaceChildren(el)
  },
  navigate (path, { replace = false } = {}) {
    const url = new URL(path, location.origin)
    if (url.pathname + url.search === location.pathname + location.search) { route(); return }
    if (replace) history.replaceState(null, '', url.pathname + url.search)
    else history.pushState(null, '', url.pathname + url.search)
    route()
  },
  newBoard () {
    const code = newCode()
    app.navigate('/b/' + code)
  }
}

function route () {
  if (current) { try { current.destroy() } catch (e) { console.warn(e) } current = null }
  window.scrollTo(0, 0)
  const params = new URLSearchParams(location.search)
  const m = location.pathname.match(/^\/b\/([^/?#]+)\/?$/)
  document.body.classList.remove('on-board', 'on-home', 'on-tv')
  if (m) {
    const code = cleanCode(decodeURIComponent(m[1]))
    if (!isValidCode(code)) {
      toast('קוד לוח לא תקין · Invalid board code')
      app.navigate('/', { replace: true })
      return
    }
    if (code !== m[1]) { history.replaceState(null, '', '/b/' + code + location.search); }
    const tv = params.get('tv') === '1' || (params.has('tv') && params.get('tv') !== '0')
    document.body.classList.add('on-board')
    if (tv) document.body.classList.add('on-tv')
    try {
      current = openBoard(app, code, { tv })
    } catch (e) {
      console.error('[couchboard] board failed to open', e)
      showCrash(e)
      return
    }
    window.__couchboard = current
    return
  }
  // legacy v1 links (?join=CODE) land on the matching board
  const legacy = cleanCode(params.get('join') || params.get('code') || '')
  if (legacy && isValidCode(legacy)) { app.navigate('/b/' + legacy, { replace: true }); return }
  if (location.pathname !== '/' && location.pathname !== '/index.html') history.replaceState(null, '', '/')
  document.body.classList.add('on-home')
  const autoNew = params.get('new') === '1'
  if (autoNew) history.replaceState(null, '', '/')
  current = openHome(app, { autoNew })
  window.__couchboard = null
}

function showCrash (e) {
  app.mount(h('div', { class: 'boot' },
    h('div', { class: 'boot-t' }, 'אופס — משהו השתבש'),
    h('div', { class: 'boot-s', dir: 'ltr' }, String((e && e.message) || e).slice(0, 160)),
    h('div', { style: { display: 'flex', gap: '10px', marginTop: '14px' } },
      h('button', { class: 'btn primary', type: 'button', onclick: () => location.reload() }, 'רענון'),
      h('button', { class: 'btn', type: 'button', onclick: () => app.navigate('/') }, 'למסך הבית'))
  ))
}

addEventListener('popstate', route)

// Same-origin <a href="/b/..."> links go through the router
document.addEventListener('click', e => {
  const a = e.target.closest && e.target.closest('a[href]')
  if (!a || a.target || a.hasAttribute('download') || e.metaKey || e.ctrlKey || e.shiftKey) return
  const url = new URL(a.href, location.href)
  if (url.origin !== location.origin) return
  if (url.pathname === '/' || url.pathname.startsWith('/b/')) { e.preventDefault(); app.navigate(url.pathname + url.search) }
})

// Keep a stable viewport height on mobile (address bar show/hide) for the board layout
const setVh = () => document.documentElement.style.setProperty('--vh', (window.visualViewport ? window.visualViewport.height : innerHeight) * 0.01 + 'px')
setVh()
addEventListener('resize', setVh)
if (window.visualViewport) visualViewport.addEventListener('resize', setVh)

initPWA()
route()
document.documentElement.classList.add('js-ready')
