// LAYERS — the renderer controller (per-layer offscreen surfaces + opacity) and the layers panel UI.
// Data model + operations live in layers.js. This file wires them into the canvas, input and selection.
//
// Rendering: every VISIBLE layer is painted on its own offscreen canvas (bottom-to-top) and composited
// onto the ink canvas with the layer's opacity, so a pixel-eraser stroke (destination-out) only erases
// inside the layer it was drawn on. Boards whose content all sits on one fully-opaque visible layer keep
// the original single-surface fast path (old boards render exactly as before).
import { getEntry, drawEntries, intersects } from './render.js'
import { h } from './util.js'
import { icon } from './icons.js'
import { toast, popover, closePopover, confirmDialog, promptDialog } from './ui.js'
import {
  BASE, MAX_LAYERS, layersMap, readLayers, layerOf, groupByLayer, isInteractive, getActiveId, saveActiveId,
  addLayer, setLayerProp, moveLayer, countInLayer, deleteLayer, moveToLayer, installLayers
} from './layers.js'

const CSS = `
.layers-pop { width: min(360px, calc(100vw - 16px)); padding: 10px; }
.lp-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.lp-head .pop-label { flex: 1; margin: 0; }
.layers-pop .lp-add { min-height: 44px; height: 44px; }
.lp-list { display: flex; flex-direction: column; gap: 4px; }
.lp-row { border-radius: 14px; border: 1px solid transparent; background: rgba(255,255,255,.03); }
.lp-row.on { border-color: rgba(139,92,246,.75); background: var(--accent-soft, rgba(139,92,246,.22)); }
.lp-main { display: flex; align-items: center; gap: 2px; min-height: 48px; padding: 2px; }
.lp-ib { width: 44px; height: 44px; flex: 0 0 44px; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center; color: var(--muted, #a6abc8); }
.lp-ib:hover { background: rgba(255,255,255,.08); color: var(--text, #eef0ff); }
.lp-ib.off { opacity: .45; }
.lp-ib.warn { color: #fbbf24; }
.lp-ib:disabled { opacity: .25; }
.lp-ib .ic { width: 20px; height: 20px; }
.lp-name { flex: 1; min-width: 0; min-height: 44px; display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  padding: 0 8px; text-align: start; border-radius: 12px; color: var(--text, #eef0ff); font-weight: 650; font-size: 14.5px; }
.lp-name span { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lp-name small { color: var(--muted, #a6abc8); font-weight: 500; font-size: 11.5px; }
.lp-row.hid .lp-name span { opacity: .55; }
.lp-more { display: flex; align-items: center; gap: 2px; flex-wrap: wrap; padding: 0 2px 4px; }
.lp-op { flex: 1 1 140px; display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 6px; font-size: 12.5px; color: var(--muted, #a6abc8); }
.lp-op input { flex: 1; min-width: 60px; accent-color: var(--accent, #8b5cf6); height: 32px; }
.lp-op b { min-width: 3.2em; text-align: center; color: var(--text, #eef0ff); font-weight: 650; }
.lp-ib.danger { color: #fb7185; }
.lp-foot { margin-top: 8px; font-size: 11.5px; color: var(--muted, #a6abc8); line-height: 1.4; }
.layers-btn .lyr-n { position: absolute; top: 4px; inset-inline-end: 4px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px;
  background: var(--accent, #8b5cf6); color: #fff; font-size: 10px; font-weight: 700; line-height: 16px; text-align: center; }
.layers-btn { position: relative; }
.sel-layers { display: flex; flex-direction: column; gap: 4px; min-width: 220px; }
.sel-layers button { min-height: 44px; display: flex; align-items: center; gap: 8px; padding: 0 12px; border-radius: 12px; color: var(--text, #eef0ff); text-align: start; }
.sel-layers button:hover { background: rgba(255,255,255,.08); }
.sel-layers button.on { background: var(--accent-soft, rgba(139,92,246,.22)); }
.sel-layers button:disabled { opacity: .4; }
`
let cssInjected = false
function injectCSS () {
  if (cssInjected) return
  cssInjected = true
  document.head.append(h('style', { id: 'layers-css' }, CSS))
}

export function installLayersUI ({ session, cv, input, selection, code }) {
  injectCSS()
  const lmap = layersMap(session.doc)
  let state = readLayers(lmap)
  let ver = 0
  let activeId = getActiveId(code)
  const active = () => (state.byId.has(activeId) ? activeId : BASE)
  const hook = installLayers(session, active)
  const listeners = new Set()
  const notify = () => { for (const fn of listeners) fn() }

  // ---------------------------------------------------------------- renderer controller
  const surfaces = new Map() // layer id -> { cv, ctx }
  let scratch = null
  let mode = 'fast'
  let pickCache = null
  const surface = (id, W, H) => {
    let s = surfaces.get(id)
    if (!s) { const c = document.createElement('canvas'); s = { cv: c, ctx: c.getContext('2d') }; surfaces.set(id, s) }
    if (s.cv.width !== W || s.cv.height !== H) { s.cv.width = W; s.cv.height = H }
    return s
  }
  const needsLayers = () => {
    // the original single surface is exact when nothing is hidden by a layer and at most one opaque layer has content
    const used = new Set()
    for (const m of cv.all) used.add(layerOf(state, m).id)
    if (used.size > 1) return true
    for (const id of used) { const l = state.byId.get(id); if (!l.visible || l.opacity < 1) return true }
    return false
  }
  const ctl = {
    pick (all) {
      if (pickCache && pickCache.all === all && pickCache.ver === ver) return pickCache.out
      const out = all.filter(m => isInteractive(state, m))
      pickCache = { all, ver, out }
      return out
    },
    visible (all) { return all.filter(m => layerOf(state, m).visible) },
    render (c, view, dpr, dark, cull) {
      const want = needsLayers() ? 'layers' : 'fast'
      if (want !== mode) { mode = want; c.dirtyStatic = true; c.staticValid = false }
      if (mode === 'fast') return false
      const ink = c.inkCtx
      const W = c.inkCv.width; const H = c.inkCv.height
      const groups = groupByLayer(c.all, state)
      const ids = new Set(groups.map(g => g.layer.id))
      for (const id of [...surfaces.keys()]) if (!ids.has(id)) surfaces.delete(id)
      if (c.dirtyStatic) {
        for (const g of groups) {
          const s = surface(g.layer.id, W, H)
          s.ctx.setTransform(1, 0, 0, 1, 0, 0)
          s.ctx.clearRect(0, 0, W, H)
          const ents = []
          for (const m of g.maps) if (!c.hidden.has(m) && !c.active.has(m)) ents.push(getEntry(m))
          drawEntries(s.ctx, ents, view, dpr, dark, cull)
        }
        c.dirtyStatic = false
      }
      ink.setTransform(1, 0, 0, 1, 0, 0)
      ink.globalCompositeOperation = 'source-over'
      ink.globalAlpha = 1
      ink.clearRect(0, 0, W, H)
      for (const g of groups) {
        const s = surface(g.layer.id, W, H)
        let src = s.cv
        const act = []
        if (c.active.size) for (const m of g.maps) if (c.active.has(m) && !c.hidden.has(m)) { const e = getEntry(m); if (e.bbox && intersects(e.bbox, cull)) act.push(e) }
        if (act.length) {
          if (!scratch) { const sc = document.createElement('canvas'); scratch = { cv: sc, ctx: sc.getContext('2d') } }
          if (scratch.cv.width !== W || scratch.cv.height !== H) { scratch.cv.width = W; scratch.cv.height = H }
          const x = scratch.ctx
          x.setTransform(1, 0, 0, 1, 0, 0)
          x.globalAlpha = 1
          x.globalCompositeOperation = 'copy'
          x.drawImage(s.cv, 0, 0)
          x.globalCompositeOperation = 'source-over'
          drawEntries(x, act, view, dpr, dark, null)
          src = scratch.cv
        }
        ink.globalAlpha = g.layer.opacity
        ink.drawImage(src, 0, 0)
      }
      ink.globalAlpha = 1
      return true
    }
  }
  cv.layers = ctl

  const refresh = () => {
    state = readLayers(lmap)
    ver++
    cv.dirtyStatic = true
    cv.schedule()
    // selection may not keep objects that just became hidden / locked
    if (selection && selection.items.size) {
      const keep = [...selection.items].filter(m => isInteractive(state, m))
      if (keep.length !== selection.items.size) selection.set(keep)
    }
    notify()
  }
  const onLayers = () => refresh()
  lmap.observeDeep(onLayers)
  const onStrokes = (events) => {
    ver++
    // a layerId change on an existing object moves it between surfaces
    for (const ev of events) if (ev.keysChanged && ev.keysChanged.has('layerId')) { cv.dirtyStatic = true; cv.schedule() }
    notify()
  }
  session.strokes.observeDeep(onStrokes)

  // ---------------------------------------------------------------- drawing guard (locked / hidden active layer)
  const DRAW_TOOLS = new Set(['pen', 'highlighter', 'eraser', 'line', 'arrow', 'rect', 'ellipse', 'text'])
  input.canDraw = (tool, eraserMode) => {
    if (!DRAW_TOOLS.has(tool)) return true
    if (tool === 'eraser' && eraserMode === 'stroke') return true // erases whole objects in unlocked visible layers only
    const l = state.byId.get(active())
    if (l.locked) { toast(`🔒 השכבה "${l.name}" נעולה — פתחו אותה או בחרו שכבה אחרת`, { key: 'layer-guard', timeout: 2600 }); return false }
    if (!l.visible) { toast(`👁 השכבה "${l.name}" מוסתרת — הציגו אותה כדי לצייר עליה`, { key: 'layer-guard', timeout: 2600 }); return false }
    return true
  }

  // ---------------------------------------------------------------- active layer
  function setActive (id) {
    activeId = state.byId.has(id) ? id : BASE
    saveActiveId(code, activeId)
    notify()
  }

  // ---------------------------------------------------------------- panel
  let pop = null
  let body = null
  let holdRender = false
  function openPanel (anchor) {
    body = h('div', { class: 'lp' })
    renderPanel()
    pop = popover(anchor, body, { placement: 'auto', className: 'layers-pop', sheetOnPhone: true, onClose: () => { pop = null; body = null } })
  }

  function renderPanel () {
    if (!body || holdRender) return
    const cur = active()
    const list = state.list.slice().reverse() // top layer first, like Photoshop
    const rows = list.map(l => {
      const n = countInLayer(session, l.id)
      const on = l.id === cur
      const ib = (ic, label, fn, cls = '', disabled = false) => {
        const b = h('button', { class: 'lp-ib ' + cls, type: 'button', 'aria-label': label, title: label, disabled }, icon(ic))
        b.addEventListener('click', e => { e.stopPropagation(); fn() })
        return b
      }
      const eye = ib(l.visible ? 'eye' : 'eyeOff', l.visible ? 'הסתרה · Hide' : 'הצגה · Show', () => setLayerProp(session, l.id, 'visible', !l.visible), l.visible ? '' : 'off')
      eye.setAttribute('aria-pressed', String(l.visible))
      const lock = ib(l.locked ? 'lock' : 'unlock', l.locked ? 'שחרור נעילה · Unlock' : 'נעילה · Lock', () => setLayerProp(session, l.id, 'locked', !l.locked), l.locked ? 'warn' : 'off')
      lock.setAttribute('aria-pressed', String(l.locked))
      const name = h('button', { class: 'lp-name', type: 'button', 'aria-label': `שכבה פעילה: ${l.name}`, 'aria-pressed': String(on) },
        h('span', null, l.name), h('small', null, `${n} פריטים${l.opacity < 1 ? ` · ${Math.round(l.opacity * 100)}%` : ''}${l.locked ? ' · נעולה' : ''}${!l.visible ? ' · מוסתרת' : ''}`))
      name.addEventListener('click', () => setActive(l.id))
      name.addEventListener('dblclick', () => rename(l))
      const row = h('div', { class: 'lp-row' + (on ? ' on' : '') + (l.visible ? '' : ' hid'), dataset: { layer: l.id } }, h('div', { class: 'lp-main' }, eye, lock, name))
      if (on) {
        const stack = state.list.filter(x => !x.base)
        const i = stack.findIndex(x => x.id === l.id)
        const slider = h('input', { type: 'range', min: '0', max: '100', step: '5', value: String(Math.round(l.opacity * 100)), 'aria-label': 'שקיפות · Opacity' })
        const val = h('b', null, Math.round(l.opacity * 100) + '%')
        slider.addEventListener('pointerdown', () => { holdRender = true })
        slider.addEventListener('input', () => { val.textContent = slider.value + '%'; holdRender = true; setLayerProp(session, l.id, 'opacity', +slider.value / 100) })
        slider.addEventListener('change', () => { holdRender = false; renderPanel() })
        slider.addEventListener('pointerup', () => { if (holdRender) { holdRender = false; setTimeout(renderPanel, 0) } })
        row.append(h('div', { class: 'lp-more' },
          h('label', { class: 'lp-op' }, 'שקיפות', slider, val),
          ib('chevronUp', 'הזזה למעלה · Move up', () => moveLayer(session, l.id, +1), '', l.base || i >= stack.length - 1),
          ib('chevronDown', 'הזזה למטה · Move down', () => moveLayer(session, l.id, -1), '', l.base || i <= 0),
          ib('edit', 'שינוי שם · Rename', () => rename(l)),
          ib('trash', 'מחיקת שכבה · Delete layer', () => remove(l), 'danger', l.base)
        ))
      }
      return row
    })
    const add = h('button', { class: 'btn small primary lp-add', type: 'button', disabled: state.list.length >= MAX_LAYERS }, icon('plus'), 'שכבה חדשה')
    add.addEventListener('click', () => {
      const id = addLayer(session)
      if (!id) { toast(`אפשר עד ${MAX_LAYERS} שכבות`); return }
      state = readLayers(lmap)
      setActive(id)
      input.ev.emit('undo-changed')
    })
    body.replaceChildren(
      h('div', { class: 'lp-head' }, h('div', { class: 'pop-label' }, 'שכבות · Layers'), add),
      h('div', { class: 'lp-list', role: 'list' }, rows),
      h('div', { class: 'lp-foot' }, 'ציורים חדשים נכנסים לשכבה המסומנת. שכבה נעולה לא ניתנת לציור, מחיקה או הזזה.')
    )
    if (pop) pop.place()
  }
  listeners.add(renderPanel)

  async function rename (l) {
    const v = await promptDialog({ title: 'שם השכבה · Layer name', value: l.name, maxLength: 40 })
    if (v != null && v.trim()) setLayerProp(session, l.id, 'name', v.trim())
  }

  async function remove (l) {
    if (l.base) return
    const n = countInLayer(session, l.id)
    const ok = await confirmDialog({
      title: `למחוק את "${l.name}"?`,
      text: n ? `השכבה ו-${n} הפריטים שבה יימחקו אצל כל המכשירים. אפשר לבטל מיד (Ctrl+Z).` : 'השכבה הריקה תימחק. אפשר לבטל (Ctrl+Z).',
      okLabel: 'מחיקת השכבה',
      danger: true,
      icon: 'trash'
    })
    if (!ok) return
    deleteLayer(session, l.id)
    if (activeId === l.id) setActive(BASE)
    input.ev.emit('undo-changed')
    toast('השכבה נמחקה', { actionLabel: 'ביטול', action: () => { session.undo.undo(); input.ev.emit('undo-changed') }, timeout: 6000 })
  }

  // ---------------------------------------------------------------- "move to layer" for the selection bar
  function openMoveTo (anchor, maps) {
    const cur = maps.length ? layerOf(state, maps[0]).id : null
    const same = maps.every(m => layerOf(state, m).id === cur)
    const list = state.list.slice().reverse().map(l => {
      const b = h('button', { type: 'button', class: same && l.id === cur ? 'on' : '', disabled: l.locked || !l.visible },
        icon(l.locked ? 'lock' : 'layers'), h('span', null, l.name))
      b.addEventListener('click', () => {
        closePopover()
        moveToLayer(session, maps, l.id)
        input.ev.emit('undo-changed')
        toast(`הועבר ל"${l.name}"`, { key: 'sel', timeout: 1400 })
      })
      return b
    })
    const newBtn = h('button', { type: 'button', disabled: state.list.length >= MAX_LAYERS }, icon('plus'), h('span', null, 'לשכבה חדשה'))
    newBtn.addEventListener('click', () => {
      closePopover()
      const id = addLayer(session)
      if (!id) return
      moveToLayer(session, maps, id)
      input.ev.emit('undo-changed')
      toast('הועבר לשכבה חדשה', { key: 'sel', timeout: 1400 })
    })
    popover(anchor, h('div', null, h('div', { class: 'pop-label' }, 'העברה לשכבה · Move to layer'), h('div', { class: 'sel-layers' }, list, newBtn)), { placement: 'auto', className: 'sel-layers-pop' })
  }

  return {
    get state () { return state },
    activeId: active,
    setActive,
    openPanel,
    openMoveTo,
    onChange (fn) { listeners.add(fn); return () => listeners.delete(fn) },
    destroy () {
      try { lmap.unobserveDeep(onLayers) } catch {}
      try { session.strokes.unobserveDeep(onStrokes) } catch {}
      hook.destroy()
      cv.layers = null
      listeners.clear()
      input.canDraw = null
    }
  }
}
