// One board = one Y.Doc, synced by three providers at once:
//   y-indexeddb (this device, offline) + y-websocket (our server, reliable) + y-webrtc (p2p bonus).
import * as Y from 'yjs'
import { IndexeddbPersistence } from 'y-indexeddb'
import { WebsocketProvider } from 'y-websocket'
import { WebrtcProvider } from 'y-webrtc'
import * as awarenessProtocol from 'y-protocols/awareness'
import { ROOM_PREFIX, wsOrigin, emitter } from './util.js'

const hasRTC = () => typeof RTCPeerConnection !== 'undefined' && typeof RTCDataChannel !== 'undefined'

// ICE: host candidates only by default (same Wi-Fi = the couch case; no external STUN service).
// Opt in to a public STUN server for cross-network p2p with ?stun=1 — the websocket path always works anyway.
function iceServers () {
  try {
    if (new URLSearchParams(location.search).get('stun') === '1') return [{ urls: ['stun:stun.l.google.com:19302'] }]
  } catch {}
  return []
}

export function createSession (code, me) {
  const room = ROOM_PREFIX + code
  const doc = new Y.Doc()
  const strokes = doc.getArray('strokes')
  const meta = doc.getMap('meta')
  const LOCAL = { local: true, code } // transaction origin for this device's edits (undo scope)
  const awareness = new awarenessProtocol.Awareness(doc)
  const ev = emitter()

  const status = {
    idb: false, // local copy loaded
    ws: 'connecting', // 'connecting' | 'connected' | 'disconnected'
    wsSynced: false,
    signaling: false,
    p2p: 0, // connected webrtc peers
    rtc: hasRTC(),
    online: navigator.onLine !== false
  }
  const emitStatus = () => ev.emit('status', { ...status })

  // ---- 1. IndexedDB (instant, offline)
  let idb = null
  try {
    idb = new IndexeddbPersistence(room, doc)
    idb.on('synced', () => { status.idb = true; emitStatus(); ev.emit('local-ready') })
  } catch (e) {
    console.warn('[couchboard] IndexedDB unavailable', e)
    status.idb = false
    setTimeout(() => ev.emit('local-ready'), 0)
  }

  // ---- 2. y-websocket to our own server (same origin, wss on https)
  const ws = new WebsocketProvider(wsOrigin() + '/yjs', room, doc, { awareness, maxBackoffTime: 4000, resyncInterval: 20000 })
  ws.on('status', e => { status.ws = e.status; if (e.status !== 'connected') status.wsSynced = false; emitStatus() })
  ws.on('sync', s => { status.wsSynced = !!s; emitStatus(); if (s) ev.emit('server-synced') })
  ws.on('connection-error', () => { status.ws = 'disconnected'; emitStatus() })

  // ---- 3. y-webrtc p2p (bonus; never required)
  let rtc = null
  if (status.rtc) {
    try {
      rtc = new WebrtcProvider(room, doc, {
        signaling: [wsOrigin() + '/signal'],
        awareness,
        maxConns: 16,
        filterBcConns: true,
        peerOpts: { config: { iceServers: iceServers() } }
      })
      rtc.on('peers', () => countPeers())
    } catch (e) {
      console.warn('[couchboard] WebRTC disabled', e)
      rtc = null
      status.rtc = false
    }
  }
  const countPeers = () => {
    let n = 0
    let sig = false
    try {
      if (rtc && rtc.room) for (const c of rtc.room.webrtcConns.values()) if (c.connected) n++
      if (rtc) sig = rtc.signalingConns.some(c => c.connected)
    } catch {}
    if (n !== status.p2p || sig !== status.signaling) { status.p2p = n; status.signaling = sig; emitStatus() }
  }
  const peerTimer = setInterval(countPeers, 2000)

  const onOnline = () => { status.online = navigator.onLine !== false; emitStatus(); if (status.online) { try { ws.connect() } catch {} } }
  addEventListener('online', onOnline)
  addEventListener('offline', onOnline)

  // ---- undo/redo: only this device's own edits
  const undo = new Y.UndoManager([strokes], { trackedOrigins: new Set([LOCAL]), captureTimeout: 400 })

  // ---- awareness (presence)
  awareness.setLocalState({ user: { name: me.name, color: me.color, kind: me.kind, id: me.id } })
  const setPresence = patch => {
    const cur = awareness.getLocalState() || {}
    awareness.setLocalState({ ...cur, ...patch })
  }
  const setPresenceField = (k, v) => {
    try { awareness.setLocalStateField(k, v) } catch {}
  }
  const onHide = () => { try { awarenessProtocol.removeAwarenessStates(awareness, [doc.clientID], 'pagehide') } catch {} }
  const onShow = e => {
    if (e.persisted || !awareness.getLocalState()) {
      awareness.setLocalState({ user: { name: me.name, color: me.color, kind: me.kind, id: me.id } })
    }
  }
  addEventListener('pagehide', onHide)
  addEventListener('pageshow', onShow)

  let destroyed = false
  function destroy () {
    if (destroyed) return
    destroyed = true
    clearInterval(peerTimer)
    removeEventListener('online', onOnline)
    removeEventListener('offline', onOnline)
    removeEventListener('pagehide', onHide)
    removeEventListener('pageshow', onShow)
    try { awarenessProtocol.removeAwarenessStates(awareness, [doc.clientID], 'leave') } catch {}
    try { undo.destroy() } catch {}
    try { if (rtc) rtc.destroy() } catch {}
    try { ws.destroy() } catch {}
    try { awareness.destroy() } catch {}
    try { if (idb) idb.destroy() } catch {}
    try { doc.destroy() } catch {}
  }

  return {
    code,
    room,
    doc,
    strokes,
    meta,
    awareness,
    undo,
    LOCAL,
    status,
    on: ev.on,
    setPresence,
    setPresenceField,
    get ws () { return ws },
    get rtc () { return rtc },
    whenLocal: () => new Promise(resolve => {
      if (!idb || status.idb) return resolve()
      const off = ev.on('local-ready', () => { off(); resolve() })
    }),
    whenServer: (ms = 2500) => new Promise(resolve => {
      if (status.wsSynced) return resolve(true)
      const t = setTimeout(() => { off(); resolve(false) }, ms)
      const off = ev.on('server-synced', () => { clearTimeout(t); off(); resolve(true) })
    }),
    destroy
  }
}
